```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>🎬 YouTube Archive Engine V5</title>
<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='8' fill='%230a0e14'/%3E%3Cpath d='M12 8l10 8-10 8z' fill='%23ff3b5c'/%3E%3C/svg%3E" />
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@fontsource/inter@5.0.18/index.css" />
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@fontsource/jetbrains-mono@5.0.20/index.css" />
<style>
  :root{
    --bg:#070a0f; --bg2:#0a0e14; --panel:#0f151f; --panel2:#131b27; --line:#1e2836;
    --line2:#263344; --txt:#e6edf6; --mut:#8296ad; --dim:#5b6b80;
    --red:#ff3b5c; --red2:#ff6b3d; --cy:#22d3ee; --gr:#2ee6a8; --am:#ffb020; --vi:#a78bfa; --bl:#4da3ff;
    --r:14px; --sh:0 10px 30px rgba(0,0,0,.45);
  }
  *{box-sizing:border-box;margin:0;padding:0}
  html,body{height:100%}
  body{
    background:
      radial-gradient(1200px 600px at 85% -10%, rgba(255,59,92,.13), transparent 60%),
      radial-gradient(900px 500px at 0% 0%, rgba(34,211,238,.10), transparent 55%),
      var(--bg);
    color:var(--txt); font-family:'Inter',system-ui,-apple-system,sans-serif;
    font-size:14px; line-height:1.45; -webkit-font-smoothing:antialiased;
  }
  ::-webkit-scrollbar{width:10px;height:10px}
  ::-webkit-scrollbar-track{background:transparent}
  ::-webkit-scrollbar-thumb{background:#22303f;border-radius:8px;border:2px solid transparent;background-clip:padding-box}
  ::-webkit-scrollbar-thumb:hover{background:#31445a;background-clip:padding-box}
  button,input,select,textarea{font-family:inherit;font-size:inherit;color:inherit}
  button{cursor:pointer;border:none;background:none}
  a{color:var(--cy);text-decoration:none}
  .mono{font-family:'JetBrains Mono',ui-monospace,Menlo,monospace}

  /* ---------- layout ---------- */
  .wrap{max-width:1560px;margin:0 auto;padding:18px 20px 60px}
  .topbar{
    display:flex;align-items:center;gap:16px;flex-wrap:wrap;
    padding:14px 18px;border:1px solid var(--line);border-radius:var(--r);
    background:linear-gradient(180deg,rgba(255,255,255,.035),rgba(255,255,255,0)) , var(--panel);
    box-shadow:var(--sh); position:sticky; top:10px; z-index:40; backdrop-filter:blur(14px);
  }
  .brand{display:flex;align-items:center;gap:12px;min-width:0}
  .logo{width:42px;height:42px;border-radius:11px;flex:0 0 auto;display:grid;place-items:center;
    background:linear-gradient(140deg,#1b2432,#0c1119);border:1px solid #263344;box-shadow:0 0 0 1px rgba(255,59,92,.18),0 6px 18px rgba(255,59,92,.18)}
  .logo svg{width:24px;height:24px;filter:drop-shadow(0 0 6px rgba(255,59,92,.55))}
  .brand h1{font-size:16px;font-weight:700;letter-spacing:-.2px;white-space:nowrap}
  .brand p{font-size:11.5px;color:var(--mut);white-space:nowrap}
  .top-spacer{flex:1 1 auto}
  .pill{
    display:inline-flex;align-items:center;gap:7px;padding:6px 12px;border-radius:999px;
    border:1px solid var(--line2);background:#0c121b;font-size:12px;font-weight:600;color:var(--mut);white-space:nowrap
  }
  .dot{width:8px;height:8px;border-radius:50%;background:var(--dim);box-shadow:0 0 0 3px rgba(255,255,255,.04)}
  .dot.on{background:var(--gr);box-shadow:0 0 10px var(--gr);animation:beat 1.8s infinite}
  .dot.off{background:var(--red);box-shadow:0 0 10px var(--red)}
  .dot.demo{background:var(--am);box-shadow:0 0 10px var(--am);animation:beat 1.4s infinite}
  @keyframes beat{0%,100%{opacity:1}50%{opacity:.45}}

  /* ---------- buttons ---------- */
  .btn{
    display:inline-flex;align-items:center;gap:8px;padding:9px 14px;border-radius:10px;
    border:1px solid var(--line2);background:#111a25;color:var(--txt);font-weight:600;font-size:13px;
    transition:transform .12s ease,background .18s,border-color .18s,box-shadow .18s; white-space:nowrap
  }
  .btn:hover{background:#17222f;border-color:#33475e;transform:translateY(-1px)}
  .btn:active{transform:translateY(0) scale(.985)}
  .btn svg{width:15px;height:15px;flex:0 0 auto}
  .btn.primary{background:linear-gradient(135deg,var(--red),#e01e46);border-color:#ff5a76;color:#fff;box-shadow:0 6px 20px rgba(255,59,92,.30)}
  .btn.primary:hover{background:linear-gradient(135deg,#ff4e6c,#f02a52)}
  .btn.ghost{background:transparent}
  .btn.danger{border-color:#5a2231;color:#ff8ea1;background:#1a1015}
  .btn.danger:hover{background:#25141b;border-color:#7d2c3d}
  .btn.warn{border-color:#5a4520;color:#ffd07a;background:#1a1610}
  .btn.warn:hover{background:#241d12}
  .btn.sm{padding:6px 10px;font-size:12px;border-radius:8px}
  .btn:disabled{opacity:.4;cursor:not-allowed;transform:none}
  .iconbtn{width:30px;height:30px;border-radius:8px;display:grid;place-items:center;border:1px solid var(--line2);background:#101923;transition:.16s}
  .iconbtn svg{width:14px;height:14px}
  .iconbtn:hover{background:#18242f;border-color:#3a4f68;transform:translateY(-1px)}
  .iconbtn.red:hover{border-color:#7d2c3d;color:var(--red)}
  .iconbtn.amber:hover{border-color:#6d5522;color:var(--am)}
  .iconbtn.green:hover{border-color:#1f6b52;color:var(--gr)}

  /* ---------- cards ---------- */
  .grid{display:grid;gap:14px;margin-top:14px}
  .g4{grid-template-columns:repeat(4,minmax(0,1fr))}
  .g3{grid-template-columns:1.35fr 1fr 1fr}
  .card{
    border:1px solid var(--line);border-radius:var(--r);background:var(--panel);
    padding:16px 18px;position:relative;overflow:hidden;transition:border-color .2s,transform .2s
  }
  .card:hover{border-color:var(--line2)}
  .card .k{font-size:11px;text-transform:uppercase;letter-spacing:.09em;color:var(--dim);font-weight:700;display:flex;align-items:center;gap:7px}
  .card .v{font-size:28px;font-weight:700;letter-spacing:-.8px;margin-top:6px;font-family:'JetBrains Mono',monospace}
  .card .s{font-size:11.5px;color:var(--mut);margin-top:2px}
  .card .glow{position:absolute;inset:auto -30% -70% auto;width:190px;height:190px;border-radius:50%;filter:blur(46px);opacity:.22;pointer-events:none}
  .card .ico{width:22px;height:22px;border-radius:6px;display:grid;place-items:center;background:#16202c;border:1px solid var(--line2)}
  .card .ico svg{width:12px;height:12px}

  .bar{height:6px;border-radius:99px;background:#182231;overflow:hidden}
  .bar > i{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,var(--red),var(--red2));transition:width .5s cubic-bezier(.4,0,.2,1)}
  .bar.cy > i{background:linear-gradient(90deg,#0ea5c4,var(--cy))}
  .bar.gr > i{background:linear-gradient(90deg,#12b981,var(--gr))}
  .bar.vi > i{background:linear-gradient(90deg,#7c5cf0,var(--vi))}

  /* throughput */
  .th-head{display:flex;align-items:flex-end;gap:14px;flex-wrap:wrap}
  .th-speed{font-size:34px;font-weight:800;letter-spacing:-1.2px;font-family:'JetBrains Mono',monospace;
    background:linear-gradient(90deg,#fff,#ffb9c6);-webkit-background-clip:text;background-clip:text;color:transparent}
  .th-cap{font-size:12px;color:var(--mut);padding-bottom:8px}
  #spark{width:100%;height:74px;display:block;margin-top:10px}
  .th-foot{display:flex;gap:18px;flex-wrap:wrap;margin-top:10px;padding-top:12px;border-top:1px dashed var(--line2)}
  .th-foot div{font-size:11.5px;color:var(--mut)}
  .th-foot b{display:block;color:var(--txt);font-size:14px;font-family:'JetBrains Mono',monospace;margin-top:2px}

  /* gauge */
  .gauge-wrap{display:flex;align-items:center;gap:16px}
  .gauge{position:relative;width:104px;height:104px;flex:0 0 auto}
  .gauge svg{transform:rotate(-90deg)}
  .gauge .lbl{position:absolute;inset:0;display:grid;place-items:center;text-align:center}
  .gauge .lbl b{font-size:19px;font-family:'JetBrains Mono',monospace;display:block}
  .gauge .lbl span{font-size:9.5px;color:var(--dim);text-transform:uppercase;letter-spacing:.08em}
  .kv{font-size:12px;color:var(--mut);display:flex;justify-content:space-between;gap:10px;padding:4px 0;border-bottom:1px dashed rgba(255,255,255,.05)}
  .kv:last-child{border-bottom:none}
  .kv b{color:var(--txt);font-family:'JetBrains Mono',monospace;font-weight:600}

  /* workers */
  .workers{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}
  .wk{font-size:10.5px;font-family:'JetBrains Mono',monospace;padding:4px 8px;border-radius:7px;border:1px solid var(--line2);background:#0d141d;color:var(--dim);
    max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;transition:.2s}
  .wk.busy{border-color:#2c5c4c;background:#0d1f19;color:var(--gr);box-shadow:0 0 12px rgba(46,230,168,.12)}
  .wk.conv{border-color:#3d3470;background:#14112a;color:var(--vi)}
  .wk.err{border-color:#6d2434;background:#1d0f14;color:#ff8ea1}
  .wk.wait{border-color:#5a4520;background:#1a1610;color:var(--am)}

  /* ---------- toolbar ---------- */
  .toolbar{
    margin-top:14px;border:1px solid var(--line);border-radius:var(--r);background:var(--panel);
    padding:12px;display:flex;gap:10px;align-items:center;flex-wrap:wrap;box-shadow:var(--sh)
  }
  .sep{width:1px;height:26px;background:var(--line2)}
  .search{display:flex;align-items:center;gap:8px;background:#0b1119;border:1px solid var(--line2);border-radius:10px;padding:0 12px;min-width:220px;flex:1 1 220px;max-width:340px}
  .search svg{width:14px;height:14px;color:var(--dim);flex:0 0 auto}
  .search input{background:none;border:none;outline:none;padding:9px 0;width:100%;font-size:13px}
  .chips{display:flex;gap:6px;flex-wrap:wrap}
  .chip{padding:6px 11px;border-radius:999px;border:1px solid var(--line2);background:#0d141d;color:var(--mut);font-size:11.5px;font-weight:600;transition:.16s}
  .chip:hover{color:var(--txt);border-color:#3a4f68}
  .chip.on{background:linear-gradient(135deg,rgba(255,59,92,.22),rgba(255,107,61,.16));border-color:#7d2c3d;color:#ffd7de}
  .selbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:9px 12px;margin-top:10px;border-radius:12px;
    border:1px solid #2f4a63;background:linear-gradient(90deg,rgba(34,211,238,.09),rgba(34,211,238,.02));animation:slideDown .22s ease}
  .selbar b{font-family:'JetBrains Mono',monospace;color:var(--cy)}
  @keyframes slideDown{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:none}}

  /* ---------- tabs ---------- */
  .panel{margin-top:14px;border:1px solid var(--line);border-radius:var(--r);background:var(--panel);overflow:hidden;box-shadow:var(--sh)}
  .tabs{display:flex;gap:2px;padding:10px 12px 0;border-bottom:1px solid var(--line);background:#0c121b;flex-wrap:wrap;align-items:center}
  .tab{padding:9px 15px;border-radius:10px 10px 0 0;color:var(--mut);font-weight:600;font-size:13px;display:flex;align-items:center;gap:8px;
    border:1px solid transparent;border-bottom:none;position:relative;top:1px;transition:.16s}
  .tab:hover{color:var(--txt);background:rgba(255,255,255,.03)}
  .tab.on{color:#fff;background:var(--panel);border-color:var(--line)}
  .tab.on::after{content:"";position:absolute;left:12px;right:12px;top:-1px;height:2px;border-radius:2px;background:linear-gradient(90deg,var(--red),var(--red2))}
  .tab .cnt{font-size:10.5px;padding:1px 7px;border-radius:99px;background:#1b2735;color:var(--mut);font-family:'JetBrains Mono',monospace}
  .tab.on .cnt{background:#2a1620;color:#ff9db0}
  .tabs .right{margin-left:auto;display:flex;gap:8px;align-items:center;padding-bottom:8px}

  /* ---------- table ---------- */
  .tbl-wrap{overflow:auto;max-height:min(62vh,720px)}
  table{width:100%;border-collapse:separate;border-spacing:0}
  thead th{
    position:sticky;top:0;z-index:5;background:#0d141d;text-align:left;font-size:10.5px;text-transform:uppercase;letter-spacing:.08em;
    color:var(--dim);font-weight:700;padding:11px 12px;border-bottom:1px solid var(--line);white-space:nowrap
  }
  tbody td{padding:11px 12px;border-bottom:1px solid rgba(30,40,54,.7);vertical-align:middle}
  tbody tr{transition:background .15s}
  tbody tr:hover{background:rgba(255,255,255,.025)}
  tbody tr.sel{background:rgba(34,211,238,.06)}
  tbody tr.rowin{animation:fadeUp .3s ease}
  @keyframes fadeUp{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:none}}
  .ttl{font-weight:600;font-size:13px;color:var(--txt);display:block;max-width:430px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
  .meta{font-size:11px;color:var(--dim);margin-top:2px;display:flex;gap:8px;flex-wrap:wrap;font-family:'JetBrains Mono',monospace}
  .meta span{display:inline-flex;align-items:center;gap:4px}
  .prog-cell{min-width:170px}
  .prog-top{display:flex;justify-content:space-between;gap:8px;font-size:11px;color:var(--mut);font-family:'JetBrains Mono',monospace;margin-bottom:5px}
  .prog-top b{color:var(--txt)}
  .shimmer{position:relative;overflow:hidden}
  .shimmer > i::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,transparent,rgba(255,255,255,.35),transparent);animation:sh 1.4s infinite}
  @keyframes sh{from{transform:translateX(-100%)}to{transform:translateX(100%)}}
  .badge{display:inline-flex;align-items:center;gap:6px;padding:4px 10px;border-radius:99px;font-size:11px;font-weight:700;white-space:nowrap;border:1px solid}
  .badge i{width:6px;height:6px;border-radius:50%;background:currentColor}
  .b-dl{color:#7cc4ff;border-color:#24486b;background:#0e1a26}
  .b-q{color:#9fb2c8;border-color:#2b3a4d;background:#111a24}
  .b-ok{color:#5ff0bd;border-color:#1f6b52;background:#0b1f18}
  .b-er{color:#ff95a8;border-color:#7d2c3d;background:#1d0f14}
  .b-ps{color:#ffd07a;border-color:#6d5522;background:#1a1610}
  .b-cv{color:#c4b3ff;border-color:#453a7d;background:#14102a}
  .b-dl i{animation:beat 1.2s infinite}
  .num{font-family:'JetBrains Mono',monospace;font-size:12.5px;white-space:nowrap}
  .num.mut{color:var(--mut)}
  .acts{display:flex;gap:6px;justify-content:flex-end}
  input[type=checkbox]{appearance:none;width:16px;height:16px;border-radius:5px;border:1.5px solid #33475e;background:#0b1119;cursor:pointer;position:relative;transition:.15s;flex:0 0 auto}
  input[type=checkbox]:hover{border-color:#4f6b8a}
  input[type=checkbox]:checked{background:linear-gradient(135deg,var(--red),#e01e46);border-color:#ff5a76}
  input[type=checkbox]:checked::after{content:"";position:absolute;left:4.5px;top:1px;width:5px;height:9px;border:solid #fff;border-width:0 2px 2px 0;transform:rotate(42deg)}
  .empty{padding:52px 20px;text-align:center;color:var(--dim)}
  .empty svg{width:38px;height:38px;opacity:.4;margin-bottom:10px}
  .empty h3{font-size:14px;color:var(--mut);font-weight:600;margin-bottom:4px}

  /* logs */
  .term{background:#070b10;border-top:1px solid var(--line);padding:12px 14px;height:min(58vh,620px);overflow:auto;
    font-family:'JetBrains Mono',monospace;font-size:12px;line-height:1.75}
  .term .ln{white-space:pre-wrap;word-break:break-word;padding:1px 0;border-radius:4px}
  .term .ln:hover{background:rgba(255,255,255,.03)}
  .t-err{color:#ff8ea1}.t-warn{color:#ffd07a}.t-ok{color:#5ff0bd}.t-info{color:#93a6bd}.t-dim{color:#4d5c6e}
  .logbar{display:flex;gap:8px;align-items:center;padding:10px 12px;border-bottom:1px solid var(--line);background:#0c121b;flex-wrap:wrap}
  .switch{display:inline-flex;align-items:center;gap:8px;font-size:12px;color:var(--mut);cursor:pointer;user-select:none}
  .switch input{appearance:none;width:32px;height:18px;border-radius:99px;background:#1c2735;border:1px solid var(--line2);position:relative;transition:.2s;cursor:pointer}
  .switch input::after{content:"";position:absolute;top:2px;left:2px;width:12px;height:12px;border-radius:50%;background:#6b7f96;transition:.2s}
  .switch input:checked{background:rgba(46,230,168,.22);border-color:#1f6b52}
  .switch input:checked::after{left:16px;background:var(--gr)}

  /* failed cards */
  .fail-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(340px,1fr));gap:12px;padding:14px}
  .fcard{border:1px solid #3a2029;border-radius:12px;background:linear-gradient(180deg,#160f14,#110c10);padding:13px 14px;transition:.2s}
  .fcard:hover{border-color:#6d2c3d;transform:translateY(-2px)}
  .fcard h4{font-size:13px;font-weight:600;margin-bottom:6px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
  .fcard .err{font-family:'JetBrains Mono',monospace;font-size:11px;color:#ff9db0;background:#1d0f14;border:1px solid #3a1c26;border-radius:8px;padding:8px 10px;
    max-height:74px;overflow:auto;word-break:break-word;margin:8px 0}
  .fcard .row{display:flex;gap:8px;align-items:center;justify-content:space-between}

  /* modal */
  .overlay{position:fixed;inset:0;background:rgba(4,7,11,.72);backdrop-filter:blur(6px);z-index:80;display:none;align-items:center;justify-content:center;padding:20px}
  .overlay.on{display:flex;animation:fadeIn .18s ease}
  @keyframes fadeIn{from{opacity:0}to{opacity:1}}
  .modal{width:100%;max-width:600px;border:1px solid var(--line2);border-radius:16px;background:var(--panel2);box-shadow:0 30px 80px rgba(0,0,0,.7);
    animation:pop .24s cubic-bezier(.2,.9,.3,1.2);max-height:90vh;display:flex;flex-direction:column}
  @keyframes pop{from{opacity:0;transform:translateY(14px) scale(.97)}to{opacity:1;transform:none}}
  .modal header{padding:16px 18px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:10px}
  .modal header h2{font-size:15px;font-weight:700}
  .modal header p{font-size:11.5px;color:var(--mut)}
  .modal .body{padding:18px;overflow:auto}
  .modal footer{padding:14px 18px;border-top:1px solid var(--line);display:flex;gap:10px;justify-content:flex-end;background:#0c121b}
  .field{margin-bottom:14px}
  .field label{display:block;font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--dim);font-weight:700;margin-bottom:6px}
  .field input,.field select,.field textarea{
    width:100%;background:#0a1017;border:1px solid var(--line2);border-radius:10px;padding:10px 12px;outline:none;transition:.16s;font-size:13px}
  .field textarea{min-height:92px;resize:vertical;font-family:'JetBrains Mono',monospace;font-size:12px;line-height:1.6}
  .field input:focus,.field select:focus,.field textarea:focus{border-color:#3f7fa8;box-shadow:0 0 0 3px rgba(34,211,238,.12)}
  .hint{font-size:11px;color:var(--dim);margin-top:6px}
  .optgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px}
  .opt{display:flex;align-items:center;gap:9px;padding:10px 12px;border:1px solid var(--line2);border-radius:10px;background:#0a1017;cursor:pointer;transition:.16s;font-size:12.5px}
  .opt:hover{border-color:#3a4f68}
  .banner{margin-top:14px;border:1px solid #6d5522;background:linear-gradient(90deg,rgba(255,176,32,.12),rgba(255,176,32,.03));
    color:#ffd07a;border-radius:12px;padding:10px 14px;font-size:12.5px;display:none;align-items:center;gap:10px}
  .banner.on{display:flex}

  /* toasts */
  .toasts{position:fixed;right:18px;bottom:18px;z-index:120;display:flex;flex-direction:column;gap:9px;max-width:360px}
  .toast{border:1px solid var(--line2);border-radius:11px;background:#111a25;padding:11px 14px;box-shadow:0 14px 40px rgba(0,0,0,.55);
    font-size:12.5px;display:flex;gap:10px;align-items:flex-start;animation:tin .26s cubic-bezier(.2,.9,.3,1.15)}
  .toast.out{animation:tout .25s forwards}
  @keyframes tin{from{opacity:0;transform:translateX(28px)}to{opacity:1;transform:none}}
  @keyframes tout{to{opacity:0;transform:translateX(28px)}}
  .toast b{display:block;font-size:12.5px;margin-bottom:2px}
  .toast span{color:var(--mut);font-size:11.5px;word-break:break-word}
  .toast .bar-l{width:3px;border-radius:3px;align-self:stretch;background:var(--cy)}
  .toast.ok .bar-l{background:var(--gr)}.toast.err .bar-l{background:var(--red)}.toast.warn .bar-l{background:var(--am)}

  .spin{animation:rot 1s linear infinite}
  @keyframes rot{to{transform:rotate(360deg)}}
  .foot{margin-top:22px;text-align:center;color:var(--dim);font-size:11.5px}
  .foot code{font-family:'JetBrains Mono',monospace;color:var(--mut)}

  @media(max-width:1180px){.g4{grid-template-columns:repeat(2,1fr)}.g3{grid-template-columns:1fr}}
  @media(max-width:760px){
    .wrap{padding:12px 12px 44px}.g4{grid-template-columns:1fr 1fr}.topbar{position:static}
    .brand p{display:none}.th-speed{font-size:26px}.card .v{font-size:22px}
  }
  @media(max-width:520px){.g4{grid-template-columns:1fr}}
</style>
</head>
<body>
<div class="wrap">

  <!-- ============ TOP BAR ============ -->
  <div class="topbar">
