    <div class="pill" id="pausePill" style="display:none;border-color:#6d5522;color:#ffd07a;background:#1a1610">
      <svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="5" width="4" height="14" rx="1"/><rect x="14" y="5" width="4" height="14" rx="1"/></svg>
      <span id="pauseReason">PAUSED</span>
    </div>
    <button class="btn primary" id="btnAdd">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg>
      Add Playlist / Channel
    </button>
  </div>

  <div class="banner" id="demoBanner">
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 9v4m0 4h.01M10.3 3.9L2.6 17.2A2 2 0 004.3 20h15.4a2 2 0 001.7-2.8L13.7 3.9a2 2 0 00-3.4 0z"/></svg>
    <span><b>Demo mode</b> — engine API at <code class="mono">/api/*</code> unreachable. Showing simulated live data so every control stays interactive.</span>
  </div>

  <!-- ============ STAT CARDS ============ -->
  <div class="grid g4">
    <div class="card">
      <div class="glow" style="background:#4da3ff"></div>
      <div class="k"><span class="ico"><svg viewBox="0 0 24 24" fill="none" stroke="#7cc4ff" stroke-width="2.2"><path d="M4 6h16M4 12h16M4 18h10"/></svg></span>Total Jobs</div>
      <div class="v" id="stTotal">0</div>
      <div class="s"><span id="stQueued">0</span> in queue · <span id="stActive">0</span> downloading now</div>
      <div class="bar cy" style="margin-top:10px"><i id="barQueue" style="width:0%"></i></div>
    </div>
    <div class="card">
      <div class="glow" style="background:#2ee6a8"></div>
      <div class="k"><span class="ico"><svg viewBox="0 0 24 24" fill="none" stroke="#5ff0bd" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6L9 17l-5-5"/></svg></span>Completed</div>
      <div class="v" id="stDone">0</div>
      <div class="s" id="stDoneSub">0% of archive · 0 B written</div>
      <div class="bar gr" style="margin-top:10px"><i id="barDone" style="width:0%"></i></div>
    </div>
    <div class="card">
      <div class="glow" style="background:#ff3b5c"></div>
      <div class="k"><span class="ico"><svg viewBox="0 0 24 24" fill="none" stroke="#ff95a8" stroke-width="2.2" stroke-linecap="round"><path d="M12 8v5m0 3.5h.01"/><circle cx="12" cy="12" r="9"/></svg></span>Failed</div>
      <div class="v" id="stFailed">0</div>
      <div class="s">Requires attention · <span id="stRetries">0</span> retries used</div>
      <div class="bar" style="margin-top:10px"><i id="barFail" style="width:0%"></i></div>
    </div>
    <div class="card">
      <div class="glow" style="background:#a78bfa"></div>
      <div class="k"><span class="ico"><svg viewBox="0 0 24 24" fill="none" stroke="#c4b3ff" stroke-width="2.2" stroke-linecap="round"><path d="M12 3v12m0 0l-4-4m4 4l4-4M4 19h16"/></svg></span>Queue Position</div>
      <div class="v" id="stPos">--</div>
      <div class="s">Next up: <span id="stNext" class="mono" style="color:var(--mut)">idle</span></div>
      <div class="s" style="margin-top:6px">Global ETA <b class="mono" id="stEta" style="color:var(--txt)">--</b></div>
    </div>
  </div>

  <!-- ============ THROUGHPUT / STORAGE / SYSTEM ============ -->
  <div class="grid g3">
    <div class="card">
      <div class="k"><span class="ico"><svg viewBox="0 0 24 24" fill="none" stroke="#ff9db0" stroke-width="2.2" stroke-linecap="round"><path d="M13 2L4.5 13H11l-1 9 8.5-11H12l1-9z"/></svg></span>Aggregate Throughput</div>
      <div class="th-head" style="margin-top:8px">
