      <canvas id="spark"></canvas>
      <div class="th-foot">
        <div>Active workers<b id="thWorkers">0 / 0</b></div>
        <div>Avg per worker<b id="thAvg">0 B/s</b></div>
        <div>Peak (5m)<b id="thPeak">0 B/s</b></div>
        <div>Converted<b id="thConv">0</b></div>
