              stroke-dasharray="276.5" stroke-dashoffset="276.5" style="transition:stroke-dashoffset .7s cubic-bezier(.4,0,.2,1)"/>
            <defs><linearGradient id="gg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#2ee6a8"/><stop offset="1" stop-color="#22d3ee"/></linearGradient></defs>
