<div class="toasts" id="toasts"></div>

<script>
/* =========================================================================
   YouTube Archive Engine V5 — Web UI
   Talks to the Bun backend in batch_playlist_downloader.ts.
   Falls back to a fully-simulated demo engine when /api/* is unreachable.
   ========================================================================= */
const $  = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => Array.from(r.querySelectorAll(s));

/* ---------- formatting helpers ---------- */
const UNITS = ['B', 'KB', 'MB', 'GB', 'TB', 'PB'];
function fmtBytes(n) {
  n = Number(n) || 0;
  if (n <= 0) return '0 B';
  let i = 0, v = n;
  while (v >= 1024 && i < UNITS.length - 1) { v /= 1024; i++; }
  return `${v >= 100 ? v.toFixed(0) : v.toFixed(1)} ${UNITS[i]}`;
}
function fmtSpeed(bps) { return (Number(bps) > 0 ? fmtBytes(bps) : '0 B') + '/s'; }
function fmtDur(s) {
  s = Number(s) || 0;
  if (s <= 0) return '--';
  if (s < 60) return `${Math.round(s)}s`;
  if (s < 3600) return `${Math.floor(s / 60)}m ${Math.round(s % 60)}s`;
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60);
  return `${h}h ${m}m`;
}
function parseSpeed(str) {
  if (typeof str === 'number') return str;
  const m = String(str || '').match(/([\d.]+)\s*([KMGT]?i?B)/i);
  if (!m) return 0;
  const mult = { B: 1, KB: 1024, MB: 1024 ** 2, GB: 1024 ** 3, TB: 1024 ** 4 };
  return parseFloat(m[1]) * (mult[m[2].toUpperCase().replace('IB', 'B')] || 1);
}
function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }
function ts(d = new Date()) { return d.toTimeString().slice(0, 8); }
function shortId(id) { const s = String(id || ''); return s.length > 11 ? s.slice(0, 11) : s; }

/* ---------- toasts ---------- */
function toast(title, msg = '', type = 'info', ms = 3800) {
  const el = document.createElement('div');
  el.className = `toast ${type}`;
  el.innerHTML = `<div class="bar-l"></div><div style="flex:1"><b>${esc(title)}</b>${msg ? `<span>${esc(msg)}</span>` : ''}</div>`;
  $('#toasts').appendChild(el);
  setTimeout(() => { el.classList.add('out'); setTimeout(() => el.remove(), 260); }, ms);
}
/* ---------- confirm dialog ---------- */
let cfResolve = null;
function confirmDialog(title, msg, okLabel = 'Confirm') {
  $('#cfTitle').textContent = title; $('#cfMsg').innerHTML = msg; $('#cfOk').textContent = okLabel;
  $('#ovConfirm').classList.add('on');
  return new Promise(res => { cfResolve = res; });
}
function closeConfirm(val) { $('#ovConfirm').classList.remove('on'); if (cfResolve) { cfResolve(val); cfResolve = null; } }
$('#cfOk').onclick = () => closeConfirm(true);
$$('[data-close]').forEach(b => b.onclick = () => {
  $('#' + b.dataset.close).classList.remove('on');
  if (b.dataset.close === 'ovConfirm') closeConfirm(false);
});
$$('.overlay').forEach(o => o.addEventListener('click', e => {
  if (e.target === o) { o.classList.remove('on'); if (o.id === 'ovConfirm') closeConfirm(false); }
}));

/* =========================================================================
   DEMO ENGINE (used when the real backend is offline)
   ========================================================================= */
const demo = {
  jobs: [], history: [], logs: { error: [], report: [] },
  paused: false, pauseReason: null, started: Date.now() - 1000 * 60 * 47,
  disk: { freeGB: 1843.2, totalGB: 3815.0 }, memGB: 6.4, memTotalGB: 32,
  target: 4, maxWorkers: 5, converts: 2, capKBps: 0,
  folders: ['Linus Tech Tips', 'Veritasium', 'Fireship', 'Wendover Productions'],
  titles: [
    'Why Every Data Center Is Moving To Liquid Cooling', 'The Impossible Physics of Black Holes',
    'God-Tier TypeScript in 100 Seconds', 'How Airlines Secretly Price Their Seats',
    'I Built a 100TB NAS for $900', 'The Largest Structure Ever Constructed',
    'Rust Is Eating The Web', 'Why Trains Are Absurdly Efficient',
    'Testing the Cheapest 4K Camera on the Market', 'The Math Behind Perfect Shuffles',
    'This $5 Chip Runs Your Whole House', 'Why Nations Fight Over Sand',
    'Docker But It Actually Makes Sense', 'The Airport That Should Not Exist',
    'Overclocking a 1998 Pentium in 2025', 'How Scientists Weigh a Planet',
    'The Framework Laptop 5 Review', 'Why Some Bridges Sing in the Wind',
    'CSS Has Finally Won', 'The Economics of Empty Cargo Ships',
    'Rebuilding a Dead GPU With Hot Air', 'The Deep Sea Cable Map Explained',
    'SQLite Is a Web Server Now?', 'Why High-Speed Rail Keeps Failing',
    'Silence Is Expensive: Studio Acoustics', 'The Battery Breakthrough Nobody Believed',
    'Bun vs Node: A Brutally Honest Benchmark', 'The Forgotten Engineering of Venice'
  ],
  errors: [
    'ERROR: [youtube] Unable to extract video signature — yt-dlp needs an update',
    'HTTP Error 429: Too Many Requests (rate limited, backing off)',
    'ERROR: fragment 47 not found after 10 retries; incomplete download',
    'ERROR: Unable to download video: connection reset by peer',
    'FFmpeg remux failed: moov atom not found in source file',
    'ERROR: Video unavailable — members-only content requires cookies'
  ],
  init() {
    let k = 0;
    for (let i = 0; i < 26; i++) {
      const folder = this.folders[i % this.folders.length];
      const est = Math.round((90 + Math.random() * 720) * 1024 * 1024);
      const id = this.rid();
      const r = Math.random();
      let ds = 'downloaded', cs = 'done', prog = 100, speed = 0, eta = 0, retry = 0, err = null;
      if (r < 0.16) { ds = 'downloading'; cs = 'pending'; prog = 4 + Math.random() * 78; speed = (3 + Math.random() * 14) * 1048576; eta = est * (1 - prog / 100) / speed; }
      else if (r < 0.34) { ds = 'pending'; cs = 'pending'; prog = 0; }
      else if (r < 0.40) { ds = 'paused'; cs = 'pending'; prog = 10 + Math.random() * 60; }
      else if (r < 0.47) { ds = 'failed'; cs = 'pending'; prog = 0; retry = 1 + Math.floor(Math.random() * 3); err = this.errors[Math.floor(Math.random() * this.errors.length)]; }
      else if (r < 0.53) { ds = 'downloaded'; cs = 'in_progress'; prog = 100; }
      this.jobs.push({
        id, url: `https://www.youtube.com/watch?v=${id}`, title: this.titles[i % this.titles.length],
        folder, index: ++k, download_status: ds, conversion_status: cs, progress: prog,
        speed, eta, file_size: ds === 'downloaded' ? est : 0, est, retry_count: retry,
        last_error: err, created_at: new Date(Date.now() - (26 - i) * 420000).toISOString(), ticks: 0
      });
    }
    for (let h = 6; h >= 1; h--) {
      const dl = 8 + Math.floor(Math.random() * 40), sk = Math.floor(Math.random() * 60), fl = Math.floor(Math.random() * 4);
      const dur = 300 + Math.random() * 5400;
      this.history.push({
        id: h, started_at: new Date(Date.now() - h * 7200000).toISOString(),
        ended_at: new Date(Date.now() - h * 7200000 + dur * 1000).toISOString(),
        duration_seconds: dur, downloaded: dl, skipped: sk, failed: fl, total_queued: dl + sk + fl
      });
    }
    const seed = [
      ['info', 'Engine V5 started. Resilient, autonomous, proxy-free.'],
      ['ok', 'Cookies validated against youtube.com (200 OK).'],
      ['info', 'Database ready — WAL journal, busy_timeout 5000ms.'],
      ['ok', 'Reconciled 2 crashed job(s) back to paused/pending.'],
      ['info', 'Network monitor started (15s interval).'],
      ['info', 'Autoscaler: target 4 workers, min 1, max 5.'],
      ['warn', 'Worker DL3 throttled — aggregate speed exceeded soft cap.'],
      ['err', 'Job 8fK2mQzX1pA failed: HTTP Error 429: Too Many Requests'],
      ['ok', 'yt-dlp auto-updated to 2025.01.15 — retrying signature-challenged jobs.'],
      ['info', 'Web UI listening on http://127.0.0.1:3000']
    ];
    seed.forEach(([lv, m], i) => this.push(lv === 'err' ? 'error' : 'report', lv, m, Date.now() - (seed.length - i) * 41000));
    this.push('error', 'err', 'Job 8fK2mQzX1pA failed: HTTP Error 429: Too Many Requests');
    this.push('error', 'warn', 'Corrupt fragment detected on 014 - Why Nations Fight Over Sand — deleted .part and requeued.');
    this.push('error', 'err', 'FFmpeg remux failed: moov atom not found (009 - Testing the Cheapest 4K Camera)');
  },
  rid() {
    const c = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-';
    let s = ''; for (let i = 0; i < 11; i++) s += c[Math.floor(Math.random() * c.length)];
    return s;
  },
  push(stream, level, msg, when) {
    const line = `[${ts(when ? new Date(when) : new Date())}] [${level.toUpperCase()}] ${msg}`;
    this.logs[stream].push(line);
    if (this.logs[stream].length > 400) this.logs[stream].shift();
  },
  tick() {
    if (this.paused) { this.jobs.forEach(j => { if (j.download_status === 'downloading') j.speed = 0; }); return; }
    const active = this.jobs.filter(j => j.download_status === 'downloading');
    for (const j of active) {
      j.speed = Math.max(0.8 * 1048576, Math.min(22 * 1048576, j.speed + (Math.random() - 0.48) * 2.4 * 1048576));
      j.progress = Math.min(100, j.progress + (j.speed / j.est) * 100);
      j.eta = (j.est * (1 - j.progress / 100)) / j.speed;
      if (Math.random() < 0.0016) {
        j.download_status = 'failed'; j.retry_count++; j.progress = 0; j.speed = 0;
        j.last_error = this.errors[Math.floor(Math.random() * this.errors.length)];
        this.push('error', 'err', `Job ${j.id} failed (attempt ${j.retry_count}): ${j.last_error}`);
        continue;
      }
      if (j.progress >= 100) {
        j.download_status = 'downloaded'; j.conversion_status = 'in_progress'; j.file_size = j.est; j.speed = 0; j.eta = 0; j.ticks = 0;
        this.push('report', 'ok', `Downloaded 0${String(j.index).padStart(2, '0')} — ${j.title} (${fmtBytes(j.est)})`);
      }
    }
    let slots = this.converts;
    for (const j of this.jobs) {
      if (slots <= 0) break;
      if (j.conversion_status === 'in_progress') {
        slots--; j.ticks++;
        if (j.ticks > 3 + Math.random() * 4) { j.conversion_status = 'done'; this.push('report', 'info', `Remuxed to mp4 + sha256 verified: ${j.title}`); }
      }
    }
    let free = this.target - this.jobs.filter(j => j.download_status === 'downloading').length;
    for (const j of this.jobs.filter(x => x.download_status === 'pending')) {
      if (free <= 0) break;
      j.download_status = 'downloading'; j.speed = (4 + Math.random() * 9) * 1048576; free--;
      this.push('report', 'info', `Worker DL${this.target - free + 1} claimed ${j.id} — ${j.title}`);
    }
    if (Math.random() < 0.10) {
      const msgs = [
        ['info', `Disk check OK — ${this.disk.freeGB.toFixed(1)}GB free (reserve 10GB).`],
        ['info', 'Network probe: youtube.com reachable in ' + (60 + Math.floor(Math.random() * 180)) + 'ms.'],
        ['ok', 'Playlist rescan finished — 0 new items.'],
        ['warn', 'Backpressure applied: fragment concurrency reduced to 8.']
      ];
      const [lv, m] = msgs[Math.floor(Math.random() * msgs.length)];
      this.push('report', lv, m);
    }
    this.disk.freeGB = Math.max(120, this.disk.freeGB - Math.random() * 0.35);
  },
  aggregate() { return this.jobs.reduce((a, j) => a + (j.download_status === 'downloading' ? j.speed : 0), 0); },
  status() {
    const jobs = this.jobs;
    const q = jobs.filter(j => ['pending', 'paused', 'downloading'].includes(j.download_status)).length;
    const done = jobs.filter(j => j.download_status === 'downloaded').length;
    const failed = jobs.filter(j => j.download_status === 'failed' || j.conversion_status === 'failed').length;
    const agg = this.aggregate();
    const dlCount = jobs.filter(j => j.download_status === 'downloading').length;
    const remaining = jobs.reduce((a, j) => {
      if (j.download_status === 'downloading') return a + j.est * (1 - j.progress / 100);
      if (j.download_status === 'pending' || j.download_status === 'paused') return a + j.est * (1 - j.progress / 100);
      return a;
    }, 0);
    const workers = [];
    for (let i = 1; i <= this.maxWorkers; i++) {
      const j = jobs.filter(x => x.download_status === 'downloading')[i - 1];
      workers.push({ id: 'DL' + i, type: 'download', status: j ? `⬇️ ${j.progress.toFixed(1)}% @ ${fmtSpeed(j.speed)} | ${j.title}` : '— idle slot —' });
    }
    for (let i = 1; i <= this.converts; i++) {
      const j = jobs.filter(x => x.conversion_status === 'in_progress')[i - 1];
      workers.push({ id: 'CV' + i, type: 'convert', status: j ? `🔄 Converting | ${j.title}` : '💤 Idle' });
    }
    return {
      stats: { totalQueued: q, downloaded: done, failed, total: jobs.length },
      aggregateSpeed: fmtSpeed(agg), activeWorkers: dlCount, targetWorkers: this.target,
      workers, isPaused: this.paused, pauseReason: this.pauseReason,
      diskSpace: { free: `${this.disk.freeGB.toFixed(1)} GB / ${this.disk.totalGB.toFixed(1)} GB`, percent: (this.disk.freeGB / this.disk.totalGB) * 100 },
      system: {
        cpu: `${(8 + dlCount * 6 + Math.random() * 5).toFixed(0)}%`, cpuPercent: 8 + dlCount * 6 + Math.random() * 5,
        ram: `${this.memGB.toFixed(2)} GB / ${this.memTotalGB.toFixed(2)} GB`, ramPercent: (this.memGB / this.memTotalGB) * 100
      },
      uptime: fmtDur((Date.now() - this.started) / 1000),
      globalETA: agg > 0 ? fmtDur(remaining / agg) : '--',
      _demo: { remaining, agg, dlCount, converted: jobs.filter(j => j.conversion_status === 'done').length, archived: jobs.reduce((a, j) => a + j.file_size, 0) }
    };
  },
  jobsList() {
    return {
      jobs: this.jobs.map(j => ({
        id: j.id, url: j.url, title: j.title, folder: j.folder, download_status: j.download_status,
        conversion_status: j.conversion_status, retry_count: j.retry_count, last_error: j.last_error,
        file_size: j.file_size, progress: j.progress, speed: j.speed, eta: j.eta, index: j.index
      })).reverse()
    };
  },
  failedList() {
    return { ok: true, failed: this.jobs.filter(j => j.download_status === 'failed' || j.conversion_status === 'failed')
      .map(j => ({ id: j.id, title: j.title, folder: j.folder, retry_count: j.retry_count, last_error: j.last_error })) };
  },
  historyList() { return { ok: true, history: this.history.slice().reverse() }; },
  logsList(t) { return { ok: true, type: t, logs: (this.logs[t] || []).slice(-200) }; },
  async scan(urls, folder, opts) {
    let added = 0;
    for (const url of urls) {
      const f = folder || this.folders[Math.floor(Math.random() * this.folders.length)];
      const n = url.includes('/watch') ? 1 : 3 + Math.floor(Math.random() * 6);
      for (let i = 0; i < n; i++) {
        const est = Math.round((90 + Math.random() * 720) * 1024 * 1024);
        const id = this.rid();
        if (this.jobs.some(j => j.id === id)) continue;
        this.jobs.push({
          id, url: url.includes('/watch') ? url : `https://www.youtube.com/watch?v=${id}`,
          title: this.titles[Math.floor(Math.random() * this.titles.length)], folder: f,
          index: this.jobs.length + 1, download_status: 'pending', conversion_status: opts.quality === 'audio' ? 'pending' : 'not_needed',
          progress: 0, speed: 0, eta: 0, file_size: 0, est, retry_count: 0, last_error: null,
          created_at: new Date().toISOString(), ticks: 0
        });
        added++;
      }
      this.push('report', 'ok', `Scanned ${url} → ${f} (${n} item(s) ingested)`);
    }
    return { ok: true, message: `Queued ${added} new item(s)`, added };
  },
  purge() { const before = this.jobs.length; this.jobs = this.jobs.filter(j => !['pending', 'paused', 'failed'].includes(j.download_status)); const d = before - this.jobs.length; this.push('report', 'warn', `Queue purged — ${d} job(s) removed.`); return { ok: true, deleted: d }; },
  retry(ids) { ids.forEach(id => { const j = this.jobs.find(x => x.id === id); if (j) { j.download_status = 'pending'; j.conversion_status = 'pending'; j.retry_count = 0; j.last_error = null; j.progress = 0; this.push('report', 'info', `Requeued ${id} — ${j.title}`); } }); return { ok: true }; },
  pause(ids) { ids.forEach(id => { const j = this.jobs.find(x => x.id === id); if (j && ['pending', 'downloading'].includes(j.download_status)) { j.download_status = 'paused'; j.speed = 0; } }); return { ok: true }; },
  remove(ids) { this.jobs = this.jobs.filter(j => !ids.includes(j.id)); return { ok: true }; },
  pauseAll() { this.paused = true; this.pauseReason = 'MANUAL_WEB_UI'; this.push('report', 'warn', 'Global pause requested from Web UI — SIGINT sent to active workers.'); return { success: true }; },
  resumeAll() { this.paused = false; this.pauseReason = null; this.jobs.forEach(j => { if (j.download_status === 'paused') j.download_status = 'pending'; }); this.push('report', 'ok', 'Engine resumed.'); return { success: true }; }
};
demo.init();

