let ONLINE = false, pingFails = 0;
async function req(path, opts = {}) {
  const res = await fetch(path, Object.assign({ cache: 'no-store', headers: { 'Content-Type': 'application/json' } }, opts));
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const ct = res.headers.get('content-type') || '';
  return ct.includes('application/json') ? res.json() : { raw: await res.text() };
}
const api = {
  status:  () => ONLINE ? req('/api/status') : demo.status(),
  jobs:    () => ONLINE ? req('/api/jobs') : demo.jobsList(),
  failed:  () => ONLINE ? req('/api/failed') : demo.failedList(),
  history: () => ONLINE ? req('/api/history?limit=50') : demo.historyList(),
  logs:    t => ONLINE ? req(`/api/logs?type=${t}&limit=250`) : demo.logsList(t),
  scan:    (url, folder, opts) => ONLINE ? req('/api/scan', { method: 'POST', body: JSON.stringify({ url, folder, ...opts }) }) : demo.scan([url], folder, opts),
  purge:   () => ONLINE ? req('/api/queue/purge', { method: 'POST' }) : demo.purge(),
  pauseAll:  () => ONLINE ? req('/api/pause', { method: 'POST' }) : demo.pauseAll(),
  resumeAll: () => ONLINE ? req('/api/resume', { method: 'POST' }) : demo.resumeAll(),
  retryOne:  id => ONLINE ? req(`/api/retry/${encodeURIComponent(id)}`, { method: 'POST' }) : demo.retry([id]),
  deleteOne: id => ONLINE ? req(`/api/jobs/${encodeURIComponent(id)}`, { method: 'DELETE' }) : demo.remove([id]),
  pauseOne:  id => ONLINE ? req(`/api/pause/${encodeURIComponent(id)}`, { method: 'POST' }) : demo.pause([id])
};

