/* ---------- sparkline ---------- */
const spark = $('#spark'), sctx = spark.getContext('2d');
function drawSpark() {
  const dpr = window.devicePixelRatio || 1;
  const w = spark.clientWidth, h = spark.clientHeight;
  if (!w || !h) return;
  if (spark.width !== w * dpr) { spark.width = w * dpr; spark.height = h * dpr; }
  sctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  sctx.clearRect(0, 0, w, h);
  sctx.strokeStyle = 'rgba(255,255,255,.045)'; sctx.lineWidth = 1;
  for (let i = 1; i < 4; i++) { const y = (h / 4) * i; sctx.beginPath(); sctx.moveTo(0, y); sctx.lineTo(w, y); sctx.stroke(); }
  const data = state.speedHist;
  if (data.length < 2) return;
  const max = Math.max(...data, 1);
  const pts = data.map((v, i) => [(i / (data.length - 1)) * w, h - (v / max) * (h - 10) - 5]);
  const grad = sctx.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0, 'rgba(255,59,92,.38)'); grad.addColorStop(1, 'rgba(255,59,92,0)');
  sctx.beginPath(); sctx.moveTo(0, h);
  pts.forEach(p => sctx.lineTo(p[0], p[1]));
  sctx.lineTo(w, h); sctx.closePath(); sctx.fillStyle = grad; sctx.fill();
  sctx.beginPath(); pts.forEach((p, i) => i ? sctx.lineTo(p[0], p[1]) : sctx.moveTo(p[0], p[1]));
  sctx.strokeStyle = '#ff3b5c'; sctx.lineWidth = 2; sctx.lineJoin = 'round'; sctx.stroke();
  const last = pts[pts.length - 1];
  sctx.beginPath(); sctx.arc(last[0] - 2, last[1], 3.2, 0, Math.PI * 2); sctx.fillStyle = '#fff'; sctx.fill();
  sctx.beginPath(); sctx.arc(last[0] - 2, last[1], 7, 0, Math.PI * 2); sctx.fillStyle = 'rgba(255,59,92,.22)'; sctx.fill();
}
window.addEventListener('resize', drawSpark);

/* ---------- status render ---------- */
function renderStatus(s) {
  state.lastStatus = s;
  const st = s.stats || {};
  const total = st.total || 0, done = st.downloaded || 0, failed = st.failed || 0;
  const queued = st.totalQueued || 0;
  const agg = parseSpeed(s.aggregateSpeed);

  $('#stTotal').textContent = total;
  $('#stQueued').textContent = queued;
  const activeNow = state.jobs.filter(j => j.download_status === 'downloading').length || (s._demo ? s._demo.dlCount : s.activeWorkers || 0);
  $('#stActive').textContent = activeNow;
  $('#barQueue').style.width = total ? Math.min(100, (queued / total) * 100) + '%' : '0%';

  $('#stDone').textContent = done;
  $('#stDoneSub').textContent = `${total ? Math.round((done / total) * 100) : 0}% of archive · ${fmtBytes(s._demo ? s._demo.archived : 0)} written`;
  $('#barDone').style.width = total ? (done / total) * 100 + '%' : '0%';

  $('#stFailed').textContent = failed;
  $('#stRetries').textContent = state.jobs.reduce((a, j) => a + (j.retry_count || 0), 0);
  $('#barFail').style.width = total ? Math.min(100, (failed / total) * 100) + '%' : '0%';

  const pending = state.jobs.filter(j => j.download_status === 'pending' || j.download_status === 'paused');
  $('#stPos').textContent = pending.length ? `1 / ${pending.length}` : '--';
  $('#stNext').textContent = pending.length ? (pending[0].title || pending[0].id).slice(0, 34) : 'idle';
  $('#stEta').textContent = s.globalETA || '--';

  $('#thSpeed').textContent = s.aggregateSpeed || fmtSpeed(agg);
  $('#thCap').textContent = s.capKBps ? `cap ${fmtSpeed(s.capKBps * 1024)}` : 'no cap';
  $('#thWorkers').textContent = `${s.activeWorkers || 0} / ${s.targetWorkers || 0}`;
  $('#thAvg').textContent = fmtSpeed((s.activeWorkers || 0) ? agg / s.activeWorkers : 0);
  state.speedHist.push(agg);
  if (state.speedHist.length > 90) state.speedHist.shift();
  state.peak = Math.max(state.peak * 0.995, agg);
  $('#thPeak').textContent = fmtSpeed(state.peak);
  $('#thConv').textContent = s._demo ? s._demo.converted : state.jobs.filter(j => j.conversion_status === 'done').length;
  drawSpark();

  const [freeStr, totalStr] = String((s.diskSpace || {}).free || '-- / --').split('/').map(x => (x || '').trim());
  const freeNum = parseFloat(freeStr) || 0, totalNum = parseFloat(totalStr) || 0;
  const pct = Math.max(0, Math.min(100, Number((s.diskSpace || {}).percent) || (totalNum ? (freeNum / totalNum) * 100 : 0)));
  $('#diskPct').textContent = pct ? pct.toFixed(0) + '%' : '--';
  $('#diskFree').textContent = freeStr || '--';
  $('#diskTotal').textContent = totalStr || '--';
  $('#diskArch').textContent = fmtBytes(state.jobs.reduce((a, j) => a + (j.file_size || 0), 0));
  const C = 2 * Math.PI * 44;
  $('#gaugeArc').setAttribute('stroke-dashoffset', String(C - (pct / 100) * C));
  $('#gaugeArc').setAttribute('stroke', pct < 12 ? '#ff3b5c' : pct < 25 ? '#ffb020' : 'url(#gg)');

  const sys = s.system || {};
  $('#sysRam').textContent = sys.ram || '--';
  $('#barRam').style.width = Math.min(100, Number(sys.ramPercent) || 0) + '%';
  $('#sysCpu').textContent = sys.cpu && sys.cpu !== '--' ? sys.cpu : 'n/a';
  $('#barCpu').style.width = Math.min(100, Number(sys.cpuPercent) || 0) + '%';
  const dl = (s.workers || []).filter(w => w.type === 'download').length, cv = (s.workers || []).filter(w => w.type === 'convert').length;
  $('#sysWorkers').textContent = `${dl} / ${cv}`;
  $('#sysScale').textContent = `${s.targetWorkers || 0} target · auto`;
  $('#uptime').textContent = s.uptime || '--';

  const strip = $('#workerStrip');
  strip.innerHTML = (s.workers || []).map(w => {
    const txt = String(w.status || '');
    let cls = '';
    if (/⬇|downloading|converting|🔄/i.test(txt)) cls = w.type === 'convert' ? 'conv' : 'busy';
    else if (/❌|fail/i.test(txt)) cls = 'err';
    else if (/⏸|paus/i.test(txt)) cls = 'wait';
    return `<span class="wk ${cls}" title="${esc(w.id)}: ${esc(txt)}">${esc(w.id)}</span>`;
  }).join('');

  const paused = !!s.isPaused;
  $('#pausePill').style.display = paused ? 'inline-flex' : 'none';
  $('#pauseReason').textContent = paused ? (s.pauseReason || 'PAUSED') : '';
  $('#pauseLabel').textContent = paused ? 'Resume All' : 'Pause All';
  $('#btnPause').className = paused ? 'btn' : 'btn warn';
  $('#btnPause').innerHTML = paused
    ? `<svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5l11 7-11 7V5z"/></svg><span id="pauseLabel">Resume All</span>`
    : `<svg viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="5" width="4" height="14" rx="1"/><rect x="14" y="5" width="4" height="14" rx="1"/></svg><span id="pauseLabel">Pause All</span>`;

  $('#cntJobs').textContent = total;
  $('#cntFailed').textContent = failed;
}

/* ---------- status badge ---------- */
function statusOf(j) {
  const d = j.download_status, c = j.conversion_status;
  if (d === 'failed' || c === 'failed') return { label: 'Failed', cls: 'b-er' };
  if (d === 'downloading') return { label: 'Downloading', cls: 'b-dl' };
  if (d === 'paused') return { label: 'Paused', cls: 'b-ps' };
  if (d === 'pending') return { label: 'Queued', cls: 'b-q' };
  if (d === 'downloaded') {
    if (c === 'in_progress') return { label: 'Converting', cls: 'b-cv' };
    if (c === 'pending') return { label: 'Awaiting conv', cls: 'b-cv' };
    return { label: 'Completed', cls: 'b-ok' };
  }
  return { label: d || 'Unknown', cls: 'b-q' };
}
function matchFilter(j) {
  const f = state.filter;
  const st = statusOf(j).label.toLowerCase();
  if (f === 'failed' && st !== 'failed') return false;
  if (f === 'downloaded' && st !== 'completed') return false;
  if (f === 'downloading' && st !== 'downloading') return false;
  if (f === 'pending' && st !== 'queued') return false;
  if (f === 'paused' && st !== 'paused') return false;
  if (state.query) {
    const hay = `${j.title} ${j.folder} ${j.id}`.toLowerCase();
    if (!hay.includes(state.query)) return false;
  }
  return true;
}

/* ---------- jobs table ---------- */
let prevKeys = '';
function renderJobs(list) {
  state.jobs = list || [];
  const rows = state.jobs.filter(matchFilter);
  const body = $('#jobBody');
  const key = rows.map(r => `${r.id}:${r.download_status}:${(r.progress || 0).toFixed(1)}`).join('|');
  const rebuild = key.split('|').length !== prevKeys.split('|').length || rows.some((r, i) => prevKeys.split('|')[i] !== `${r.id}:${r.download_status}:${(r.progress || 0).toFixed(1)}`);
  prevKeys = key;

  body.innerHTML = rows.map((j, i) => {
    const st = statusOf(j), p = Math.max(0, Math.min(100, Number(j.progress) || 0));
    const sel = state.selected.has(j.id);
    const shimmer = j.download_status === 'downloading' ? ' shimmer' : '';
    const barCls = st.cls === 'b-ok' ? 'gr' : st.cls === 'b-cv' ? 'vi' : st.cls === 'b-er' ? '' : 'cy';
    return `<tr class="rowin ${sel ? 'sel' : ''}" data-id="${esc(j.id)}" style="animation-delay:${Math.min(i * 8, 200)}ms">
      <td><input type="checkbox" class="rowchk" data-id="${esc(j.id)}" ${sel ? 'checked' : ''}/></td>
      <td>
        <span class="ttl" title="${esc(j.title)}">${esc(j.title || '(untitled)')}</span>
        <span class="meta">
          <span title="Folder">📁 ${esc(j.folder || '—')}</span>
          <span title="Video ID">${esc(shortId(j.id))}</span>
          ${j.file_size ? `<span title="File size">💾 ${fmtBytes(j.file_size)}</span>` : ''}
          ${j.retry_count ? `<span style="color:var(--am)" title="Retries">↻ ${j.retry_count}</span>` : ''}
        </span>
      </td>
      <td class="prog-cell">
        <div class="prog-top"><b>${p.toFixed(1)}%</b><span>${j.file_size ? fmtBytes(j.file_size * p / 100) + ' / ' + fmtBytes(j.file_size) : (p > 0 ? 'streaming' : '—')}</span></div>
        <div class="bar ${barCls}${shimmer}"><i style="width:${p}%"></i></div>
      </td>
      <td class="num ${j.speed > 0 ? '' : 'mut'}">${j.speed > 0 ? fmtSpeed(j.speed) : '—'}</td>
      <td class="num ${j.eta > 0 ? '' : 'mut'}">${j.eta > 0 ? fmtDur(j.eta) : '—'}</td>
      <td><span class="badge ${st.cls}"><i></i>${st.label}</span></td>
      <td>
        <div class="acts">
          <button class="iconbtn green" data-act="retry" data-id="${esc(j.id)}" title="Retry job"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M21 12a9 9 0 11-3-6.7M21 4v5h-5"/></svg></button>
          <button class="iconbtn amber" data-act="pause" data-id="${esc(j.id)}" title="Pause job"><svg viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="5" width="4" height="14" rx="1"/><rect x="14" y="5" width="4" height="14" rx="1"/></svg></button>
          <button class="iconbtn red" data-act="delete" data-id="${esc(j.id)}" title="Delete job"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M4 7h16M9 7V5h6v2M6 7l1 13h10l1-13"/></svg></button>
        </div>
      </td>
    </tr>`;
  }).join('');

  $('#jobsEmpty').style.display = rows.length ? 'none' : 'block';
  $('#view-jobs .tbl-wrap').style.display = rows.length ? 'block' : 'none';
  const visIds = rows.map(r => r.id);
  $('#checkAll').checked = visIds.length > 0 && visIds.every(id => state.selected.has(id));
  updateSelbar();
}

/* ---------- failed / history / logs ---------- */
function renderFailed(list) {
  state.failed = list || [];
  $('#cntFailed').textContent = state.failed.length;
  $('#failGrid').innerHTML = state.failed.map(f => `
    <div class="fcard">
      <div class="row"><span class="badge b-er"><i></i>Failed</span>
        <span class="mono" style="font-size:10.5px;color:var(--dim)">${esc(shortId(f.id))} · ↻ ${f.retry_count || 0}</span></div>
      <h4 style="margin-top:8px">${esc(f.title || '(untitled)')}</h4>
      <div style="font-size:11px;color:var(--dim)">📁 ${esc(f.folder || '—')}</div>
      <div class="err">${esc(f.last_error || 'No error message recorded.')}</div>
      <div class="row">
        <span class="mono" style="font-size:10.5px;color:var(--dim)">${esc(f.id)}</span>
        <div style="display:flex;gap:6px">
          <button class="btn sm" data-fact="copy" data-id="${esc(f.id)}">Copy ID</button>
          <button class="btn sm green" data-fact="retry" data-id="${esc(f.id)}" style="border-color:#1f6b52;color:#5ff0bd;background:#0b1f18">Retry</button>
          <button class="btn sm danger" data-fact="delete" data-id="${esc(f.id)}">Delete</button>
        </div>
      </div>
    </div>`).join('');
  $('#failEmpty').style.display = state.failed.length ? 'none' : 'block';
  $('#failGrid').style.display = state.failed.length ? 'grid' : 'none';
}
function renderHistory(list) {
  state.history = list || [];
  $('#cntHistory').textContent = state.history.length;
  $('#histBody').innerHTML = state.history.map((h, i) => `
    <tr class="rowin" style="animation-delay:${i * 18}ms">
      <td class="num mut">#${h.id || state.history.length - i}</td>
      <td class="num">${esc(String(h.started_at || '--').replace('T', ' ').slice(0, 19))}</td>
      <td class="num">${esc(String(h.ended_at || '--').replace('T', ' ').slice(0, 19))}</td>
      <td class="num">${fmtDur(h.duration_seconds)}</td>
      <td class="num" style="text-align:right;color:var(--gr)">${h.downloaded ?? 0}</td>
      <td class="num" style="text-align:right;color:var(--mut)">${h.skipped ?? 0}</td>
      <td class="num" style="text-align:right;color:var(--red)">${h.failed ?? 0}</td>
      <td class="num" style="text-align:right">${h.total_queued ?? 0}</td>
    </tr>`).join('');
  $('#histEmpty').style.display = state.history.length ? 'none' : 'block';
  $('#view-history .tbl-wrap').style.display = state.history.length ? 'block' : 'none';
}
function levelOf(line) {
  const l = line.toLowerCase();
  if (l.includes('[err') || l.includes('error') || l.includes('failed') || l.includes('traceback')) return 't-err';
  if (l.includes('[warn') || l.includes('warning') || l.includes('throttl') || l.includes('retry')) return 't-warn';
  if (l.includes('done') || l.includes('✅') || l.includes('success') || l.includes('completed') || l.includes('downloaded')) return 't-ok';
  if (l.includes('[debug')) return 't-dim';
  return 't-info';
}
function renderLogs() {
  const lines = state.localLogs[state.logType] || [];
  const term = $('#term');
  term.style.whiteSpace = $('#logWrap').checked ? 'normal' : 'pre';
  term.innerHTML = lines.length
    ? lines.map(l => `<div class="ln ${levelOf(l)}">${esc(l)}</div>`).join('')
    : `<div class="t-dim">No ${state.logType} log entries — the engine writes to <span class="mono">${state.logType}.log</span>.</div>`;
  if ($('#logAuto').checked) term.scrollTop = term.scrollHeight;
}

/* ---------- selection ---------- */
function updateSelbar() {
  const n = state.selected.size;
  $('#selbar').style.display = n ? 'flex' : 'none';
  $('#selCount').textContent = n;
}

/* =========================================================================
   REFRESH LOOP
   ========================================================================= */
async function ping() {
  try { const r = await fetch('/api/ping', { cache: 'no-store' }); return r.ok; } catch { return false; }
}
async function refresh(silent = true) {
  try {
    const s = await api.status();
    renderStatus(s);
    if (state.tab === 'jobs' || true) {
      const j = await api.jobs();
      renderJobs(j.jobs || []);
    }
    if (state.tab === 'failed') renderFailed((await api.failed()).failed || []);
    if (state.tab === 'history') renderHistory((await api.history()).history || []);
    $('#lastSync').textContent = `synced ${ts()}`;
  } catch (e) {
    if (!silent) toast('Refresh failed', String(e.message || e), 'err');
    $('#lastSync').textContent = 'sync error';
  }
}
async function refreshLogs() {
  try {
    const r = await api.logs(state.logType);
    state.localLogs[state.logType] = r.logs && r.logs.length ? r.logs : (state.localLogs[state.logType] || []);
  } catch (e) { /* keep existing */ }
  renderLogs();
}
async function connectivity() {
  const ok = await ping();
  if (ok) {
    pingFails = 0;
    if (!ONLINE) { ONLINE = true; toast('Connected to engine', 'Live data from /api/status', 'ok'); }
  } else {
    pingFails++;
    if (ONLINE || pingFails >= 2) {
      const wasOnline = ONLINE;
      ONLINE = false;
      if (wasOnline) toast('Connection lost', 'Backend unreachable — switching to demo data', 'err');
    }
  }
  $('#demoBanner').classList.toggle('on', !ONLINE);
  const dot = $('#connDot'), txt = $('#connTxt');
  dot.className = 'dot ' + (ONLINE ? 'on' : (pingFails >= 2 ? 'demo' : 'off'));
  txt.textContent = ONLINE ? 'Connected' : (pingFails >= 2 ? 'Demo Mode' : 'Connecting…');
  $('#subline').textContent = ONLINE ? 'Resilient · Autonomous · Proxy-Free' : 'Simulated data · engine API offline';
}

/* =========================================================================
   ACTIONS
   ========================================================================= */
async function doScan(urls, folder, opts) {
  let ok = 0, fail = 0;
  for (const u of urls) {
    try { const r = await api.scan(u.trim(), folder, opts); if (r && r.ok === false) throw new Error(r.error); ok++; }
    catch (e) { fail++; toast('Scan failed', `${u.slice(0, 60)} — ${e.message || e}`, 'err'); }
  }
  if (ok) toast('Scan queued', `${ok} URL(s) ingested${fail ? `, ${fail} failed` : ''}`, 'ok');
  await refresh();
}
async function bulk(fn, ids, label) {
  let ok = 0, err = 0;
  for (const id of ids) { try { await fn(id); ok++; } catch { err++; } }
  if (ok && !err) toast(`${label} succeeded`, `${ok} job(s) updated`, 'ok');
  else if (ok && err) toast(`${label} partial`, `${ok} ok · ${err} failed`, 'warn');
  else if (label.startsWith('Pause')) toast('Pause unavailable', 'Engine exposes global pause only — use “Pause All”.', 'warn');
  else toast(`${label} failed`, `${err} job(s) rejected by the API`, 'err');
  await refresh();
}

/* ---------- events ---------- */
$('#btnAdd').onclick = () => $('#ovAdd').classList.add('on');
$('#btnScan').onclick = () => { $('#ovAdd').classList.add('on'); setTimeout(() => $('#inUrl').focus(), 60); };
$('#btnDoScan').onclick = async () => {
  const urls = $('#inUrl').value.split('\n').map(s => s.trim()).filter(s => s && /^https?:\/\//i.test(s));
  if (!urls.length) { toast('No valid URLs', 'Paste at least one http(s) playlist/channel URL.', 'warn'); return; }
  const btn = $('#btnDoScan'); btn.disabled = true; $('#scanLabel').textContent = 'Scanning…';
  const opts = {
    folder: $('#inFolder').value.trim(), quality: $('#optQuality').value,
    want_subtitles: $('#optSubs').checked, want_thumbnail: $('#optThumb').checked,
    want_description: $('#optDesc').checked, archive_live: $('#optLive').checked
  };
  await doScan(urls, opts.folder, opts);
  btn.disabled = false; $('#scanLabel').textContent = 'Scan & Add to Queue';
  $('#ovAdd').classList.remove('on'); $('#inUrl').value = ''; $('#inFolder').value = '';
};
$('#btnPause').onclick = async () => {
  const paused = state.lastStatus && state.lastStatus.isPaused;
  try { paused ? await api.resumeAll() : await api.pauseAll(); toast(paused ? 'Engine resumed' : 'Engine paused', paused ? 'Workers will claim queued jobs again.' : 'Active workers received SIGINT.', paused ? 'ok' : 'warn'); }
  catch (e) { toast('Action failed', String(e.message || e), 'err'); }
  await refresh();
};
$('#btnRefresh').onclick = async () => { $('#btnRefresh').querySelector('svg').classList.add('spin'); await connectivity(); await refresh(false); setTimeout(() => $('#btnRefresh').querySelector('svg').classList.remove('spin'), 600); };
$('#btnTabRefresh').onclick = async () => { await refresh(false); if (state.tab === 'logs') await refreshLogs(); toast('Refreshed', 'Data re-synced from engine', 'ok', 1800); };
$('#btnPurge').onclick = async () => {
  const ok = await confirmDialog('Purge queue?', 'Removes every <b>pending</b>, <b>paused</b> and <b>failed</b> job from <span class="mono">archive.db</span>. Downloaded files are untouched.', 'Purge');
  if (!ok) return;
  try { const r = await api.purge(); toast('Queue purged', `${r.deleted ?? 0} job(s) removed`, 'ok'); }
  catch (e) { toast('Purge failed', String(e.message || e), 'err'); }
