};
$('#btnSelRetry').onclick = () => { const ids = [...state.selected]; bulk(api.retryOne, ids, 'Retry'); state.selected.clear(); };
$('#btnSelPause').onclick = () => { const ids = [...state.selected]; bulk(api.pauseOne, ids, 'Pause'); state.selected.clear(); };
$('#btnSelDelete').onclick = async () => {
  const ids = [...state.selected];
  const ok = await confirmDialog('Delete selected jobs?', `This permanently removes <b>${ids.length}</b> job record(s) from the database.`, 'Delete');
  if (!ok) return;
