$('#btnSelClear').onclick = () => { state.selected.clear(); renderJobs(state.jobs); };

$('#jobBody').addEventListener('click', async e => {
  const btn = e.target.closest('[data-act]'); if (!btn) return;
  const id = btn.dataset.id, act = btn.dataset.act;
  if (act === 'delete') {
    const ok = await confirmDialog('Delete job?', `Record <span class="mono">${esc(id)}</span> will be removed from the database.`, 'Delete');
    if (!ok) return;
    try { await api.deleteOne(id); toast('Job deleted', id, 'ok'); } catch (err) { toast('Delete failed', String(err.message || err), 'err'); }
  } else if (act === 'retry') {
    try { await api.retryOne(id); toast('Job requeued', id, 'ok'); } catch (err) { toast('Retry failed', String(err.message || err), 'err'); }
  } else if (act === 'pause') {
    try { await api.pauseOne(id); toast('Job paused', id, 'warn'); }
