});
$('#jobBody').addEventListener('change', e => {
  const c = e.target.closest('.rowchk'); if (!c) return;
  c.checked ? state.selected.add(c.dataset.id) : state.selected.delete(c.dataset.id);
  c.closest('tr').classList.toggle('sel', c.checked);
  updateSelbar();
  const vis = $$('#jobBody .rowchk').map(x => x.dataset.id);
  $('#checkAll').checked = vis.length > 0 && vis.every(id => state.selected.has(id));
});
$('#checkAll').addEventListener('change', e => {
  const vis = $$('#jobBody .rowchk');
  vis.forEach(c => { c.checked = e.target.checked; c.closest('tr').classList.toggle('sel', e.target.checked); e.target.checked ? state.selected.add(c.dataset.id) : state.selected.delete(c.dataset.id); });
  updateSelbar();
});
$('#failGrid').addEventListener('click', async e => {
  const b = e.target.closest('[data-fact]'); if (!b) return;
  const id = b.dataset.id, act = b.dataset.fact;
  if (act === 'retry') { try { await api.retryOne(id); toast('Job requeued', id, 'ok'); await refresh(); renderFailed((await api.failed()).failed || []); } catch (err) { toast('Retry failed', String(err.message || err), 'err'); } }
  else if (act === 'delete') {
    const ok = await confirmDialog('Delete failed job?', `<span class="mono">${esc(id)}</span> will be removed from the database.`, 'Delete');
    if (!ok) return;
    try { await api.deleteOne(id); toast('Job deleted', id, 'ok'); renderFailed((await api.failed()).failed || []); await refresh(); } catch (err) { toast('Delete failed', String(err.message || err), 'err'); }
  } else if (act === 'copy') {
    try { await navigator.clipboard.writeText(id); toast('Copied', id, 'ok', 1600); } catch { toast('Copy blocked', 'Clipboard permission denied', 'warn'); }
  }
});

/* tabs */
$$('.tab').forEach(t => t.onclick = async () => {
  $$('.tab').forEach(x => x.classList.remove('on')); t.classList.add('on');
  state.tab = t.dataset.tab;
  ['jobs', 'failed', 'history', 'logs'].forEach(v => $('#view-' + v).style.display = v === state.tab ? 'block' : 'none');
  if (state.tab === 'failed') renderFailed((await api.failed().catch(() => ({ failed: [] }))).failed || []);
  if (state.tab === 'history') renderHistory((await api.history().catch(() => ({ history: [] }))).history || []);
  if (state.tab === 'logs') await refreshLogs();
});
/* filters */
$('#chips').addEventListener('click', e => {
  const c = e.target.closest('.chip'); if (!c) return;
  $$('#chips .chip').forEach(x => x.classList.remove('on')); c.classList.add('on');
  state.filter = c.dataset.f; renderJobs(state.jobs);
});
$('#search').addEventListener('input', e => { state.query = e.target.value.trim().toLowerCase(); renderJobs(state.jobs); });
/* logs controls */
$('#logTabErr').onclick = () => { state.logType = 'error'; $('#logTabErr').classList.add('on'); $('#logTabRep').classList.remove('on'); refreshLogs(); };
$('#logTabRep').onclick = () => { state.logType = 'report'; $('#logTabRep').classList.add('on'); $('#logTabErr').classList.remove('on'); refreshLogs(); };
$('#btnLogsRefresh').onclick = () => refreshLogs();
$('#logAuto').onchange = () => { if ($('#logAuto').checked) $('#term').scrollTop = $('#term').scrollHeight; };
$('#logWrap').onchange = renderLogs;
$('#btnClearLogs').onclick = () => { state.localLogs[state.logType] = []; renderLogs(); toast('Log view cleared', 'Server-side log file untouched.', 'info', 2200); };
$('#btnCopyLogs').onclick = async () => {
  try { await navigator.clipboard.writeText((state.localLogs[state.logType] || []).join('\n')); toast('Logs copied', `${(state.localLogs[state.logType] || []).length} lines`, 'ok', 2000); }
  catch { toast('Copy blocked', 'Clipboard permission denied', 'warn'); }
};
/* keyboard */
document.addEventListener('keydown', e => {
  if (e.key === 'Escape') { $$('.overlay.on').forEach(o => { o.classList.remove('on'); if (o.id === 'ovConfirm') closeConfirm(false); }); }
  if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); $('#search').focus(); }
  if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'r') { e.preventDefault(); $('#btnRefresh').click(); }
});

/* =========================================================================
   BOOT
   ========================================================================= */
(async function boot() {
  drawSpark();
  await connectivity();
  await refresh();
  await refreshLogs();
  setInterval(() => { if (!ONLINE) demo.tick(); }, 1000);
  setInterval(refresh, 2000);
  setInterval(connectivity, 5000);
  setInterval(() => { if (state.tab === 'logs') refreshLogs(); }, 4000);
  setTimeout(() => toast(ONLINE ? 'Engine connected' : 'Demo mode active',
    ONLINE ? 'Streaming live status from the Bun backend.' : 'No backend found — running a simulated engine so all controls work.',
    ONLINE ? 'ok' : 'warn', 5200), 700);
})();
</script>
</body>
