type LogLevel = "debug" | "info" | "ok" | "warn" | "error" | "fatal";
const LEVEL_COLOR: Record<LogLevel, string> = {
  debug: "\x1b[90m", info: "\x1b[36m", ok: "\x1b[32m",
  warn: "\x1b[33m", error: "\x1b[31m", fatal: "\x1b[41m\x1b[97m",
};
const LEVEL_ICON: Record<LogLevel, string> = {
  debug: "·", info: "ℹ", ok: "✅", warn: "⚠️", error: "❌", fatal: "☠️",
};

class Logger {
  private errorLog = "error.log";
  private reportLog = "report.log";
  private sink: ((lvl: LogLevel, scope: string, msg: string) => void) | null = null;
  verbose = CLI.verbose;
  private writeQueue: Promise<void> = Promise.resolve();

  configure(opts: { errorLog?: string; reportLog?: string; verbose?: boolean }) {
    if (opts.errorLog) this.errorLog = opts.errorLog;
    if (opts.reportLog) this.reportLog = opts.reportLog;
    if (opts.verbose !== undefined) this.verbose = opts.verbose;
  }
  attachDb(fn: (lvl: LogLevel, scope: string, msg: string) => void) { this.sink = fn; }

  private stamp() { return new Date().toISOString().replace("T", " ").slice(0, 19); }

  private line(lvl: LogLevel, scope: string, msg: string) {
    return `${this.stamp()} [${lvl.toUpperCase().padEnd(5)}]${scope ? ` [${scope}]` : ""} ${msg}`;
  }

  log(lvl: LogLevel, scope: string, msg: string, err?: unknown) {
    const detail = err !== undefined ? ` :: ${err instanceof Error ? (err.stack || err.message) : String(err)}` : "";
    if (lvl === "debug" && !this.verbose) { /* still persisted to db */ }
    else {
      const color = LEVEL_COLOR[lvl];
      process.stdout.write(`${color}${LEVEL_ICON[lvl]} \x1b[0m${this.line(lvl, scope, msg + (lvl === "fatal" || lvl === "error" ? detail : ""))}\n`);
    }
    try { this.sink?.(lvl, scope, msg + detail); } catch { /* db not ready yet */ }

    if (lvl === "error" || lvl === "fatal" || lvl === "warn") {
      this.enqueue(() => appendFile(this.errorLog, this.line(lvl, scope, msg + detail) + "\n", "utf-8").catch(() => {}));
    }
    if (lvl === "ok" || lvl === "info") {
      this.enqueue(() => appendFile(this.reportLog, this.line(lvl, scope, msg) + "\n", "utf-8").catch(() => {}));
    }
  }

  private enqueue(task: () => Promise<void>) {
    this.writeQueue = this.writeQueue.then(task).catch(() => {});
  }

  debug(s: string, m: string, e?: unknown) { this.log("debug", s, m, e); }
  info (s: string, m: string, e?: unknown) { this.log("info",  s, m, e); }
  ok   (s: string, m: string, e?: unknown) { this.log("ok",    s, m, e); }
  warn (s: string, m: string, e?: unknown) { this.log("warn",  s, m, e); }
  error(s: string, m: string, e?: unknown) { this.log("error", s, m, e); }
  fatal(s: string, m: string, e?: unknown) { this.log("fatal", s, m, e); }
}
