let globalConfig: Config = { ...DEFAULT_CONFIG };

async function loadConfig(): Promise<Config> {
  if (!existsSync(CONFIG_PATH)) {
    log.warn("config", `${CONFIG_PATH} not found — writing defaults. Add playlists/channels then re-run (or use: bun run update_config.ts).`);
    await writeFile(CONFIG_PATH, JSON.stringify(DEFAULT_CONFIG, null, 2), "utf-8");
    return { ...DEFAULT_CONFIG };
  }
  let rawText = "";
  try {
    rawText = await readFile(CONFIG_PATH, "utf-8");
  } catch (e) {
    throw new Error(`Unable to read ${CONFIG_PATH}: ${(e as Error).message}`);
  }
  let parsedJson: unknown;
  try {
    parsedJson = JSON.parse(rawText);
  } catch (e) {
    const backup = `${CONFIG_PATH}.corrupt.${Date.now()}`;
    await writeFile(backup, rawText, "utf-8").catch(() => {});
    throw new Error(`config.json is not valid JSON (${(e as Error).message}). A copy was saved to ${backup}.`);
  }
  const merged = { ...DEFAULT_CONFIG, ...(parsedJson as object) };
  const result = ConfigSchema.safeParse(merged);
  if (!result.success) {
    const issues = result.error.issues.map(i => `  • ${i.path.join(".") || "(root)"}: ${i.message}`).join("\n");
    throw new Error(`config.json failed validation:\n${issues}`);
  }
  return result.data as Config;
}

