function formatBytes(bytes: number): string {
  if (!bytes || bytes <= 0 || !Number.isFinite(bytes)) return "0 B";
  const units = ["B", "KB", "MB", "GB", "TB"];
  let i = 0, v = bytes;
  while (v >= 1024 && i < units.length - 1) { v /= 1024; i++; }
  return `${v.toFixed(v >= 100 || i === 0 ? 0 : 1)} ${units[i]}`;
}
function formatBytesPerSec(bps: number): string {
  if (!bps || bps <= 0 || !Number.isFinite(bps)) return "0 B/s";
  return formatBytes(bps) + "/s";
}
function parseSpeedToBytesPerSec(speedStr: string | number | undefined): number {
  if (typeof speedStr === "number") return Number.isFinite(speedStr) ? speedStr : 0;
  if (!speedStr || !speedStr.trim() || speedStr.toLowerCase() === "na") return 0;
  const m = speedStr.match(/([\d.]+)\s*([KMGT]?i?B)/i);
  if (!m) return 0;
  const unit = m[2].toLowerCase().replace("ib", "b");
  const mult: Record<string, number> = { b: 1, kb: 1024, mb: 1024 ** 2, gb: 1024 ** 3, tb: 1024 ** 4 };
  const v = parseFloat(m[1]) * (mult[unit] || 1);
  return Number.isFinite(v) ? v : 0;
}
function formatDuration(seconds: number): string {
  if (!seconds || seconds <= 0 || !Number.isFinite(seconds)) return "--";
  const s = Math.round(seconds);
  if (s < 60) return `${s}s`;
  if (s < 3600) return `${Math.floor(s / 60)}m ${s % 60}s`;
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60);
  return `${h}h ${m}m`;
}
function sanitizeFolderName(name: string): string {
  return (name || "").replace(/[/:*?"<>|]/g, " ").replace(/\s+/g, " ").trim().slice(0, 120) || "playlist";
}
function sanitizeFileName(name: string): string {
  return (name || "").replace(/[/:*?"<>|]/g, " ").replace(/\s+/g, " ").trim().slice(0, 150) || "video";
}
function safeNum(v: unknown, fallback = 0): number {
  const n = typeof v === "string" ? parseFloat(v) : Number(v);
  return Number.isFinite(n) ? n : fallback;
}
function sleep(ms: number): Promise<void> { return new Promise(r => setTimeout(r, ms)); }
function truncate(s: string, n = 500): string { return (s || "").slice(0, n); }

async function hashFile(filePath: string): Promise<string> {
  return new Promise((res, rej) => {
    const hash = createHash("sha256");
    const stream = createReadStream(filePath);
    stream.on("data", c => hash.update(c));
    stream.on("end", () => res(hash.digest("hex")));
    stream.on("error", rej);
  });
}

async function checkDiskSpace(path: string, minGB: number): Promise<{ freeGB: number; totalGB: number; percent: number; ok: boolean; error?: string }> {
  try {
    const s = await statfs(path);
    const freeGB = (s.bavail * s.bsize) / 1024 ** 3;
    const totalGB = (s.blocks * s.bsize) / 1024 ** 3;
    return {
      freeGB, totalGB,
      percent: totalGB > 0 ? (freeGB / totalGB) * 100 : 0,
      ok: freeGB > minGB,
    };
  } catch (e) {
    return { freeGB: 0, totalGB: 0, percent: 0, ok: false, error: (e as Error).message };
  }
}

async function checkInternet(): Promise<boolean> {
  try {
    const ac = new AbortController();
    const t = setTimeout(() => ac.abort(), 5000);
    await fetch("https://www.youtube.com/favicon.ico", { signal: ac.signal, method: "HEAD", redirect: "follow" });
    clearTimeout(t);
    return true;
  } catch { return false; }
}

function cookiesArgs(config: Config): string[] {
  try { if (statSync(config.cookiesFile).size > 0) return ["--cookies", config.cookiesFile]; } catch {}
  return [];
}

/** Run a binary and capture stdout/stderr/exit code with a hard timeout. */
async function runCmd(
  cmd: string, args: string[], opts: { timeoutMs?: number; cwd?: string } = {},
): Promise<{ code: number; stdout: string; stderr: string; timedOut: boolean }> {
  const timeoutMs = opts.timeoutMs ?? 60_000;
  let proc: ReturnType<typeof Bun.spawn> | null = null;
  let timedOut = false;
  try {
    proc = Bun.spawn([cmd, ...args], {
      stdout: "pipe", stderr: "pipe", stdin: "ignore",
      cwd: opts.cwd, env: { ...process.env, PYTHONUNBUFFERED: "1" },
    });
    const timer = setTimeout(() => { timedOut = true; try { proc!.kill("SIGKILL"); } catch {} }, timeoutMs);
    const [out, err, code] = await Promise.all([
      new Response(proc.stdout).text().catch(() => ""),
      new Response(proc.stderr).text().catch(() => ""),
      proc.exited.catch(() => 1),
    ]);
    clearTimeout(timer);
    return { code: timedOut ? 124 : code, stdout: out, stderr: err, timedOut };
  } catch (e) {
    return { code: 127, stdout: "", stderr: `spawn failed: ${(e as Error).message}`, timedOut: false };
  }
}

/* ---- Error classification (drives retry / remediation logic) -------------- */

type ErrKind =
  | "SIGNATURE" | "CORRUPT_PARTIAL" | "TRANSIENT_NETWORK" | "RATE_LIMIT"
  | "UNAVAILABLE" | "PRIVATE" | "LOGIN_REQUIRED" | "GEO_BLOCKED"
  | "DISK_FULL" | "TIMEOUT" | "FFMPEG" | "UNKNOWN";

interface ClassifiedError {
  kind: ErrKind;
  retriable: boolean;
  autoRemedy: string;
  userFix: string;
  permanent: boolean;
}

function classifyError(raw: string): ClassifiedError {
  const e = (raw || "").toLowerCase();
  const mk = (kind: ErrKind, retriable: boolean, autoRemedy: string, userFix: string, permanent = false): ClassifiedError =>
    ({ kind, retriable, autoRemedy, userFix, permanent });

  if (e.includes("signature") || e.includes("unable to extract") || e.includes("nsig") || e.includes("js player"))
    return mk("SIGNATURE", true, "Auto-update yt-dlp, reset retry counter and requeue.", "If it persists run: yt-dlp -U");
  if (e.includes("unable to resume") || e.includes("incomplete") || e.includes("corrupt") || e.includes("invalid data") || e.includes("fragment") && e.includes("missing"))
    return mk("CORRUPT_PARTIAL", true, "Delete the corrupt .part file and restart from zero.", "None required.");
  if (e.includes("no space left") || e.includes("disk quota") || e.includes("enospc"))
    return mk("DISK_FULL", false, "Engine paused — free disk space, then press Resume.", `Raise minFreeSpaceGB or clean ${globalConfig.outputRoot}`);
  if (e.includes("private video") || e.includes("members-only") || e.includes("join this channel"))
    return mk("PRIVATE", false, "Marked skipped — needs channel membership.", "Export fresh cookies.txt from a logged-in browser session.", true);
  if (e.includes("login required") || e.includes("sign in") || e.includes("authentication"))
    return mk("LOGIN_REQUIRED", true, "Requeued once; will be skipped if it keeps failing.", "Refresh cookies.txt (browser extension → Netscape format).", false);
  if (e.includes("video unavailable") || e.includes("not available") || e.includes("removed") || e.includes("does not exist") || e.includes("404"))
    return mk("UNAVAILABLE", false, "Marked skipped — the video no longer exists.", "None required.", true);
  if (e.includes("geo") || e.includes("country") && e.includes("not available"))
    return mk("GEO_BLOCKED", false, "Marked failed — geo restriction.", "Configure a VPN/mirror outside the engine (proxy-free by design).", true);
  if (e.includes("429") || e.includes("too many requests") || e.includes("rate limit") || e.includes("throttl"))
    return mk("RATE_LIMIT", true, "Long exponential backoff, then requeue.", "Lower maxConcurrentDownloads or set maxBandwidthKBps.");
  if (e.includes("timed out") || e.includes("timeout") || e.includes("sigabrt"))
    return mk("TIMEOUT", true, "Requeued with a fresh timeout window.", "Raise downloadTimeoutMinutes for very long VODs.");
  if (e.includes("ffmpeg") || e.includes("remux") || e.includes("muxing") || e.includes("codec"))
    return mk("FFMPEG", false, "Conversion marked failed — source kept on disk.", "Verify ffmpeg build supports the target codec/container.");
  if (["connection reset", "network is unreachable", "err_connection", "temporary failure", "could not connect",
       "unable to download", "eof occurred", "broken pipe", "aborted", "socket", "tls", "ssl"].some(k => e.includes(k)))
    return mk("TRANSIENT_NETWORK", true, "Short backoff then requeue (partial file preserved).", "None required — automatic.");
  return mk("UNKNOWN", true, "Requeued up to maxRetryAttempts.", "Inspect the raw error in the Failed tab.");
}

/* ==========================================================================
   5. DEPENDENCY PREFLIGHT
   ========================================================================== */

async function preflight(config: Config): Promise<{ checks: DepCheck[]; ok: boolean }> {
  log.info("boot", "Running dependency preflight…");
  const checks: DepCheck[] = [];

  // bun
  checks.push({
    name: "Bun runtime", ok: true, critical: true,
    version: (Bun as any).version || "unknown",
    detail: `pid ${process.pid} · ${process.platform}/${process.arch}`,
  });

  // yt-dlp
  {
    const r = await runCmd("yt-dlp", ["--version"], { timeoutMs: 20_000 });
    const ok = r.code === 0 && !!r.stdout.trim();
    checks.push({
      name: "yt-dlp", ok, critical: true,
      version: ok ? r.stdout.trim().split("\n")[0] : "not found",
      detail: ok ? "downloader binary reachable on PATH" : truncate(r.stderr || r.stdout || "no output", 200),
      hint: ok ? undefined : "Install: pip install -U yt-dlp  (or: brew install yt-dlp)",
    });
  }

  // ffmpeg
  {
    const r = await runCmd("ffmpeg", ["-version"], { timeoutMs: 20_000 });
    const ok = r.code === 0;
    checks.push({
      name: "ffmpeg", ok, critical: true,
      version: ok ? (r.stdout.split("\n")[0].match(/ffmpeg version (\S+)/)?.[1] ?? "present") : "not found",
      detail: ok ? "required for remux / conversion / metadata embedding" : truncate(r.stderr, 200),
      hint: ok ? undefined : "Install: https://ffmpeg.org/download.html",
    });
  }

  // deno (JS runtime used by yt-dlp for signature extraction)
  {
    const bin = config.denoPath || "deno";
    const r = await runCmd(existsSync(bin) ? bin : "deno", ["--version"], { timeoutMs: 15_000 });
    const ok = r.code === 0;
    checks.push({
      name: "Deno (JS runtime)", ok, critical: false,
      version: ok ? (r.stdout.split("\n")[0] ?? "present") : "not found",
      detail: ok ? `path: ${bin}` : "yt-dlp may fall back to Node/PhantomJS for signature solving",
      hint: ok ? undefined : "Optional — install from https://deno.land or set denoPath in config.json",
    });
  }

  // config.json
  {
    const ok = existsSync(CONFIG_PATH);
    const srcCount = config.playlists.length + config.channels.length + config.channelPlaylists.length;
    checks.push({
      name: "config.json", ok: ok && (srcCount > 0 || config.daemonMode), critical: false,
      version: ok ? `${srcCount} source(s)` : "missing",
      detail: ok
        ? (srcCount ? "sources loaded" : "valid but empty — enable daemonMode or add sources")
        : "defaults were generated on first run",
      hint: srcCount ? undefined : "Run: bun run update_config.ts",
    });
  }

  // cookies
  {
    let ok = false, detail = "cookies.txt absent (anonymous mode)";
    let version = "n/a";
    try {
      const s = statSync(config.cookiesFile);
      if (s.size > 0) { ok = true; version = formatBytes(s.size); detail = `${config.cookiesFile} present`; }
      else detail = "cookies.txt is empty";
    } catch { /* absent is fine */ }
    checks.push({ name: "Cookies", ok, critical: false, version, detail });
  }

  // output root writable + disk space
  {
    const dir = resolve(config.outputRoot);
    let ok = false, detail = "";
    try {
      await mkdir(dir, { recursive: true });
      const probe = join(dir, `.write-probe-${Date.now()}`);
      await writeFile(probe, "ok", "utf-8");
      await unlink(probe).catch(() => {});
      ok = true; detail = `${dir} is writable`;
    } catch (e) { ok = false; detail = `cannot write to ${dir}: ${(e as Error).message}`; }
    const disk = await checkDiskSpace(dir, config.minFreeSpaceGB);
    if (ok && !disk.ok) { ok = false; detail = `only ${disk.freeGB.toFixed(1)} GB free (min ${config.minFreeSpaceGB} GB)`; }
    checks.push({
      name: "Output storage", ok, critical: true,
      version: `${disk.freeGB.toFixed(1)} / ${disk.totalGB.toFixed(1)} GB free`, detail,
      hint: ok ? undefined : "Change outputRoot or free disk space",
    });
  }

  // database writable
  {
    const p = resolve(CLI.dbPath || config.dbPath);
    let ok = true, detail = `sqlite @ ${p}`;
    try {
      await mkdir(dirname(p), { recursive: true });
      await access(dirname(p));
      if (existsSync(p)) detail += ` (${formatBytes(statSync(p).size)})`;
      else detail += " (will be created)";
    } catch (e) { ok = false; detail = (e as Error).message; }
    checks.push({ name: "Central database", ok, critical: true, version: "SQLite · WAL", detail });
  }

  const failedCritical = checks.filter(c => c.critical && !c.ok);
  const failedOptional = checks.filter(c => !c.critical && !c.ok);

  const width = Math.max(...checks.map(c => c.name.length), 18);
  console.log("");
  for (const c of checks) {
    const mark = c.ok ? "\x1b[32m✔\x1b[0m" : c.critical ? "\x1b[31m✘\x1b[0m" : "\x1b[33m!\x1b[0m";
    console.log(`  ${mark} ${c.name.padEnd(width)}  ${c.version.padEnd(22)} ${c.detail}`);
    if (!c.ok && c.hint) console.log(`      \x1b[90m↳ ${c.hint}\x1b[0m`);
  }
  console.log("");

  if (failedCritical.length) {
    log.fatal("boot", `Preflight failed: ${failedCritical.map(c => c.name).join(", ")}`);
    return { checks, ok: false };
  }
  if (failedOptional.length) log.warn("boot", `Preflight warnings: ${failedOptional.map(c => c.name).join(", ")}`);
  else log.ok("boot", "All dependencies satisfied.");
  return { checks, ok: true };
}

let LAST_PREFLIGHT: { checks: DepCheck[]; at: string } = { checks: [], at: "" };

/* ==========================================================================
   6. CENTRAL DATABASE
   ========================================================================== */

let db: Database;
let DB_PATH = "./archive.db";

const SCHEMA_VERSION = 6;

function initDatabase(path: string) {
  DB_PATH = path;
  try {
    db = new Database(path, { create: true });
  } catch (e) {
    throw new Error(`Cannot open database at ${path}: ${(e as Error).message}`);
  }
  db.run("PRAGMA journal_mode = WAL;");
  db.run("PRAGMA synchronous = NORMAL;");
  db.run("PRAGMA busy_timeout = 8000;");
  db.run("PRAGMA foreign_keys = ON;");
  db.run("PRAGMA temp_store = MEMORY;");
  db.run("PRAGMA cache_size = -16000;");

  db.run(`CREATE TABLE IF NOT EXISTS jobs (
    id                  TEXT PRIMARY KEY,
    url                 TEXT NOT NULL,
    title               TEXT NOT NULL DEFAULT 'video',
    channel             TEXT,
    playlist_title      TEXT,
    duration_seconds    REAL DEFAULT 0,
    upload_date         TEXT,
    folder              TEXT NOT NULL DEFAULT 'playlist',
    index_number        INTEGER NOT NULL DEFAULT 0,
    output_directory    TEXT NOT NULL,
    video_quality       TEXT NOT NULL DEFAULT '1080p',
    target_format       TEXT NOT NULL DEFAULT 'mp4',
    want_subtitles      INTEGER NOT NULL DEFAULT 0,
    want_thumbnail      INTEGER NOT NULL DEFAULT 0,
    want_description    INTEGER NOT NULL DEFAULT 0,
    want_infojson       INTEGER NOT NULL DEFAULT 0,
    want_metadata       INTEGER NOT NULL DEFAULT 1,
    verify_integrity    INTEGER NOT NULL DEFAULT 1,
    download_status     TEXT NOT NULL DEFAULT 'not_started',
    metadata_status     TEXT NOT NULL DEFAULT 'pending',
    conversion_status   TEXT NOT NULL DEFAULT 'pending',
    download_claimed_by TEXT,
    download_claimed_ms INTEGER,
    conversion_claimed_by TEXT,
    conversion_claimed_ms INTEGER,
    metadata_claimed_by TEXT,
    metadata_claimed_ms INTEGER,
    heartbeat_ms        INTEGER,
    partial_file_path   TEXT,
    file_path           TEXT,
    file_size           INTEGER DEFAULT 0,
    downloaded_bytes    INTEGER DEFAULT 0,
    integrity           TEXT,
    progress            REAL DEFAULT 0,
    speed               REAL DEFAULT 0,
    eta                 REAL DEFAULT 0,
    retry_count         INTEGER DEFAULT 0,
    error_code          TEXT,
    last_error          TEXT,
    source_url          TEXT,
    created_at          TEXT DEFAULT (datetime('now')),
    updated_at          TEXT DEFAULT (datetime('now')),
    started_at          TEXT,
    completed_at        TEXT
  )`);

  db.run(`CREATE TABLE IF NOT EXISTS sources (
    url             TEXT PRIMARY KEY,
    kind            TEXT NOT NULL DEFAULT 'playlist',
    folder          TEXT,
    title           TEXT,
    status          TEXT NOT NULL DEFAULT 'new',
    item_count      INTEGER DEFAULT 0,
    added_count     INTEGER DEFAULT 0,
    last_scanned_at TEXT,
    last_error      TEXT,
    created_at      TEXT DEFAULT (datetime('now'))
  )`);

  db.run(`CREATE TABLE IF NOT EXISTS playlist_state (
    folder      TEXT PRIMARY KEY,
    next_index  INTEGER NOT NULL DEFAULT 0,
    updated_at  TEXT DEFAULT (datetime('now'))
  )`);

  db.run(`CREATE TABLE IF NOT EXISTS run_history (
    id               INTEGER PRIMARY KEY AUTOINCREMENT,
    started_at       TEXT,
    ended_at         TEXT,
    duration_seconds REAL,
    downloaded       INTEGER DEFAULT 0,
    skipped          INTEGER DEFAULT 0,
    failed           INTEGER DEFAULT 0,
    converted        INTEGER DEFAULT 0,
    total_queued     INTEGER DEFAULT 0,
    bytes_downloaded INTEGER DEFAULT 0,
    exit_reason      TEXT
  )`);

  db.run(`CREATE TABLE IF NOT EXISTS events (
    seq      INTEGER PRIMARY KEY AUTOINCREMENT,
    ts       TEXT DEFAULT (datetime('now')),
    level    TEXT,
    scope    TEXT,
    message  TEXT,
    job_id   TEXT
  )`);

  db.run(`CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT)`);

  // indexes
  const idx = [
    `CREATE INDEX IF NOT EXISTS idx_jobs_dstatus ON jobs(download_status)`,
    `CREATE INDEX IF NOT EXISTS idx_jobs_cstatus ON jobs(conversion_status)`,
    `CREATE INDEX IF NOT EXISTS idx_jobs_mstatus ON jobs(metadata_status)`,
    `CREATE INDEX IF NOT EXISTS idx_jobs_folder  ON jobs(folder)`,
    `CREATE INDEX IF NOT EXISTS idx_jobs_claim   ON jobs(download_status, created_at)`,
    `CREATE INDEX IF NOT EXISTS idx_jobs_conv    ON jobs(download_status, conversion_status)`,
    `CREATE INDEX IF NOT EXISTS idx_jobs_meta    ON jobs(download_status, metadata_status)`,
    `CREATE INDEX IF NOT EXISTS idx_events_ts    ON events(seq)`,
  ];
  for (const s of idx) { try { db.run(s); } catch (e) { log.warn("db", `index skipped: ${(e as Error).message}`); } }

  // ---- migrations for databases created by V5 -----------------------------
  const cols = (db.query("PRAGMA table_info(jobs)").all() as unknown as { name: string }[]).map(c => c.name);
  const migrations: Record<string, string> = {
    channel: "TEXT", playlist_title: "TEXT", duration_seconds: "REAL DEFAULT 0", upload_date: "TEXT",
    index_number: "INTEGER DEFAULT 0", video_quality: "TEXT DEFAULT '1080p'", target_format: "TEXT DEFAULT 'mp4'",
    want_infojson: "INTEGER DEFAULT 0", want_metadata: "INTEGER DEFAULT 1", verify_integrity: "INTEGER DEFAULT 1",
    metadata_status: "TEXT DEFAULT 'pending'", metadata_claimed_by: "TEXT", metadata_claimed_ms: "INTEGER",
    download_claimed_ms: "INTEGER", conversion_claimed_ms: "INTEGER", heartbeat_ms: "INTEGER",
    downloaded_bytes: "INTEGER DEFAULT 0", error_code: "TEXT", source_url: "TEXT",
    started_at: "TEXT", completed_at: "TEXT",
  };
  // V5 used a column literally named "index" — map it into index_number.
  if (!cols.includes("index_number") && cols.includes("index")) {
    try { db.run(`ALTER TABLE jobs RENAME COLUMN "index" TO index_number`); log.info("db", "Migrated legacy column index → index_number"); } catch {}
    cols.push("index_number");
  }
  for (const [name, def] of Object.entries(migrations)) {
    if (cols.includes(name)) continue;
    try { db.run(`ALTER TABLE jobs ADD COLUMN ${name} ${def}`); log.info("db", `migrated: +jobs.${name}`); }
    catch (e) { log.warn("db", `migration failed for ${name}: ${(e as Error).message}`); }
  }
  // normalise legacy statuses into the V6 vocabulary
  try {
    db.run(`UPDATE jobs SET download_status = 'not_started' WHERE download_status = 'pending'`);
    db.run(`UPDATE jobs SET metadata_status = 'pending' WHERE metadata_status IS NULL OR metadata_status = ''`);
  } catch {}

  db.run(`INSERT INTO meta(key,value) VALUES('schema_version',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value`, [String(SCHEMA_VERSION)]);
  db.run(`INSERT INTO meta(key,value) VALUES('engine_version',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value`, [ENGINE_VERSION]);

  log.attachDb((lvl, scope, msg) => {
    try {
      db.run(`INSERT INTO events(level,scope,message) VALUES(?,?,?)`, [lvl, scope, truncate(msg, 900)]);
      db.run(`DELETE FROM events WHERE seq < (SELECT MAX(seq) - 5000 FROM events)`);
    } catch { /* non-fatal */ }
  });

  log.ok("db", `Central database ready @ ${resolve(DB_PATH)} (schema v${SCHEMA_VERSION}, WAL)`);
}

/* ---- crash reconciliation: downloading → paused (resume later) ----------- */
function reconcileCrashedJobs() {
  const res = db.prepare(`
    UPDATE jobs SET
      download_status = CASE WHEN download_status = 'downloading' THEN 'paused' ELSE download_status END,
      conversion_status = CASE WHEN conversion_status = 'in_progress' THEN 'pending' ELSE conversion_status END,
      metadata_status = CASE WHEN metadata_status = 'downloading' THEN 'pending' ELSE metadata_status END,
      download_claimed_by = NULL, download_claimed_ms = NULL,
      conversion_claimed_by = NULL, conversion_claimed_ms = NULL,
      metadata_claimed_by = NULL, metadata_claimed_ms = NULL,
      progress = CASE WHEN download_status = 'downloading' THEN COALESCE(progress,0) ELSE progress END,
      updated_at = datetime('now')
    WHERE download_status = 'downloading' OR conversion_status = 'in_progress' OR metadata_status = 'downloading'
  `).run();
  const n = (res as any).changes ?? 0;
  if (n > 0) log.warn("db", `Reconciled ${n} interrupted job(s) → paused/pending (resume continues from .part files).`);
  return n;
}

/* ---- atomic claim helpers (no two workers ever touch the same row) ------- */

const claimDownloadJob = db0 => db0; // placeholder replaced after db init
function makeClaimers() {
  const claimDownload = db.transaction((workerId: string) => {
    return db.query(`
      UPDATE jobs SET
        download_status = 'downloading',
        download_claimed_by = ?,
        download_claimed_ms = ?,
        heartbeat_ms = ?,
        started_at = COALESCE(started_at, datetime('now')),
        last_error = NULL, error_code = NULL,
        updated_at = datetime('now')
      WHERE id = (
        SELECT id FROM jobs
        WHERE download_status IN ('not_started','paused')
        ORDER BY CASE WHEN download_status = 'paused' THEN 0 ELSE 1 END, index_number ASC, created_at ASC
        LIMIT 1
      ) RETURNING *
    `).get(workerId, nowMs(), nowMs()) as JobRow | null;
  });

  const claimMetadataJob = db.transaction((workerId: string) => {
    return db.query(`
      UPDATE jobs SET
        metadata_status = 'downloading',
        metadata_claimed_by = ?,
        metadata_claimed_ms = ?,
        heartbeat_ms = ?,
        updated_at = datetime('now')
      WHERE id = (
        SELECT id FROM jobs
        WHERE download_status = 'downloaded' AND metadata_status = 'pending'
        ORDER BY completed_at ASC, created_at ASC
        LIMIT 1
      ) RETURNING *
    `).get(workerId, nowMs(), nowMs()) as JobRow | null;
  });

  const claimConvertJob = db.transaction((workerId: string) => {
    return db.query(`
      UPDATE jobs SET
        conversion_status = 'in_progress',
        conversion_claimed_by = ?,
        conversion_claimed_ms = ?,
        heartbeat_ms = ?,
        updated_at = datetime('now')
      WHERE id = (
        SELECT id FROM jobs
        WHERE download_status = 'downloaded'
          AND conversion_status = 'pending'
          AND (metadata_status IN ('done','not_needed','failed'))
        ORDER BY completed_at ASC, created_at ASC
        LIMIT 1
      ) RETURNING *
    `).get(workerId, nowMs(), nowMs()) as JobRow | null;
  });

  return { claimDownload, claimMetadataJob, claimConvertJob };
}
let claimers: ReturnType<typeof makeClaimers>;

/* ---- stale claim reaper (worker died without graceful shutdown) ---------- */
function reapStaleClaims(timeoutMs: number) {
  const cutoff = nowMs() - timeoutMs;
  const r1 = db.prepare(`
    UPDATE jobs SET download_status='paused', download_claimed_by=NULL, download_claimed_ms=NULL, updated_at=datetime('now')
    WHERE download_status='downloading' AND COALESCE(heartbeat_ms, download_claimed_ms, 0) < ?
  `).run(cutoff);
  const r2 = db.prepare(`
    UPDATE jobs SET metadata_status='pending', metadata_claimed_by=NULL, metadata_claimed_ms=NULL, updated_at=datetime('now')
    WHERE metadata_status='downloading' AND COALESCE(heartbeat_ms, metadata_claimed_ms, 0) < ?
  `).run(cutoff);
  const r3 = db.prepare(`
    UPDATE jobs SET conversion_status='pending', conversion_claimed_by=NULL, conversion_claimed_ms=NULL, updated_at=datetime('now')
    WHERE conversion_status='in_progress' AND COALESCE(heartbeat_ms, conversion_claimed_ms, 0) < ?
  `).run(cutoff);
  const n = ((r1 as any).changes ?? 0) + ((r2 as any).changes ?? 0) + ((r3 as any).changes ?? 0);
  if (n) log.warn("reaper", `Reclaimed ${n} stale claim(s) with no heartbeat.`);
  return n;
}

/* ---- aggregate queries --------------------------------------------------- */
function dbStats() {
  const s = db.query(`
    SELECT
      COUNT(*)                                                              AS total,
      SUM(CASE WHEN download_status = 'not_started'  THEN 1 ELSE 0 END)      AS not_started,
      SUM(CASE WHEN download_status = 'paused'       THEN 1 ELSE 0 END)      AS paused,
      SUM(CASE WHEN download_status = 'downloading'  THEN 1 ELSE 0 END)      AS downloading,
      SUM(CASE WHEN download_status = 'downloaded'   THEN 1 ELSE 0 END)      AS downloaded,
      SUM(CASE WHEN download_status = 'skipped'      THEN 1 ELSE 0 END)      AS skipped,
      SUM(CASE WHEN download_status = 'failed' OR conversion_status='failed' OR metadata_status='failed' THEN 1 ELSE 0 END) AS failed,
      SUM(CASE WHEN metadata_status = 'pending'      THEN 1 ELSE 0 END)      AS metadata_pending,
      SUM(CASE WHEN metadata_status = 'downloading'  THEN 1 ELSE 0 END)      AS metadata_active,
      SUM(CASE WHEN metadata_status = 'done'         THEN 1 ELSE 0 END)      AS metadata_done,
      SUM(CASE WHEN conversion_status = 'pending'    THEN 1 ELSE 0 END)      AS convert_pending,
      SUM(CASE WHEN conversion_status = 'in_progress' THEN 1 ELSE 0 END)     AS convert_active,
      SUM(CASE WHEN conversion_status = 'done'       THEN 1 ELSE 0 END)      AS convert_done,
      COALESCE(SUM(file_size),0)                                             AS bytes_stored
    FROM jobs
  `).get() as Record<string, number>;
  const out: Record<string, number> = {};
  for (const k of Object.keys(s)) out[k] = Number(s[k] ?? 0);
  return out;
}

function folderStats() {
  return db.query(`
    SELECT j.folder,
           MAX(j.output_directory) AS output_directory,
           COALESCE(ps.next_index, 0) AS next_index,
           COUNT(*) AS jobs,
           SUM(CASE WHEN j.download_status='downloaded' THEN 1 ELSE 0 END) AS downloaded,
           SUM(CASE WHEN j.download_status='not_started' OR j.download_status='paused' THEN 1 ELSE 0 END) AS queued,
           SUM(CASE WHEN j.download_status='downloading' THEN 1 ELSE 0 END) AS downloading,
           SUM(CASE WHEN j.download_status='failed' THEN 1 ELSE 0 END) AS failed,
           COALESCE(SUM(j.file_size),0) AS bytes
    FROM jobs j LEFT JOIN playlist_state ps ON ps.folder = j.folder
    GROUP BY j.folder ORDER BY j.folder
  `).all() as unknown as Record<string, unknown>[];
}

function isVideoInDb(videoId: string): boolean {
  return !!db.query("SELECT id FROM jobs WHERE id = ?").get(videoId);
}

const getNextIndex = db.transaction((folder: string): number => {
  const row = db.query("SELECT next_index FROM playlist_state WHERE folder = ?").get(folder) as { next_index: number } | null;
  const next = (row?.next_index || 0) + 1;
  db.run(
    `INSERT INTO playlist_state (folder, next_index, updated_at) VALUES (?,?,datetime('now'))
     ON CONFLICT(folder) DO UPDATE SET next_index = excluded.next_index, updated_at = datetime('now')`,
    [folder, next],
  );
  return next;
});

/* ==========================================================================
   7. GLOBAL RUNTIME STATE
   ========================================================================== */

let globalIsPaused = false;
let pauseReason: string | null = null;
let bootError: string | null = null;

const workerStatuses = new Map<string, string>();
const stats = { downloaded: 0, skipped: 0, failed: 0, converted: 0, totalQueued: 0, bytes: 0 };
const abortController = new AbortController();
const abortSignal = abortController.signal;
let isTTY = !!process.stdout.isTTY && globalConfig.enableTui;
let webServer: ReturnType<typeof Bun.serve> | null = null;
let shuttingDown = false;
let currentRunId: number | null = null;

const activeProcs = new Map<string, ReturnType<typeof Bun.spawn>>();

const autoscaler = {
  enabled: true, targetWorkers: 3, minWorkers: 1, maxWorkers: 5, maxBandwidthKBps: 0,
  workerSpeeds: new Map<string, number>(),
  init(c: Config) {
    this.enabled = c.autoscaleEnabled;
    this.minWorkers = c.minDownloadWorkers;
    this.maxWorkers = c.maxDownloadWorkers;
    this.maxBandwidthKBps = c.maxBandwidthKBps;
    this.targetWorkers = clamp(c.maxConcurrentDownloads, this.minWorkers, this.maxWorkers);
  },
  recordSpeed(id: string, bps: number) { if (bps > 0) this.workerSpeeds.set(id, bps); },
  clearWorker(id: string) { this.workerSpeeds.delete(id); },
  getAggregateSpeed() { let s = 0; for (const v of this.workerSpeeds.values()) s += v; return s; },
  /** Grow/shrink target workers based on measured throughput and queue pressure. */
  tune(queueDepth: number) {
    if (!this.enabled) return this.targetWorkers;
    const capBps = this.maxBandwidthKBps > 0 ? this.maxBandwidthKBps * 1024 : 0;
    const agg = this.getAggregateSpeed();
    let next = this.targetWorkers;
    if (queueDepth > 0 && (capBps === 0 || agg < capBps * 0.92)) next = Math.min(this.maxWorkers, next + 1);
    if (capBps > 0 && agg > capBps * 0.99) next = Math.max(this.minWorkers, next - 1);
    if (queueDepth === 0) next = this.minWorkers;
    this.targetWorkers = clamp(next, this.minWorkers, this.maxWorkers);
    return this.targetWorkers;
  },
};

const aliveDownloadWorkers = new Set<string>();
const aliveMetadataWorkers = new Set<string>();
const aliveConvertWorkers  = new Set<string>();

/* ==========================================================================
   8. RESILIENCE: PAUSE / RESUME / NETWORK / DISK
   ========================================================================== */

function triggerPause(reason: string) {
  if (globalIsPaused && pauseReason === reason) return;
  globalIsPaused = true;
  pauseReason = reason;
  log.warn("engine", `⏸️  PAUSE — ${reason}`);
  for (const [id, proc] of activeProcs.entries()) {
    try { proc.kill("SIGINT"); } catch { /* already gone */ }
  }
}
function triggerResume(opts: { clearPaused?: boolean } = {}) {
  if (!globalIsPaused && !opts.clearPaused) return;
  globalIsPaused = false;
  pauseReason = null;
  if (opts.clearPaused) {
    const r = db.prepare(`UPDATE jobs SET download_status='not_started', download_claimed_by=NULL, download_claimed_ms=NULL, updated_at=datetime('now') WHERE download_status='paused'`).run();
    log.ok("engine", `▶️  RESUME — ${(r as any).changes ?? 0} paused job(s) requeued.`);
  } else {
    log.ok("engine", "▶️  RESUME — workers unblocked.");
  }
}

async function networkMonitor() {
  let fails = 0;
  log.info("net", "Network monitor online (15s interval).");
  while (!abortSignal.aborted) {
    const up = await checkInternet();
    if (!up) {
      fails++;
      if (fails === 2 && !globalIsPaused) { triggerPause("NETWORK_DISCONNECTED"); }
      else if (fails > 2 && fails % 10 === 0) log.warn("net", `Still offline (${fails} consecutive failed probes).`);
    } else {
      if (fails > 0) {
        log.ok("net", "Network restored.");
        fails = 0;
        if (pauseReason === "NETWORK_DISCONNECTED") triggerResume();
      }
    }
    await sleep(15_000);
  }
}

async function diskMonitor() {
  while (!abortSignal.aborted) {
    const d = await checkDiskSpace(globalConfig.outputRoot, globalConfig.minFreeSpaceGB);
    if (d.error) log.warn("disk", d.error);
    else if (!d.ok && !globalIsPaused) {
      triggerPause(`LOW_DISK_SPACE (${d.freeGB.toFixed(1)}GB < ${globalConfig.minFreeSpaceGB}GB)`);
    } else if (d.ok && pauseReason?.startsWith("LOW_DISK_SPACE")) {
      log.ok("disk", `Space recovered (${d.freeGB.toFixed(1)}GB free).`);
      triggerResume();
    }
    await sleep(30_000);
  }
}

function reaperLoop() {
  const t = setInterval(() => {
    if (abortSignal.aborted) return clearInterval(t);
    try { reapStaleClaims(globalConfig.claimTimeoutSeconds * 1000); }
    catch (e) { log.error("reaper", "reap failed", e); }
  }, Math.max(5_000, globalConfig.claimTimeoutSeconds * 500));
  return t;
}

async function cleanOrphanedFiles(rootDir: string) {
  try {
    const failed = db.query(
      `SELECT partial_file_path FROM jobs WHERE download_status='failed' AND partial_file_path IS NOT NULL`,
    ).all() as unknown as { partial_file_path: string }[];
    const failedSet = new Set(failed.map(r => r.partial_file_path));
    const maxAgeMs = globalConfig.cleanOrphanedDays * 24 * 3600 * 1000;
    let removed = 0;
    const files = await readdir(rootDir, { recursive: true, encoding: "utf-8" }).catch(() => [] as string[]);
    for (const f of files as string[]) {
      if (!(f.endsWith(".part") || f.endsWith(".ytdl") || f.endsWith(".temp"))) continue;
      const full = join(rootDir, f);
      const st = await stat(full).catch(() => null);
      if (!st) continue;
      const stale = maxAgeMs > 0 && (Date.now() - st.mtimeMs) > maxAgeMs;
      // never delete a partial belonging to a live/paused job
      const owner = db.query(`SELECT download_status FROM jobs WHERE partial_file_path = ?`).get(full) as { download_status: string } | null;
      if (owner && ["downloading", "paused", "not_started"].includes(owner.download_status)) continue;
      if (failedSet.has(full) || stale || !owner) {
        await rm(full, { force: true }).catch(() => {});
        removed++;
      }
    }
    if (removed) log.ok("housekeeping", `Removed ${removed} orphaned partial file(s).`);
  } catch (e) { log.warn("housekeeping", `orphan scan skipped: ${(e as Error).message}`); }
}

/* ==========================================================================
   9. SCANNING & INGESTION  →  central DB, status = not_started
   ========================================================================== */

interface ScannedItem {
  id: string; title: string; playlist: string; duration: number;
  channel: string; uploadDate: string; index: number;
}

async function getPlaylistItems(url: string, config: Config): Promise<{ items: ScannedItem[]; error?: string }> {
  const args = [
    ...cookiesArgs(config),
    "--flat-playlist", "--no-warnings", "--ignore-config",
    "--print", "%(playlist_title)s|||%(id)s|||%(title)s|||%(duration)s|||%(channel)s|||%(upload_date)s|||%(playlist_index)s",
    "--extractor-retries", "3", "--socket-timeout", String(config.socketTimeout),
    url,
  ];
  const r = await runCmd("yt-dlp", args, { timeoutMs: 10 * 60_000 });
  if (r.code !== 0) {
    const msg = truncate((r.stderr || r.stdout || `exit ${r.code}`).trim(), 400);
    return { items: [], error: msg };
  }
  const items: ScannedItem[] = [];
  for (const line of r.stdout.split("\n")) {
    const t = line.trim();
    if (!t) continue;
    const p = t.split("|||");
    const id = (p[1] || "").trim();
    if (!id || id.toLowerCase() === "na") continue;
    items.push({
      id,
      title: ((p[2] || "video") === "NA" ? "video" : (p[2] || "video")).trim(),
      playlist: ((p[0] || "playlist") === "NA" ? "playlist" : (p[0] || "playlist")).trim(),
      duration: safeNum(p[3], 0),
      channel: (p[4] || "").trim() === "NA" ? "" : (p[4] || "").trim(),
      uploadDate: (p[5] || "").trim() === "NA" ? "" : (p[5] || "").trim(),
      index: safeNum(p[6], 0),
    });
  }
  return { items };
}

async function validateCookies(cookiesFile: string): Promise<boolean> {
  if (!existsSync(cookiesFile)) return false;
  const r = await runCmd(
    "yt-dlp",
    ["--cookies", cookiesFile, "--no-warnings", "--skip-download", "--print", "%(id)s", "https://www.youtube.com/watch?v=dQw4w9WgXcQ"],
    { timeoutMs: 60_000 },
  );
  return r.code === 0 && !r.stderr.toLowerCase().includes("login required");
}

/**
 * Ingest one source URL into the central database.
 * Every row is created with:
 *   download_status = 'not_started'
 *   target_format   = final container/codec after conversion
 *   want_*          = subtitles / thumbnail / description / info.json / metadata
 *   output_directory= exact folder the file must land in
 */
async function scanAndIngest(
  url: string, config: Config, overrideFolderName?: string, kind: "playlist" | "channel" | "channelPlaylist" = "playlist",
): Promise<{ scanned: number; added: number; skipped: number; folder: string; error?: string }> {
  const startedAt = Date.now();
  log.info("scan", `Scanning ${url}`);
  const { items, error } = await getPlaylistItems(url, config);

  db.run(
    `INSERT INTO sources(url,kind,folder,status,last_scanned_at,last_error,created_at)
     VALUES(?,?,?,?,datetime('now'),?,datetime('now'))
     ON CONFLICT(url) DO UPDATE SET kind=excluded.kind, status=excluded.status,
       last_scanned_at=datetime('now'), last_error=excluded.last_error`,
    [url, kind, overrideFolderName || null, error ? "error" : "scanned", error ? truncate(error) : null],
  );

  if (error) {
    log.error("scan", `Failed to scan ${url}: ${error}`);
    db.run(`UPDATE sources SET item_count=0, added_count=0 WHERE url=?`, [url]);
    return { scanned: 0, added: 0, skipped: 0, folder: overrideFolderName || "", error };
  }
  if (items.length === 0) {
    log.warn("scan", `No items returned for ${url} (empty/private playlist?)`);
    return { scanned: 0, added: 0, skipped: 0, folder: overrideFolderName || "" };
  }

  const folder = sanitizeFolderName(
    overrideFolderName || config.folderOverrides?.[url] || items[0].playlist || "Single Videos",
  );
  const outputDir = join(config.outputRoot, folder);
  try { await mkdir(outputDir, { recursive: true }); }
  catch (e) { throw new Error(`Cannot create output directory ${outputDir}: ${(e as Error).message}`); }

  const isAudio = config.videoQuality === "audio";
  const targetFormat = isAudio ? (config.targetFormat === "mp4" || config.targetFormat === "mkv" || config.targetFormat === "webm" ? "mp3" : config.targetFormat) : config.targetFormat;
  const wantSubs   = config.downloadSubtitles ? 1 : 0;
  const wantThumb  = config.writeThumbnail ? 1 : 0;
  const wantDesc   = config.writeDescription ? 1 : 0;
  const wantInfo   = config.writeInfoJson ? 1 : 0;
  const wantMeta   = config.embedMetadata ? 1 : 0;
  const verify     = config.verifyIntegrity ? 1 : 0;
  // metadata worker has something to do only if a sidecar/metadata flag is on
  const needsMeta  = (wantSubs || wantThumb || wantDesc || wantInfo || wantMeta) ? "pending" : "not_needed";
  // conversion is needed unless we already download straight into the target container
  const needsConv  = isAudio ? "pending" : (targetFormat === "mp4" ? "not_needed" : "pending");

  let added = 0, skipped = 0;
  const insert = db.transaction((rows: ScannedItem[]) => {
    const stmt = db.prepare(`
      INSERT OR IGNORE INTO jobs (
        id, url, title, channel, playlist_title, duration_seconds, upload_date,
        folder, index_number, output_directory, video_quality, target_format,
        want_subtitles, want_thumbnail, want_description, want_infojson, want_metadata, verify_integrity,
        download_status, metadata_status, conversion_status, source_url, created_at, updated_at
      ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'not_started',?,?,?,datetime('now'),datetime('now'))
    `);
    for (const it of rows) {
      if (isVideoInDb(it.id)) { skipped++; continue; }
      const isShort = it.duration > 0 && it.duration < 60;
      if (isShort && config.skipShorts && !config.downloadShorts) {
        const idx = getNextIndex(folder);
        stmt.run(
          it.id, `https://www.youtube.com/watch?v=${it.id}`, it.title, it.channel || null, it.playlist || folder,
          it.duration, it.uploadDate || null, folder, idx, outputDir, config.videoQuality, targetFormat,
          wantSubs, wantThumb, wantDesc, wantInfo, wantMeta, verify,
          "skipped", "not_needed", "not_needed", url,
        );
        db.run(`UPDATE jobs SET last_error='Skipped: YouTube Short (<60s)' WHERE id=?`, [it.id]);
        stats.skipped++;
        continue;
      }
      if (!config.archiveLiveStreams && it.duration === 0) {
        // live/unknown duration: still queue, engine will re-probe at download time
      }
      const idx = it.index > 0 ? it.index : getNextIndex(folder);
      if (it.index <= 0) getNextIndex(folder);
      stmt.run(
        it.id, `https://www.youtube.com/watch?v=${it.id}`, it.title, it.channel || null, it.playlist || folder,
        it.duration, it.uploadDate || null, folder, idx, outputDir, config.videoQuality, targetFormat,
        wantSubs, wantThumb, wantDesc, wantInfo, wantMeta, verify,
        needsMeta, needsConv, url,
      );
      added++;
    }
  });

  try { insert(items); }
  catch (e) {
    const msg = (e as Error).message;
    db.run(`UPDATE sources SET status='error', last_error=? WHERE url=?`, [truncate(msg), url]);
    log.error("scan", `Ingest transaction failed for ${url}`, e);
    return { scanned: items.length, added: 0, skipped: 0, folder, error: msg };
  }

  db.run(
    `UPDATE sources SET item_count=?, added_count=?, folder=?, title=?, status='scanned', last_error=NULL WHERE url=?`,
    [items.length, added, folder, items[0].playlist || null, url],
  );
  stats.totalQueued += added;
  log.ok("scan", `${folder}: ${items.length} item(s) → ${added} new, ${skipped} already known (${((Date.now() - startedAt) / 1000).toFixed(1)}s)`);
  return { scanned: items.length, added, skipped, folder };
}

/** Register every source from config.json, then ingest with bounded concurrency. */
async function ingestAllSources(config: Config) {
  const sources: { url: string; kind: "playlist" | "channel" | "channelPlaylist" }[] = [
    ...config.playlists.map(u => ({ url: u, kind: "playlist" as const })),
    ...config.channels.map(u => ({ url: u, kind: "channel" as const })),
    ...config.channelPlaylists.map(u => ({ url: u, kind: "channelPlaylist" as const })),
  ];
  if (sources.length === 0) {
    log.warn("scan", "No sources configured. The engine will idle — add URLs via config.json, update_config.ts or the Web UI.");
    return { total: 0, added: 0 };
  }
  let added = 0;
  const queue = [...sources];
  const worker = async () => {
    while (queue.length && !abortSignal.aborted) {
      const s = queue.shift()!;
      try {
        const r = await scanAndIngest(s.url, config, config.folderOverrides?.[s.url], s.kind);
        added += r.added;
      } catch (e) {
        log.error("scan", `Unhandled scan error for ${s.url}`, e);
        db.run(`INSERT INTO sources(url,kind,status,last_error) VALUES(?,?,'error',?)
                ON CONFLICT(url) DO UPDATE SET status='error', last_error=excluded.last_error`,
               [s.url, s.kind, truncate((e as Error).message)]);
      }
    }
  };
  const n = clamp(config.scanConcurrency, 1, 8);
  await Promise.all(Array.from({ length: n }, worker));
  log.ok("scan", `Ingestion complete — ${added} new job(s) queued as not_started.`);
  return { total: sources.length, added };
}

/* ==========================================================================
   10. DOWNLOAD WORKER
   ========================================================================== */

function jobOutTemplate(job: JobRow): string {
  const base = `${String(job.index_number || 0).padStart(3, "0")} - ${sanitizeFileName(job.title)}`;
  return join(job.output_directory, `${base}.%(ext)s`);
}

function heartbeat(jobId: string) {
  try { db.run(`UPDATE jobs SET heartbeat_ms = ? WHERE id = ?`, [nowMs(), jobId]); } catch {}
}

async function downloadWorker(id: number, config: Config) {
  const workerId = `dl-${id}`;
  aliveDownloadWorkers.add(workerId);
  updateWorkerLine(id, "— idle slot —", config);
  let hb: ReturnType<typeof setInterval> | null = null;

  while (!abortSignal.aborted) {
    try {
      if (globalIsPaused) { updateWorkerLine(id, `⏸️  paused (${pauseReason})`, config); await sleep(2000); continue; }
      if (!aliveDownloadWorkers.has(workerId)) break;

      const disk = await checkDiskSpace(config.outputRoot, config.minFreeSpaceGB);
      if (!disk.ok) {
        triggerPause(`LOW_DISK_SPACE (${disk.freeGB.toFixed(1)}GB < ${config.minFreeSpaceGB}GB)`);
        await sleep(5000);
        continue;
      }

      const job = claimers.claimDownload(workerId);
      if (!job) {
        updateWorkerLine(id, "💤 idle — queue empty", config);
        autoscaler.clearWorker(workerId);
        await sleep(750);
        continue;
      }

      hb = setInterval(() => heartbeat(job.id), Math.max(1000, config.heartbeatSeconds * 1000));
      const resumed = !!job.partial_file_path && existsSync(job.partial_file_path);
      updateWorkerLine(id, resumed ? `⏯️  Resuming @ ${job.progress.toFixed(1)}% | ${job.title}` : `⬇️  Starting… | ${job.title}`, config);
      log.info(workerId, `${resumed ? "Resuming" : "Downloading"} "${job.title}" → ${job.output_directory} [retry ${job.retry_count}]`);

      const format = QUALITY_FORMATS[job.video_quality || config.videoQuality] || QUALITY_FORMATS["1080p"];
      const outTemplate = jobOutTemplate(job);

      const args = [
        job.url,
        ...cookiesArgs(config),
        "--format", format,
        "--merge-output-format", job.target_format === "mp3" || job.target_format === "m4a" ? "m4a" : job.target_format,
        "--concurrent-fragments", String(config.concurrentFragments),
        "-o", outTemplate,
        "--restrict-filenames",
        "--no-overwrites",
        "--continue",                       // ← resume the paused .part from where it stopped
        "--progress", "--newline",
        "--progress-template", "download:PROGRESS:%(progress.percent)s|%(progress.speed)s|%(progress.eta)s|%(progress.total_bytes)s|%(progress.downloaded_bytes)s|%(progress.filename)s",
        "--socket-timeout", String(config.socketTimeout),
        "--retries", "10",
        "--retry-sleep", "5",
        "--fragment-retries", String(config.fragmentRetries),
        "--extractor-retries", "3",
        "--no-part" in {} ? "--no-part" : "--part",   // keep .part so resume works
        "--print", "after_move:filepath",
        "--windows-filenames",
      ].filter(a => a !== undefined);

      // sidecars handled during download when cheap; metadata worker fills gaps afterwards
      if (job.want_subtitles) args.push("--write-subs", "--write-auto-subs", "--sub-langs", config.subtitleLangs);
      if (job.want_thumbnail) args.push("--write-thumbnail", "--convert-thumbnails", "jpg");
      if (job.want_description) args.push("--write-description");
      if (job.want_infojson) args.push("--write-info-json");
      if (job.want_metadata) args.push("--embed-metadata", "--embed-chapters");
      if (config.maxBandwidthKBps > 0) args.push("--limit-rate", `${Math.floor(config.maxBandwidthKBps / Math.max(1, autoscaler.targetWorkers))}K`);

      const timeoutMs = config.downloadTimeoutMinutes * 60_000;
      const ac = new AbortController();
      const killer = setTimeout(() => ac.abort(), timeoutMs);
      let proc: ReturnType<typeof Bun.spawn>;
      try {
        proc = Bun.spawn(["yt-dlp", ...args], { stdout: "pipe", stderr: "pipe", stdin: "ignore", signal: ac.signal });
      } catch (e) {
        clearTimeout(killer);
        throw new Error(`Failed to spawn yt-dlp: ${(e as Error).message}`);
      }
      activeProcs.set(workerId, proc);

      let stdoutBuf = "", stderrBuf = "", finalFilePath: string | null = job.partial_file_path;
      let lastDbWrite = 0, lastTotalBytes = job.file_size || 0;

      const reader = proc.stdout.getReader();
      const dec = new TextDecoder();
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        stdoutBuf += dec.decode(value, { stream: true });
        const lines = stdoutBuf.split("\n");
        stdoutBuf = lines.pop() || "";
        for (const line of lines) {
          const l = line.trim();
          if (!l) continue;
          if (l.startsWith("PROGRESS:")) {
            const p = l.slice("PROGRESS:".length).split("|");
            const pct = safeNum(p[0], NaN);
            const bps = parseSpeedToBytesPerSec(p[1]);
            const eta = safeNum(p[2], 0);
            const total = safeNum(p[3], 0);
            const downloaded = safeNum(p[4], 0);
            const fname = (p[5] || "").trim();
            if (total > 0) lastTotalBytes = total;
            if (bps > 0) autoscaler.recordSpeed(workerId, bps);
            if (fname && !finalFilePath) finalFilePath = fname;
            if (Number.isFinite(pct) && nowMs() - lastDbWrite > 500) {
              lastDbWrite = nowMs();
              try {
                db.run(
                  `UPDATE jobs SET progress=?, speed=?, eta=?, file_size=?, downloaded_bytes=?, heartbeat_ms=?, updated_at=datetime('now') WHERE id=?`,
                  [clamp(pct, 0, 100), bps, eta, lastTotalBytes, downloaded, nowMs(), job.id],
                );
              } catch (e) { log.debug(workerId, `progress write failed: ${(e as Error).message}`); }
              const speedTxt = bps > 0 ? formatBytesPerSec(bps) : "calculating…";
              updateWorkerLine(id, `⬇️  ${clamp(pct, 0, 100).toFixed(1)}% @ ${speedTxt}${eta > 0 ? ` · ETA ${formatDuration(eta)}` : ""} | ${job.title}`, config);
            }
          } else if (existsSync(l)) {
            finalFilePath = l;
          }
        }
      }
      const errTask = new Response(proc.stderr).text().catch(() => "");
      const code = await proc.exited.catch(() => 1);
      stderrBuf = await errTask;
      clearTimeout(killer);
      activeProcs.delete(workerId);
      if (hb) { clearInterval(hb); hb = null; }

      // --- paused mid-flight (manual pause, network loss, shutdown) ---------
      if (globalIsPaused || abortSignal.aborted) {
        const partPath = finalFilePath && existsSync(finalFilePath) ? finalFilePath : job.partial_file_path;
        db.run(
          `UPDATE jobs SET download_status='paused', download_claimed_by=NULL, download_claimed_ms=NULL,
             partial_file_path=?, heartbeat_ms=NULL, updated_at=datetime('now') WHERE id=?`,
          [partPath || null, job.id],
        );
        autoscaler.clearWorker(workerId);
        updateWorkerLine(id, `⏸️  Paused (partial saved) | ${job.title}`, config);
        log.warn(workerId, `Paused mid-download, partial preserved: ${partPath || "n/a"}`);
        continue;
      }

      if (ac.signal.aborted) throw new Error(`Process timed out after ${config.downloadTimeoutMinutes}m`);

      if (code === 0) {
        let filePath = finalFilePath || "";
        if (!filePath || !existsSync(filePath)) {
          // locate the newest matching file in the destination folder
          filePath = await locateDownloadedFile(job) || filePath;
        }
        let fileSize = 0;
        if (filePath && existsSync(filePath)) fileSize = (await stat(filePath).catch(() => ({ size: 0 }))).size;

        const metaNeeded = (job.want_subtitles || job.want_thumbnail || job.want_description || job.want_infojson || job.want_metadata)
          ? "pending" : "not_needed";
        const convNeeded = job.target_format && extname(filePath || "").slice(1).toLowerCase() !== job.target_format
          ? "pending" : (job.conversion_status === "not_needed" ? "not_needed" : "pending");

        db.run(
          `UPDATE jobs SET
             download_status='downloaded', file_path=?, file_size=?, progress=100, speed=0, eta=0,
             partial_file_path=?, download_claimed_by=NULL, download_claimed_ms=NULL, heartbeat_ms=NULL,
             metadata_status=?, conversion_status=?, completed_at=datetime('now'), updated_at=datetime('now'),
             last_error=NULL, error_code=NULL
           WHERE id=?`,
          [filePath || null, fileSize, filePath || null, metaNeeded, convNeeded, job.id],
        );
        stats.downloaded++;
        stats.bytes += fileSize;
        autoscaler.clearWorker(workerId);
        updateWorkerLine(id, `✅ Downloaded ${formatBytes(fileSize)} | ${job.title}`, config);
        log.ok(workerId, `Downloaded "${job.title}" → ${filePath || job.output_directory} (${formatBytes(fileSize)})`);
        continue;
      }

      // --- failure path ----------------------------------------------------
      throw new Error(truncate((stderrBuf || stdoutBuf || `yt-dlp exit ${code}`).trim(), 900) || `yt-dlp exit ${code}`);

    } catch (err) {
      if (hb) { clearInterval(hb); hb = null; }
      activeProcs.delete(workerId);
      autoscaler.clearWorker(workerId);
      const job = lastClaimedJob.get(workerId);
      const msg = err instanceof Error ? (err.stack ? err.message : String(err)) : String(err);

      if (globalIsPaused || abortSignal.aborted) {
        if (job) db.run(`UPDATE jobs SET download_status='paused', download_claimed_by=NULL, heartbeat_ms=NULL, updated_at=datetime('now') WHERE id=?`, [job]);
        updateWorkerLine(id, `⏸️  Paused | ${job || ""}`, config);
        continue;
      }
      if (!job) { log.error(workerId, `Worker error with no active job: ${msg}`); await sleep(2000); continue; }

      const cls = classifyError(msg);
      const row = db.query(`SELECT retry_count, title, partial_file_path, max_retry FROM jobs WHERE 1=0`).get();
      const cur = db.query(`SELECT retry_count, title, partial_file_path FROM jobs WHERE id=?`).get(job) as { retry_count: number; title: string; partial_file_path: string | null } | null;
      const retryCount = (cur?.retry_count ?? 0) + 1;

      log.error(workerId, `${cls.kind} on "${cur?.title ?? job}" (attempt ${retryCount}/${config.maxRetryAttempts}): ${msg.split("\n")[0]}`);

      // 1) signature challenge → self-heal yt-dlp then retry immediately
      if (cls.kind === "SIGNATURE") {
        log.warn(workerId, "Signature challenge — auto-updating yt-dlp…");
        const up = await runCmd("yt-dlp", ["-U"], { timeoutMs: 120_000 });
        log.info(workerId, up.code === 0 ? `yt-dlp updated: ${up.stdout.trim().split("\n").pop()}` : `yt-dlp update failed: ${truncate(up.stderr, 200)}`);
        db.run(`UPDATE jobs SET download_status='not_started', retry_count=0, download_claimed_by=NULL, heartbeat_ms=NULL,
                error_code=?, last_error=?, updated_at=datetime('now') WHERE id=?`, [cls.kind, truncate(msg), job]);
        updateWorkerLine(id, `🔄 yt-dlp updated, requeued | ${cur?.title}`, config);
        await sleep(1500);
        continue;
      }

      // 2) corrupt partial → delete and restart clean
      if (cls.kind === "CORRUPT_PARTIAL") {
        const part = cur?.partial_file_path;
        if (part && existsSync(part)) { await unlink(part).catch(() => {}); log.warn(workerId, `Deleted corrupt partial ${part}`); }
        for (const suffix of [".part", ".ytdl", ".temp"]) {
          if (part && existsSync(part + suffix)) await unlink(part + suffix).catch(() => {});
        }
        db.run(`UPDATE jobs SET download_status='not_started', progress=0, partial_file_path=NULL, download_claimed_by=NULL,
                heartbeat_ms=NULL, error_code=?, last_error=?, updated_at=datetime('now') WHERE id=?`, [cls.kind, truncate(msg), job]);
        updateWorkerLine(id, `🗑️  Corrupt partial removed, restarting | ${cur?.title}`, config);
        await sleep(1000);
        continue;
      }

      // 3) permanently unavailable → skipped (never retried again)
      if (cls.permanent && (cls.kind === "UNAVAILABLE" || cls.kind === "PRIVATE" || cls.kind === "GEO_BLOCKED")) {
        db.run(`UPDATE jobs SET download_status='skipped', download_claimed_by=NULL, heartbeat_ms=NULL, speed=0,
                error_code=?, last_error=?, updated_at=datetime('now'), completed_at=datetime('now') WHERE id=?`, [cls.kind, truncate(msg), job]);
        stats.skipped++;
        updateWorkerLine(id, `⏭️  Skipped (${cls.kind}) | ${cur?.title}`, config);
        continue;
      }

      // 4) transient → requeue with backoff, keep partial
      if (cls.kind === "TRANSIENT_NETWORK" || cls.kind === "RATE_LIMIT" || cls.kind === "TIMEOUT") {
        const backoff = cls.kind === "RATE_LIMIT" ? config.transientBackoffSeconds * 4 : config.transientBackoffSeconds;
        db.run(`UPDATE jobs SET download_status='not_started', download_claimed_by=NULL, heartbeat_ms=NULL, speed=0,
                retry_count=?, error_code=?, last_error=?, updated_at=datetime('now') WHERE id=?`,
               [cls.kind === "RATE_LIMIT" ? retryCount : (cur?.retry_count ?? 0), cls.kind, truncate(msg), job]);
        updateWorkerLine(id, `🌐 ${cls.kind} — backing off ${backoff}s | ${cur?.title}`, config);
        await sleep(backoff * 1000);
        continue;
      }

      // 5) disk full → pause the whole engine
      if (cls.kind === "DISK_FULL") {
        db.run(`UPDATE jobs SET download_status='paused', download_claimed_by=NULL, heartbeat_ms=NULL, error_code=?, last_error=?, updated_at=datetime('now') WHERE id=?`, [cls.kind, truncate(msg), job]);
        triggerPause("DISK_FULL");
        continue;
      }

      // 6) generic → retry until maxRetryAttempts / maxFailuresPerVideo
      const exhausted = retryCount >= Math.min(config.maxRetryAttempts, config.maxFailuresPerVideo);
      const newStatus: DownloadStatus = exhausted ? "failed" : "not_started";
      db.run(`UPDATE jobs SET download_status=?, retry_count=?, download_claimed_by=NULL, heartbeat_ms=NULL, speed=0,
              error_code=?, last_error=?, updated_at=datetime('now') WHERE id=?`,
             [newStatus, retryCount, cls.kind, truncate(msg), job]);
      if (exhausted) {
        stats.failed++;
        const globalFails = db.query(`SELECT COUNT(*) AS c FROM jobs WHERE download_status='failed'`).get() as { c: number };
        log.error(workerId, `Job permanently failed: ${cur?.title} — ${cls.userFix}`);
        updateWorkerLine(id, `❌ Failed (${cls.kind}) | ${cur?.title}`, config);
        if ((globalFails?.c ?? 0) >= config.maxFailures && !globalIsPaused) {
          triggerPause(`MAX_FAILURES_REACHED (${globalFails.c} failed ≥ ${config.maxFailures})`);
        }
      } else {
        updateWorkerLine(id, `♻️  Requeued (${retryCount}/${config.maxRetryAttempts}) | ${cur?.title}`, config);
        await sleep(2000);
      }
    } finally {
      if (hb) { clearInterval(hb); hb = null; }
      activeProcs.delete(workerId);
      autoscaler.clearWorker(workerId);
    }
  }
  aliveDownloadWorkers.delete(workerId);
  log.info(`dl-${id}`, "download worker stopped");
}

/** Track the job currently owned by a worker so the catch-block can update it. */
const lastClaimedJob = new Map<string, string>();

/** Patch: wrap claim so we always know which job a worker owns. */
function bindClaimTracking() {
  const origDownload = claimers.claimDownload;
  (claimers as any).claimDownload = (workerId: string) => {
    const j = origDownload(workerId);
    if (j) { lastClaimedJob.set(workerId, j.id); db.run(`UPDATE jobs SET progress=COALESCE(progress,0) WHERE id=?`, [j.id]); }
    else lastClaimedJob.delete(workerId);
    return j;
  };
  const origMeta = claimers.claimMetadataJob;
  (claimers as any).claimMetadataJob = (workerId: string) => { const j = origMeta(workerId); if (j) lastClaimedJob.set(workerId, j.id); return j; };
  const origConv = claimers.claimConvertJob;
  (claimers as any).claimConvertJob = (workerId: string) => { const j = origConv(workerId); if (j) lastClaimedJob.set(workerId, j.id); return j; };
}

/** Best-effort discovery of the finished file inside the job's destination. */
async function locateDownloadedFile(job: JobRow): Promise<string | null> {
  try {
    const base = `${String(job.index_number || 0).padStart(3, "0")} - ${sanitizeFileName(job.title)}`;
    const files = await readdir(job.output_directory).catch(() => [] as string[]);
    const exact = files.find(f => f.startsWith(base) && !f.endsWith(".part") && !f.endsWith(".ytdl"));
    if (exact) return join(job.output_directory, exact);
    const byId = files.find(f => f.includes(job.id) && !f.endsWith(".part"));
    if (byId) return join(job.output_directory, byId);
    const recent = files
      .filter(f => !f.endsWith(".part") && !f.endsWith(".ytdl"))
      .map(f => ({ f, m: statSync(join(job.output_directory, f)).mtimeMs }))
      .sort((a, b) => b.m - a.m)[0];
    if (recent && Date.now() - recent.m < 5 * 60_000) return join(job.output_directory, recent.f);
  } catch {}
  return null;
}

/* ==========================================================================
   11. METADATA WORKER  (sidecars into the video's own folder)
   ========================================================================== */

async function metadataWorker(id: number, config: Config) {
  const workerId = `md-${id}`;
  aliveMetadataWorkers.add(workerId);
  let hb: ReturnType<typeof setInterval> | null = null;

  while (!abortSignal.aborted) {
    try {
      if (globalIsPaused) { await sleep(2000); continue; }
      const job = claimers.claimMetadataJob(workerId);
      if (!job) { await sleep(1500); continue; }

      hb = setInterval(() => heartbeat(job.id), Math.max(1000, config.heartbeatSeconds * 1000));
      log.info(workerId, `Fetching metadata for "${job.title}" → ${job.output_directory}`);
      updateMetaLine(id, `🏷️  ${job.title}`, config);

      await mkdir(job.output_directory, { recursive: true });
      const outTemplate = jobOutTemplate(job);
      const args = [
        job.url, ...cookiesArgs(config),
        "--skip-download", "--no-warnings", "--restrict-filenames",
        "--no-overwrites", "--ignore-errors",
        "-o", outTemplate,
        "--socket-timeout", String(config.socketTimeout),
        "--retries", "5",
      ];
      if (job.want_subtitles)   args.push("--write-subs", "--write-auto-subs", "--sub-langs", config.subtitleLangs, "--convert-subs", "srt");
      if (job.want_thumbnail)   args.push("--write-thumbnail", "--convert-thumbnails", "jpg");
      if (job.want_description) args.push("--write-description");
      if (job.want_infojson)    args.push("--write-info-json");

      const r = await runCmd("yt-dlp", args, { timeoutMs: 5 * 60_000 });

      // Verify at least one sidecar landed; if not, fall back to a raw JSON dump.
      const produced = await listSidecars(job);
      if (produced.length === 0) {
        log.warn(workerId, `yt-dlp produced no sidecars (exit ${r.code}); writing info.json from JSON dump.`);
        const j = await runCmd("yt-dlp", [job.url, ...cookiesArgs(config), "--skip-download", "-J", "--no-warnings"], { timeoutMs: 5 * 60_000 });
        if (j.code === 0 && j.stdout.trim().startsWith("{")) {
          const base = join(job.output_directory, `${String(job.index_number).padStart(3, "0")} - ${sanitizeFileName(job.title)}`);
          await writeFile(`${base}.info.json`, j.stdout, "utf-8").catch(() => {});
          try {
            const info = JSON.parse(j.stdout);
            if (job.want_description && info.description) await writeFile(`${base}.description`, String(info.description), "utf-8");
            if (!job.title || job.title === "video") db.run(`UPDATE jobs SET title=? WHERE id=?`, [String(info.title || job.title), job.id]);
            if (info.duration) db.run(`UPDATE jobs SET duration_seconds=? WHERE id=?`, [safeNum(info.duration, 0), job.id]);
            if (info.channel) db.run(`UPDATE jobs SET channel=? WHERE id=?`, [String(info.channel), job.id]);
            if (info.upload_date) db.run(`UPDATE jobs SET upload_date=? WHERE id=?`, [String(info.upload_date), job.id]);
          } catch {}
          produced.push(`${base}.info.json`);
        } else {
          throw new Error(truncate(`metadata fetch failed: ${j.stderr || j.stdout || "empty JSON"}`, 400));
        }
      }

      // Embed metadata/chapters/thumbnail into the media file when requested.
      if (job.want_metadata && job.file_path && existsSync(job.file_path)) {
        const thumb = produced.find(p => /\.(jpg|jpeg|png|webp)$/i.test(p));
        const ffArgs = ["-y", "-i", job.file_path];
        if (thumb) ffArgs.push("-i", thumb, "-map", "0", "-map", "1", "-c", "copy", "-disposition:v:1", "attached_pic");
        else ffArgs.push("-map", "0", "-c", "copy");
        ffArgs.push(
          "-metadata", `title=${job.title}`,
          "-metadata", `artist=${job.channel || "YouTube"}`,
          "-metadata", `comment=${job.url}`,
          job.file_path + ".tmp" + extname(job.file_path),
        );
        const ff = await runCmd("ffmpeg", ffArgs, { timeoutMs: 10 * 60_000 });
        const tmp = job.file_path + ".tmp" + extname(job.file_path);
        if (ff.code === 0 && existsSync(tmp) && (await stat(tmp)).size > 0) {
          await rename(tmp, job.file_path).catch(async () => { await rm(job.file_path, { force: true }); await rename(tmp, job.file_path); });
          log.ok(workerId, `Embedded metadata into ${basename(job.file_path)}`);
        } else {
          await rm(tmp, { force: true }).catch(() => {});
          log.warn(workerId, `Metadata embedding skipped (ffmpeg exit ${ff.code}) — sidecars are still on disk.`);
        }
      }

      // write the flat archive record
      if (config.archiveFile) {
        await appendFile(config.archiveFile, `${job.id}\n`, "utf-8").catch(() => {});
      }

      db.run(
        `UPDATE jobs SET metadata_status='done', metadata_claimed_by=NULL, metadata_claimed_ms=NULL, heartbeat_ms=NULL,
           last_error=NULL, error_code=NULL, updated_at=datetime('now') WHERE id=?`,
        [job.id],
      );
      log.ok(workerId, `Metadata stored (${produced.length} file(s)) for "${job.title}"`);
      updateMetaLine(id, `✅ ${job.title}`, config);
    } catch (err) {
      const job = lastClaimedJob.get(workerId);
      const msg = err instanceof Error ? err.message : String(err);
      const cls = classifyError(msg);
      log.error(workerId, `Metadata failed: ${msg.split("\n")[0]}`);
      if (job) {
        const cur = db.query(`SELECT retry_count FROM jobs WHERE id=?`).get(job) as { retry_count: number } | null;
        const rc = (cur?.retry_count ?? 0);
        db.run(
          `UPDATE jobs SET metadata_status=?, metadata_claimed_by=NULL, metadata_claimed_ms=NULL, heartbeat_ms=NULL,
             error_code=?, last_error=?, updated_at=datetime('now') WHERE id=?`,
          [rc >= config.maxRetryAttempts ? "failed" : "pending", `META_${cls.kind}`, truncate(msg), job],
        );
      }
    } finally {
      if (hb) { clearInterval(hb); hb = null; }
    }
    await sleep(300);
  }
  aliveMetadataWorkers.delete(workerId);
  log.info(`md-${id}`, "metadata worker stopped");
}

async function listSidecars(job: JobRow): Promise<string[]> {
  const base = `${String(job.index_number || 0).padStart(3, "0")} - ${sanitizeFileName(job.title)}`;
  const files = await readdir(job.output_directory).catch(() => [] as string[]);
  const out: string[] = [];
  for (const f of files) {
    if (!f.startsWith(base)) continue;
    if (/\.(info\.json|description|jpg|jpeg|png|webp|srt|vtt|en\..*srt|.*\.srt|.*\.vtt)$/i.test(f)) out.push(join(job.output_directory, f));
  }
  return out;
}

/* ==========================================================================
   12. CONVERTER WORKER  (downloaded → target_format)
   ========================================================================== */

function ffmpegArgsFor(src: string, dst: string, target: string): string[] {
  switch (target) {
    case "mp3":
      return ["-y", "-i", src, "-vn", "-c:a", "libmp3lame", "-q:a", "2", "-map_metadata", "0", dst];
    case "m4a":
      return ["-y", "-i", src, "-vn", "-c:a", "aac", "-b:a", "192k", "-map_metadata", "0", dst];
    case "mkv":
      return ["-y", "-i", src, "-map", "0", "-c", "copy", "-map_metadata", "0", dst];
    case "webm":
      return ["-y", "-i", src, "-map", "0:v:0", "-map", "0:a?", "-c:v", "libvpx-vp9", "-b:v", "0", "-crf", "33", "-c:a", "libopus", "-map_metadata", "0", dst];
    case "mp4":
    default:
      return ["-y", "-i", src, "-map", "0:v:0", "-map", "0:a?", "-map", "0:s?", "-c:v", "copy", "-c:a", "aac",
              "-c:s", "mov_text", "-movflags", "+faststart", "-map_metadata", "0", dst];
  }
}

async function converterWorker(id: number, config: Config) {
  const workerId = `cv-${id}`;
  aliveConvertWorkers.add(workerId);
  let hb: ReturnType<typeof setInterval> | null = null;

  while (!abortSignal.aborted) {
    try {
      if (globalIsPaused) { await sleep(2000); continue; }
      const job = claimers.claimConvertJob(workerId);
      if (!job) { updateConvertWorkerLine(id, "💤 idle", config); await sleep(2000); continue; }

      hb = setInterval(() => heartbeat(job.id), Math.max(1000, config.heartbeatSeconds * 1000));
      const src = job.file_path;
      if (!src || !existsSync(src)) throw new Error(`Source file missing: ${src ?? "(null)"}`);

      const target = job.target_format || "mp4";
      const srcExt = extname(src).slice(1).toLowerCase();
      let finalPath = src;

      if (srcExt !== target) {
        updateConvertWorkerLine(id, `🎞️  ${srcExt} → ${target} | ${job.title}`, config);
        log.info(workerId, `Converting "${job.title}" ${srcExt} → ${target}`);
        const dst = src.replace(/\.[^.]+$/, `.${target}`);
        const r = await runCmd("ffmpeg", ffmpegArgsFor(src, dst, target), { timeoutMs: 3 * 60 * 60_000 });
        if (r.code !== 0) throw new Error(`FFmpeg conversion failed (${target}): ${truncate(r.stderr || r.stdout, 400)}`);
        if (!existsSync(dst) || (await stat(dst)).size === 0) throw new Error("FFmpeg produced an empty output file");

        if (config.deleteSourceAfterConvert) {
          await rm(src, { force: true }).catch(() => {});
          // remove sibling sidecar of the old container if it duplicates
        }
        finalPath = dst;
      } else {
        updateConvertWorkerLine(id, `🎞️  already ${target} | ${job.title}`, config);
      }

      // optional migration to secondary storage (NAS)
      if (config.secondaryStoragePath) {
        const destDir = join(config.secondaryStoragePath, job.folder);
        await mkdir(destDir, { recursive: true });
        const destPath = join(destDir, basename(finalPath));
        try {
          await rename(finalPath, destPath);
        } catch {
          await cp(finalPath, destPath, { force: true });
          await rm(finalPath, { force: true }).catch(() => {});
        }
        finalPath = destPath;
      }

      // integrity
      let integrity: string | null = null;
      if (job.verify_integrity || config.verifyIntegrity) {
        try { integrity = await hashFile(finalPath); }
        catch (e) { log.warn(workerId, `integrity hash failed: ${(e as Error).message}`); }
      }

      const size = (await stat(finalPath).catch(() => ({ size: 0 }))).size;
      db.run(
        `UPDATE jobs SET conversion_status='done', file_path=?, file_size=?, integrity=?, progress=100,
           conversion_claimed_by=NULL, conversion_claimed_ms=NULL, heartbeat_ms=NULL,
           last_error=NULL, error_code=NULL, completed_at=COALESCE(completed_at, datetime('now')), updated_at=datetime('now')
         WHERE id=?`,
        [finalPath, size, integrity, job.id],
      );
      stats.converted++;
      updateConvertWorkerLine(id, `✅ ${basename(finalPath)} ${integrity ? `· sha256:${integrity.slice(0, 10)}…` : ""}`, config);
      log.ok(workerId, `Converted "${job.title}" → ${finalPath} (${formatBytes(size)})${integrity ? " ✔ integrity" : ""}`);
    } catch (err) {
      const job = lastClaimedJob.get(workerId);
      const msg = err instanceof Error ? err.message : String(err);
      const cls = classifyError(msg);
      log.error(workerId, `Conversion failed: ${msg.split("\n")[0]}`);
      if (job) {
        const cur = db.query(`SELECT retry_count FROM jobs WHERE id=?`).get(job) as { retry_count: number } | null;
        const rc = (cur?.retry_count ?? 0) + 1;
        db.run(
          `UPDATE jobs SET conversion_status=?, retry_count=?, conversion_claimed_by=NULL, conversion_claimed_ms=NULL,
             heartbeat_ms=NULL, error_code=?, last_error=?, updated_at=datetime('now') WHERE id=?`,
          [rc >= config.maxRetryAttempts ? "failed" : "pending", rc, `CONV_${cls.kind}`, truncate(msg), job],
        );
        updateConvertWorkerLine(id, `❌ ${cls.kind} | ${msg.split("\n")[0].slice(0, 60)}`, config);
      }
    } finally {
      if (hb) { clearInterval(hb); hb = null; }
    }
  }
  aliveConvertWorkers.delete(workerId);
  log.info(`cv-${id}`, "converter worker stopped");
}

/* ==========================================================================
   13. TUI DASHBOARD
   ========================================================================== */

function initDashboard(config: Config) {
  if (!process.stdout.isTTY || !config.enableTui) { isTTY = false; return; }
  const cols = process.stdout.columns || 80;
  const rows = process.stdout.rows || 50;
  const lines = 3 + config.maxDownloadWorkers + config.maxConcurrentConverts + config.metadataWorkers;
  if (rows <= lines + 6 || cols < 70) {
    isTTY = false;
    log.warn("tui", "Terminal too small for the TUI dashboard — using scrolling logs instead.");
    return;
  }
  isTTY = true;
  process.stdout.write("\x1b[2J\x1b[1;1H");
  process.stdout.write(`\x1b[${lines + 1};${rows}r\x1b[${lines + 1};1H`);
  for (let i = 1; i <= lines; i++) process.stdout.write(`\x1b[${i};1H\x1b[2K`);
  for (let i = 1; i <= config.maxDownloadWorkers; i++) updateWorkerLine(i, "— idle slot —", config);
  for (let i = 1; i <= config.metadataWorkers; i++) updateMetaLine(i, "💤 idle", config);
  for (let i = 1; i <= config.maxConcurrentConverts; i++) updateConvertWorkerLine(i, "💤 idle", config);
}
function updateAbsoluteLine(row: number, text: string) {
  if (!isTTY) return;
  const cols = process.stdout.columns || 80;
  const plain = text.replace(/\x1b\[[0-9;]*m/g, "");
  const safe = (plain.length > cols - 1 ? plain.slice(0, cols - 4) + "…" : plain).padEnd(cols - 1, " ");
  process.stdout.write(`\x1b7\x1b[${row};1H\x1b[2K${safe}\x1b8`);
}
function updateWorkerLine(id: number, text: string, config: Config) {
  workerStatuses.set(`DL${id}`, text);
  updateAbsoluteLine(3 + id, `[DL${id}] ${text}`);
}
function updateMetaLine(id: number, text: string, config: Config) {
  workerStatuses.set(`MD${id}`, text);
  updateAbsoluteLine(3 + config.maxDownloadWorkers + id, `[MD${id}] ${text}`);
}
function updateConvertWorkerLine(id: number, text: string, config: Config) {
  workerStatuses.set(`CV${id}`, text);
  updateAbsoluteLine(3 + config.maxDownloadWorkers + config.metadataWorkers + id, `[CV${id}] ${text}`);
}
function resetTerminal() {
  if (!isTTY) return;
  const rows = process.stdout.rows || 50;
  process.stdout.write(`\x1b[1;${rows}r\x1b[${rows};1H`);
  isTTY = false;
}
function renderDashboard() {
  if (!isTTY) return;
  const s = dbStats();
  const agg = formatBytesPerSec(autoscaler.getAggregateSpeed());
  const cap = autoscaler.maxBandwidthKBps > 0 ? ` / cap ${formatBytesPerSec(autoscaler.maxBandwidthKBps * 1024)}` : "";
  const head = `🚀 V${ENGINE_VERSION} · DL ${aliveDownloadWorkers.size}/${autoscaler.targetWorkers} · MD ${aliveMetadataWorkers.size} · CV ${aliveConvertWorkers.size} | ${agg}${cap} | Q:${s.not_started} ⏸:${s.paused} ⬇:${s.downloading} ✓:${s.downloaded} 🏷:${s.metadata_pending} 🎞:${s.convert_pending} ✗:${s.failed}${globalIsPaused ? ` | ⏸ PAUSED (${pauseReason})` : ""}`;
  updateAbsoluteLine(1, head);
  updateAbsoluteLine(2, `   uptime ${formatDuration((Date.now() - BOOT_TIME) / 1000)} · disk ${""}${""}`);
}

/* ==========================================================================
   14. WEB UI + REST API
   ========================================================================== */

const json = (data: unknown, status = 200) =>
  Response.json(data, { status, headers: { "Cache-Control": "no-store" } });
const fail = (msg: string, status = 400, extra: Record<string, unknown> = {}) =>
  json({ ok: false, error: msg, ...extra }, status);

async function readBody(req: Request): Promise<Record<string, any>> {
  try {
    const t = await req.text();
    if (!t.trim()) return {};
    return JSON.parse(t) as Record<string, any>;
  } catch { throw new Error("Request body must be valid JSON"); }
}

function buildStatusPayload() {
  const s = dbStats();
  const workers: { id: string; type: string; status: string }[] = [];
  for (let i = 1; i <= globalConfig.maxDownloadWorkers; i++)
    workers.push({ id: `DL${i}`, type: "download", status: workerStatuses.get(`DL${i}`) || "Idle" });
  for (let i = 1; i <= globalConfig.metadataWorkers; i++)
    workers.push({ id: `MD${i}`, type: "metadata", status: workerStatuses.get(`MD${i}`) || "Idle" });
  for (let i = 1; i <= globalConfig.maxConcurrentConverts; i++)
    workers.push({ id: `CV${i}`, type: "convert", status: workerStatuses.get(`CV${i}`) || "Idle" });

  const mem = process.memoryUsage();
  const agg = autoscaler.getAggregateSpeed();

  // global ETA across active + queued work
  const remaining = db.query(
    `SELECT COALESCE(SUM(CASE WHEN download_status='downloading' AND file_size>0 THEN file_size*(1-COALESCE(progress,0)/100.0) ELSE 0 END),0) AS act,
            COALESCE(SUM(CASE WHEN download_status IN ('not_started','paused') AND file_size>0 THEN file_size ELSE 0 END),0) AS q
     FROM jobs`,
  ).get() as { act: number; q: number };
  const etaSec = agg > 0 ? (Number(remaining.act || 0) + Number(remaining.q || 0)) / agg : 0;

  // queue position = items ahead of the newest not_started job
  const qPos = s.not_started + s.paused;

  let disk = { free: "-- / --", percent: 0, freeGB: 0, totalGB: 0 };
  try {
    const st = statSync(globalConfig.outputRoot);
    void st;
  } catch {}

  return {
    ok: true,
    version: ENGINE_VERSION,
    stats: {
      total: s.total, totalQueued: s.not_started + s.paused + s.downloading,
      not_started: s.not_started, paused: s.paused, downloading: s.downloading,
      downloaded: s.downloaded, skipped: s.skipped, failed: s.failed,
      metadataPending: s.metadata_pending, metadataActive: s.metadata_active, metadataDone: s.metadata_done,
      convertPending: s.convert_pending, convertActive: s.convert_active, convertDone: s.convert_done,
      bytesStored: s.bytes_stored,
    },
    aggregateSpeed: formatBytesPerSec(agg),
    aggregateSpeedBps: agg,
    bandwidthCapKBps: autoscaler.maxBandwidthKBps,
    activeWorkers: aliveDownloadWorkers.size,
    targetWorkers: autoscaler.targetWorkers,
    maxWorkers: autoscaler.maxWorkers,
    minWorkers: autoscaler.minWorkers,
    workers,
    isPaused: globalIsPaused,
    pauseReason,
    bootError,
    queuePosition: qPos,
    globalETA: etaSec > 0 ? formatDuration(etaSec) : "--",
    globalETASeconds: etaSec,
    system: {
      cpu: "--", cpuPercent: 0,
      ram: `${(mem.rss / 1024 ** 3).toFixed(2)} GB / ${(os.totalmem() / 1024 ** 3).toFixed(2)} GB`,
      ramPercent: Number(((mem.rss / os.totalmem()) * 100).toFixed(1)),
      platform: `${process.platform}/${process.arch}`,
      loadavg: os.loadavg().map(n => Number(n.toFixed(2))),
    },
    uptime: formatDuration((Date.now() - BOOT_TIME) / 1000),
    uptimeSeconds: (Date.now() - BOOT_TIME) / 1000,
    config: publicConfig(globalConfig),
  };
}

function publicConfig(c: Config) {
  const { ...rest } = c as Record<string, unknown>;
  return rest;
}

async function attachDisk(payload: Record<string, any>) {
  const d = await checkDiskSpace(globalConfig.outputRoot, globalConfig.minFreeSpaceGB);
  payload.diskSpace = {
    free: `${d.freeGB.toFixed(1)} GB / ${d.totalGB.toFixed(1)} GB`,
    freeGB: Number(d.freeGB.toFixed(1)),
    totalGB: Number(d.totalGB.toFixed(1)),
    percent: Number(d.percent.toFixed(1)),
    ok: d.ok,
    minFreeSpaceGB: globalConfig.minFreeSpaceGB,
    outputRoot: resolve(globalConfig.outputRoot),
    secondaryStoragePath: globalConfig.secondaryStoragePath || null,
    error: d.error ?? null,
  };
  return payload;
}

const SQL_FILTERS: Record<string, string> = {
  all: "1=1",
  not_started: "download_status = 'not_started'",
  paused: "download_status = 'paused'",
  downloading: "download_status = 'downloading'",
  downloaded: "download_status = 'downloaded'",
  metadata: "download_status='downloaded' AND metadata_status IN ('pending','downloading')",
  converting: "conversion_status = 'in_progress'",
  done: "conversion_status='done' OR (download_status='downloaded' AND conversion_status='not_needed')",
  failed: "download_status='failed' OR conversion_status='failed' OR metadata_status='failed'",
  skipped: "download_status = 'skipped'",
};

function startWebServer(config: Config) {
  const port = CLI.port ?? config.webPort;
  const server = Bun.serve({
    port,
    hostname: config.webHost || "0.0.0.0",
    idleTimeout: 30,
    async fetch(req) {
      const url = new URL(req.url);
      const p = url.pathname;
      const method = req.method.toUpperCase();
      const t0 = Date.now();
      try {
        /* ---------- static ---------- */
        if (p === "/" || p === "/index.html") {
          if (existsSync("./web_ui.html")) {
            return new Response(Bun.file("./web_ui.html"), {
              headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" },
            });
          }
          return new Response(
            `<!doctype html><meta charset="utf-8"><title>Archive Engine V${ENGINE_VERSION}</title>
             <body style="background:#070a10;color:#e8eefc;font-family:system-ui;padding:40px">
             <h1>🎬 YouTube Archive Engine V${ENGINE_VERSION}</h1>
             <p>web_ui.html not found next to the script. The REST API is live at <code>/api/status</code>.</p>
             </body>`,
            { headers: { "Content-Type": "text/html; charset=utf-8" } },
          );
        }
        if (p === "/favicon.ico") return new Response(null, { status: 204 });

        /* ---------- api ---------- */
        if (p === "/api/ping") return json({ ok: true, pong: Date.now(), version: ENGINE_VERSION, paused: globalIsPaused });

        if (p === "/api/status" && method === "GET") {
          const payload = await attachDisk(buildStatusPayload());
          return json(payload);
        }

        if (p === "/api/health" && method === "GET") {
          const force = url.searchParams.get("refresh") === "1";
          if (force || LAST_PREFLIGHT.checks.length === 0) LAST_PREFLIGHT = { checks: (await preflight(globalConfig)).checks, at: nowIso() };
          return json({ ok: true, at: LAST_PREFLIGHT.at, checks: LAST_PREFLIGHT.checks,
            allOk: LAST_PREFLIGHT.checks.every(c => c.ok),
            criticalOk: LAST_PREFLIGHT.checks.filter(c => c.critical).every(c => c.ok) });
        }

        if (p === "/api/config" && method === "GET") return json({ ok: true, config: publicConfig(globalConfig) });

        if (p === "/api/config" && method === "POST") {
          const body = await readBody(req);
          const merged = { ...globalConfig, ...body };
          const res = ConfigSchema.safeParse(merged);
          if (!res.success) return fail(`Invalid configuration: ${res.error.issues.map(i => `${i.path.join(".")}: ${i.message}`).join("; ")}`, 400, { issues: res.error.issues });
          const next = res.data as Config;
          await writeFile(CONFIG_PATH, JSON.stringify(next, null, 2), "utf-8");
          const prev = globalConfig;
          globalConfig = next;
          autoscaler.init(next);
          log.ok("config", `Configuration updated at runtime (was quality=${prev.videoQuality}, workers=${prev.maxConcurrentDownloads}).`);
          return json({ ok: true, config: publicConfig(globalConfig), restartRequired: prev.maxDownloadWorkers !== next.maxDownloadWorkers || prev.webPort !== next.webPort });
        }

        if (p === "/api/jobs" && method === "GET") {
          const status = url.searchParams.get("status") || "all";
          const folder = url.searchParams.get("folder") || "";
          const q = (url.searchParams.get("q") || "").trim();
          const limit = clamp(parseInt(url.searchParams.get("limit") || "500", 10) || 500, 1, 5000);
          const offset = Math.max(0, parseInt(url.searchParams.get("offset") || "0", 10) || 0);
          const sortRaw = url.searchParams.get("sort") || "created_at";
          const dir = (url.searchParams.get("dir") || "desc").toLowerCase() === "asc" ? "ASC" : "DESC";
          const sortCol = ["title", "progress", "speed", "eta", "download_status", "created_at", "index_number", "file_size"]
            .includes(sortRaw) ? sortRaw : "created_at";
          const where = SQL_FILTERS[status] || "1=1";
          const params: unknown[] = [];
          let extra = "";
          if (folder) { extra += " AND folder = ?"; params.push(folder); }
          if (q) { extra += " AND (title LIKE ? OR id LIKE ? OR folder LIKE ?)"; const like = `%${q}%`; params.push(like, like, like); }
          const rows = db.query(
            `SELECT id,url,title,folder,channel,playlist_title,duration_seconds,index_number,output_directory,
                    video_quality,target_format,want_subtitles,want_thumbnail,want_description,want_infojson,want_metadata,
                    verify_integrity,download_status,metadata_status,conversion_status,download_claimed_by,
                    conversion_claimed_by,metadata_claimed_by,partial_file_path,file_path,file_size,downloaded_bytes,
                    integrity,progress,speed,eta,retry_count,error_code,last_error,source_url,
                    created_at,updated_at,started_at,completed_at
             FROM jobs WHERE ${where}${extra}
             ORDER BY ${sortCol} ${dir}, created_at DESC LIMIT ? OFFSET ?`,
          ).all(...params, limit, offset) as unknown as Record<string, unknown>[];
          const total = db.query(`SELECT COUNT(*) AS c FROM jobs WHERE ${where}${extra}`).get(...params) as { c: number };
          return json({ ok: true, jobs: rows, total: Number(total?.c ?? 0), limit, offset });
        }

        if (p === "/api/folders" && method === "GET") return json({ ok: true, folders: folderStats() });

        if (p.startsWith("/api/jobs/") && method === "GET") {
          const id = decodeURIComponent(p.replace("/api/jobs/", ""));
          const row = db.query(`SELECT * FROM jobs WHERE id = ?`).get(id);
          if (!row) return fail("Job not found", 404);
          const sidecars = row && (row as JobRow).output_directory ? await listSidecars(row as JobRow) : [];
          return json({ ok: true, job: row, sidecars });
        }

        if (p === "/api/scan" && method === "POST") {
          const body = await readBody(req);
          const scanUrl = String(body.url || "").trim();
          const folder = body.folder ? String(body.folder).trim() : undefined;
          const kind = body.kind === "channel" ? "channel" : body.kind === "channelPlaylist" ? "channelPlaylist" : "playlist";
          if (!scanUrl) return fail("url is required", 400);
          try { new URL(scanUrl); } catch { return fail("url is not a valid absolute URL", 400); }
          const before = dbStats();
          const r = await scanAndIngest(scanUrl, globalConfig, folder, kind as any);
          if (r.error) return fail(`Scan failed: ${r.error}`, 502, { result: r });
          const after = dbStats();
          return json({ ok: true, ...r, totalJobsBefore: before.total, totalJobsAfter: after.total,
            message: `Ingested ${r.added} new job(s) from ${scanUrl}` });
        }

        if (p === "/api/pause" && method === "POST") {
          const body = await readBody(req).catch(() => ({}));
          triggerPause(String(body.reason || "MANUAL_WEB_UI"));
          return json({ ok: true, success: true, isPaused: globalIsPaused, reason: pauseReason });
        }
        if (p === "/api/resume" && method === "POST") {
          const body = await readBody(req).catch(() => ({}));
          triggerResume({ clearPaused: !!body.clearPaused });
          return json({ ok: true, success: true, isPaused: globalIsPaused });
        }

        if (p === "/api/resume-paused" && method === "POST") {
          const r = db.prepare(`UPDATE jobs SET download_status='not_started', download_claimed_by=NULL, download_claimed_ms=NULL,
                                last_error=NULL, error_code=NULL, updated_at=datetime('now') WHERE download_status='paused'`).run();
          triggerResume();
          return json({ ok: true, requeued: (r as any).changes ?? 0 });
        }

        if (p === "/api/retry-failed" && method === "POST") {
          const r = db.prepare(`UPDATE jobs SET download_status='not_started', conversion_status='pending', metadata_status='pending',
                                retry_count=0, last_error=NULL, error_code=NULL, progress=0, speed=0, eta=0,
                                download_claimed_by=NULL, conversion_claimed_by=NULL, metadata_claimed_by=NULL,
                                updated_at=datetime('now')
                                WHERE download_status='failed' OR conversion_status='failed' OR metadata_status='failed'`).run();
          if (pauseReason?.startsWith("MAX_FAILURES")) triggerResume();
          return json({ ok: true, requeued: (r as any).changes ?? 0 });
        }

        if (p.startsWith("/api/retry/") && method === "POST") {
          const id = decodeURIComponent(p.replace("/api/retry/", ""));
          const r = db.prepare(`UPDATE jobs SET download_status='not_started', conversion_status='pending', metadata_status='pending',
                                retry_count=0, last_error=NULL, error_code=NULL, progress=0, speed=0, eta=0,
                                download_claimed_by=NULL, conversion_claimed_by=NULL, metadata_claimed_by=NULL,
                                updated_at=datetime('now') WHERE id=?`).run(id);
          if (((r as any).changes ?? 0) === 0) return fail("Job not found", 404);
          return json({ ok: true, id });
        }

        if (p === "/api/jobs/bulk" && method === "POST") {
          const body = await readBody(req);
          const ids: string[] = Array.isArray(body.ids) ? body.ids.map(String).slice(0, 5000) : [];
          const action = String(body.action || "");
          if (!ids.length) return fail("ids[] is required", 400);
          const ph = ids.map(() => "?").join(",");
          let changes = 0;
          if (action === "retry") {
            changes = (db.prepare(`UPDATE jobs SET download_status='not_started', conversion_status='pending', metadata_status='pending',
              retry_count=0, last_error=NULL, progress=0, updated_at=datetime('now') WHERE id IN (${ph})`).run(...ids) as any).changes ?? 0;
          } else if (action === "pause") {
            changes = (db.prepare(`UPDATE jobs SET download_status='paused', download_claimed_by=NULL, updated_at=datetime('now')
              WHERE id IN (${ph}) AND download_status IN ('not_started','paused')`).run(...ids) as any).changes ?? 0;
          } else if (action === "delete") {
            changes = (db.prepare(`DELETE FROM jobs WHERE id IN (${ph}) AND download_status NOT IN ('downloading')`).run(...ids) as any).changes ?? 0;
          } else if (action === "reconvert") {
            changes = (db.prepare(`UPDATE jobs SET conversion_status='pending', conversion_claimed_by=NULL, updated_at=datetime('now') WHERE id IN (${ph})`).run(...ids) as any).changes ?? 0;
          } else if (action === "remeta") {
            changes = (db.prepare(`UPDATE jobs SET metadata_status='pending', metadata_claimed_by=NULL, updated_at=datetime('now') WHERE id IN (${ph})`).run(...ids) as any).changes ?? 0;
          } else return fail(`Unknown action "${action}"`, 400);
          return json({ ok: true, action, affected: changes, requested: ids.length });
        }

        if (p.startsWith("/api/jobs/") && method === "DELETE") {
          const id = decodeURIComponent(p.replace("/api/jobs/", ""));
          const body = url.searchParams.get("files") === "1";
          const row = db.query(`SELECT file_path, partial_file_path, output_directory FROM jobs WHERE id=?`).get(id) as
            { file_path: string | null; partial_file_path: string | null; output_directory: string } | null;
          if (!row) return fail("Job not found", 404);
          if (body) {
            for (const f of [row.file_path, row.partial_file_path]) {
              if (f && existsSync(f)) await rm(f, { force: true }).catch(() => {});
            }
            const sidecars = await listSidecars({ ...row, index_number: 0, title: "" } as unknown as JobRow);
            for (const f of sidecars) await rm(f, { force: true }).catch(() => {});
          }
          db.run(`DELETE FROM jobs WHERE id = ?`, [id]);
          return json({ ok: true, id, filesDeleted: body });
        }

        if (p === "/api/queue/purge" && method === "POST") {
          const body = await readBody(req).catch(() => ({}));
          const includeFailed = body.failed !== false;
          const sql = includeFailed
            ? `DELETE FROM jobs WHERE download_status IN ('not_started','paused','failed','skipped')`
            : `DELETE FROM jobs WHERE download_status IN ('not_started','paused')`;
          const r = db.prepare(sql).run();
          log.warn("api", `Queue purged — ${(r as any).changes ?? 0} row(s) removed.`);
          return json({ ok: true, deleted: (r as any).changes ?? 0 });
        }

        if (p === "/api/failed" && method === "GET") {
          const rows = db.query(
            `SELECT id,title,folder,url,retry_count,error_code,last_error,download_status,metadata_status,conversion_status,
                    partial_file_path,file_path,updated_at
             FROM jobs WHERE download_status='failed' OR conversion_status='failed' OR metadata_status='failed'
             ORDER BY updated_at DESC LIMIT 500`,
          ).all();
          return json({ ok: true, failed: rows, count: (rows as unknown[]).length });
        }

        if (p === "/api/history" && method === "GET") {
          const limit = clamp(parseInt(url.searchParams.get("limit") || "50", 10) || 50, 1, 500);
          const rows = db.query(`SELECT * FROM run_history ORDER BY id DESC LIMIT ?`).all(limit);
          return json({ ok: true, history: rows });
        }

        if (p === "/api/sources" && method === "GET") {
          const rows = db.query(`SELECT * FROM sources ORDER BY created_at DESC LIMIT 500`).all();
          return json({ ok: true, sources: rows });
        }

        if (p === "/api/db/stats" && method === "GET") {
          const s = dbStats();
          const byFolder = folderStats();
          const byStage = db.query(`SELECT download_status AS stage, COUNT(*) AS n FROM jobs GROUP BY download_status ORDER BY n DESC`).all();
          const size = existsSync(DB_PATH) ? statSync(DB_PATH).size : 0;
          const wal = existsSync(DB_PATH + "-wal") ? statSync(DB_PATH + "-wal").size : 0;
          return json({
            ok: true, path: resolve(DB_PATH), sizeBytes: size, walBytes: wal,
            schemaVersion: SCHEMA_VERSION, journalMode: "wal", stats: s, byFolder, byStage,
          });
        }

        if (p === "/api/logs" && method === "GET") {
          const type = url.searchParams.get("type") || "error";
          const limit = clamp(parseInt(url.searchParams.get("limit") || "300", 10) || 300, 1, 5000);
          let logsOut: string[] = [];
          try {
            if (type === "error" && existsSync(globalConfig.errorLog)) {
              logsOut = readFileSync(globalConfig.errorLog, "utf-8").split("\n").filter(l => l.trim()).slice(-limit);
            } else if (type === "report" && existsSync(globalConfig.reportLog)) {
              logsOut = readFileSync(globalConfig.reportLog, "utf-8").split("\n").filter(l => l.trim()).slice(-limit);
            } else {
              const rows = db.query(`SELECT ts, level, scope, message FROM events ORDER BY seq DESC LIMIT ?`).all(limit) as unknown as
                { ts: string; level: string; scope: string; message: string }[];
              logsOut = rows.reverse().map(r => `${r.ts} [${(r.level || "info").toUpperCase()}] [${r.scope || "-"}] ${r.message}`);
            }
          } catch (e) { logsOut = [`Error reading logs: ${(e as Error).message}`]; }
          return json({ ok: true, logs: logsOut, type, count: logsOut.length });
        }

        if (p === "/api/events" && method === "GET") {
          const limit = clamp(parseInt(url.searchParams.get("limit") || "200", 10) || 200, 1, 2000);
          const rows = db.query(`SELECT seq,ts,level,scope,message FROM events ORDER BY seq DESC LIMIT ?`).all(limit);
          return json({ ok: true, events: rows });
        }

        if (p === "/api/metadata/run" && method === "POST") {
          const r = db.prepare(`UPDATE jobs SET metadata_status='pending', metadata_claimed_by=NULL
                                WHERE download_status='downloaded' AND metadata_status IN ('failed','not_needed')
                                  AND (want_subtitles=1 OR want_thumbnail=1 OR want_description=1 OR want_infojson=1 OR want_metadata=1)`).run();
          return json({ ok: true, requeued: (r as any).changes ?? 0 });
        }
        if (p === "/api/convert/run" && method === "POST") {
          const r = db.prepare(`UPDATE jobs SET conversion_status='pending', conversion_claimed_by=NULL
                                WHERE download_status='downloaded' AND conversion_status IN ('failed','not_needed')`).run();
          return json({ ok: true, requeued: (r as any).changes ?? 0 });
        }

        if (p === "/api/reset-failed" && method === "POST") {
          const r = db.prepare(`UPDATE jobs SET download_status='not_started', conversion_status='pending', metadata_status='pending',
                                retry_count=0, last_error=NULL, error_code=NULL, progress=0, updated_at=datetime('now')
                                WHERE download_status='failed' OR conversion_status='failed' OR metadata_status='failed'`).run();
          return json({ ok: true, reset: (r as any).changes ?? 0 });
        }

        if (p === "/api/shutdown" && method === "POST") {
          log.warn("api", "Shutdown requested from Web UI.");
          setTimeout(() => gracefulShutdown("WEB_SHUTDOWN"), 300);
          return json({ ok: true, message: "Shutdown initiated" });
        }

        return fail(`No route for ${method} ${p}`, 404);
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        log.error("api", `${method} ${p} failed in ${Date.now() - t0}ms: ${msg}`, e);
        return fail(msg, msg.includes("not found") ? 404 : 500);
      }
    },
    error(err) {
      log.error("http", `Unhandled server error: ${err.message}`, err);
      return fail(`Internal server error: ${err.message}`, 500);
    },
  });
  log.ok("web", `Web UI: http://127.0.0.1:${server.port}  (LAN: http://${localIp()}:${server.port})`);
  return server;
}

function localIp(): string {
  const ifaces = os.networkInterfaces();
  for (const list of Object.values(ifaces)) {
    for (const i of list || []) if (i.family === "IPv4" && !i.internal) return i.address;
  }
  return "127.0.0.1";
}

/* ==========================================================================
   15. AUTONOMOUS POLLING
   ========================================================================== */

function startAutonomousPolling(config: Config) {
  if (config.rescanIntervalHours <= 0) return null;
  const ms = Math.max(60_000, config.rescanIntervalHours * 3600_000);
  log.info("daemon", `Autonomous rescan every ${(ms / 3600_000).toFixed(1)}h.`);
  return setInterval(async () => {
    if (abortSignal.aborted || globalIsPaused) return;
    log.info("daemon", "Running scheduled rescan of all sources…");
    try { await ingestAllSources(globalConfig); }
    catch (e) { log.error("daemon", "rescan failed", e); }
  }, ms);
}

/* ==========================================================================
   16. SHUTDOWN + MAIN
   ========================================================================== */

function writeRunHistory(reason: string) {
  try {
    const s = dbStats();
    db.run(
      `INSERT INTO run_history(started_at,ended_at,duration_seconds,downloaded,skipped,failed,converted,total_queued,bytes_downloaded,exit_reason)
       VALUES(?, datetime('now'), ?, ?, ?, ?, ?, ?, ?, ?)`,
      [new Date(BOOT_TIME).toISOString(), (Date.now() - BOOT_TIME) / 1000,
       s.downloaded, s.skipped, s.failed, s.convert_done, s.total, stats.bytes, reason],
    );
  } catch (e) { log.warn("history", `could not persist run history: ${(e as Error).message}`); }
}

async function gracefulShutdown(signal: string, exitCode = 0) {
  if (shuttingDown) return;
  shuttingDown = true;
  log.warn("engine", `🛑 ${signal} received — parking in-flight jobs as 'paused' (partials preserved)…`);
  globalIsPaused = true;
  pauseReason = signal;

  // signal children politely so yt-dlp flushes its .part file
  for (const [, proc] of activeProcs) { try { proc.kill("SIGINT"); } catch {} }
  await sleep(3000);
  for (const [, proc] of activeProcs) { try { proc.kill("SIGKILL"); } catch {} }

  try {
    const parked = db.prepare(`
      UPDATE jobs SET
        download_status = CASE WHEN download_status='downloading' THEN 'paused' ELSE download_status END,
        conversion_status = CASE WHEN conversion_status='in_progress' THEN 'pending' ELSE conversion_status END,
        metadata_status = CASE WHEN metadata_status='downloading' THEN 'pending' ELSE metadata_status END,
        download_claimed_by=NULL, download_claimed_ms=NULL,
        conversion_claimed_by=NULL, conversion_claimed_ms=NULL,
        metadata_claimed_by=NULL, metadata_claimed_ms=NULL,
        heartbeat_ms=NULL, speed=0, updated_at=datetime('now')
    `).run();
    log.info("engine", `Parked ${(parked as any).changes ?? 0} row(s). Resume with --resume-paused or the Web UI.`);
  } catch (e) { log.error("engine", "shutdown db update failed", e); }

  writeRunHistory(signal);
  abortController.abort();
  try { webServer?.stop(true); } catch {}
  resetTerminal();
  await sleep(200);
  log.ok("engine", "Shutdown complete. Database is consistent — restart to continue where you left off.");
  process.exit(exitCode);
}

async function queueIsDrained(): Promise<boolean> {
  const s = dbStats();
  const busy = aliveDownloadWorkers.size + aliveConvertWorkers.size + aliveMetadataWorkers.size;
  return s.not_started + s.paused + s.downloading + s.metadata_pending + s.metadata_active +
         s.convert_pending + s.convert_active === 0 && busy === 0;
}

async function main() {
  if (CLI.help) { printHelp(); process.exit(0); }

  process.on("SIGINT",  () => void gracefulShutdown("SIGINT"));
  process.on("SIGTERM", () => void gracefulShutdown("SIGTERM"));
  process.on("SIGHUP",  () => void gracefulShutdown("SIGHUP"));
  process.on("uncaughtException", (e) => { log.fatal("engine", "uncaughtException", e); });
  process.on("unhandledRejection", (r) => { log.fatal("engine", "unhandledRejection", r); });

  console.log(`\n\x1b[1m🎬 YouTube Archive Engine V${ENGINE_VERSION}\x1b[0m  \x1b[90m(central-database edition)\x1b[0m\n`);

  // ---- config -------------------------------------------------------------
  try {
    globalConfig = await loadConfig();
  } catch (e) {
    bootError = (e as Error).message;
    log.fatal("boot", `Configuration error — aborting.\n${bootError}`);
    process.exit(1);
  }
  log.configure({
    errorLog: globalConfig.errorLog, reportLog: globalConfig.reportLog,
    verbose: CLI.verbose || globalConfig.logLevel === "debug",
  });
  isTTY = !!process.stdout.isTTY && globalConfig.enableTui;

  // ---- dependencies -------------------------------------------------------
  if (!CLI.skipDeps) {
    const pre = await preflight(globalConfig);
    LAST_PREFLIGHT = { checks: pre.checks, at: nowIso() };
    if (!pre.ok) { bootError = "Dependency preflight failed"; process.exit(1); }
  } else log.warn("boot", "Dependency preflight skipped (--skip-dep-check).");

  // ---- database -----------------------------------------------------------
  try {
    initDatabase(resolve(CLI.dbPath || globalConfig.dbPath));
    claimers = makeClaimers();
    bindClaimTracking();
  } catch (e) {
    bootError = (e as Error).message;
    log.fatal("boot", bootError);
    process.exit(1);
  }
  const reconciled = reconcileCrashedJobs();

  if (CLI.resetFailed) {
    const r = db.prepare(`UPDATE jobs SET download_status='not_started', conversion_status='pending', metadata_status='pending',
                          retry_count=0, last_error=NULL, error_code=NULL, progress=0, updated_at=datetime('now')
                          WHERE download_status='failed' OR conversion_status='failed' OR metadata_status='failed'`).run();
    log.ok("boot", `--reset-failed: ${(r as any).changes ?? 0} job(s) requeued.`);
  }
  if (CLI.resumePaused || reconciled > 0) {
    if (CLI.resumePaused) {
      const r = db.prepare(`UPDATE jobs SET download_status='not_started', download_claimed_by=NULL, updated_at=datetime('now') WHERE download_status='paused'`).run();
      log.ok("boot", `--resume-paused: ${(r as any).changes ?? 0} job(s) requeued (continuing from .part files).`);
    }
  }

  // ---- cookies ------------------------------------------------------------
  if (globalConfig.validateCookiesOnStart && existsSync(globalConfig.cookiesFile)) {
    const valid = await validateCookies(globalConfig.cookiesFile);
    if (!valid) log.warn("boot", "⚠️  cookies.txt appears invalid/expired — age-restricted and member-only videos will fail.");
    else log.ok("boot", "Cookies validated.");
  }

  // ---- ingest all configured sources --------------------------------------
  try {
    await ingestAllSources(globalConfig);
  } catch (e) {
    log.error("boot", "Ingestion pass failed", e);
  }

  const startStats = dbStats();
  log.info("boot", `Database: ${startStats.total} job(s) · ${startStats.not_started} not_started · ${startStats.paused} paused · ${startStats.downloaded} downloaded · ${startStats.failed} failed`);

  if (CLI.scanOnly) {
    writeRunHistory("SCAN_ONLY");
    log.ok("boot", "--scan-only: ingestion finished, exiting without workers.");
    process.exit(0);
  }

  // ---- housekeeping -------------------------------------------------------
  await cleanOrphanedFiles(globalConfig.outputRoot);
  mkdir(globalConfig.outputRoot, { recursive: true }).catch(() => {});

  autoscaler.init(globalConfig);
  initDashboard(globalConfig);

  if (!globalConfig.enableWebUi || CLI.noWeb) log.info("web", "Web UI disabled.");
  else {
    try { webServer = startWebServer(globalConfig); }
    catch (e) {
      const msg = (e as Error).message;
      log.error("web", `Could not bind port ${globalConfig.webPort}: ${msg}`);
      if (msg.toLowerCase().includes("address in use")) {
        const alt = globalConfig.webPort + 1;
        log.warn("web", `Retrying on port ${alt}…`);
        try { webServer = startWebServer({ ...globalConfig, webPort: alt }); } catch (e2) { log.error("web", `Retry failed: ${(e2 as Error).message}`); }
      }
    }
  }

  // ---- monitors -----------------------------------------------------------
  networkMonitor().catch(e => log.error("net", "monitor crashed", e));
  diskMonitor().catch(e => log.error("disk", "monitor crashed", e));
  reaperLoop();
  const dashTimer = setInterval(() => { try { renderDashboard(); } catch {} }, 2000);
  const tuneTimer = setInterval(() => {
    if (abortSignal.aborted) return clearInterval(tuneTimer);
    try {
      const s = dbStats();
      autoscaler.tune(s.not_started + s.paused);
    } catch {}
  }, 10_000);
  const pollTimer = startAutonomousPolling(globalConfig);

  // ---- worker pools -------------------------------------------------------
  log.ok("engine", `Starting pools: ${globalConfig.maxDownloadWorkers} download · ${globalConfig.metadataWorkers} metadata · ${globalConfig.maxConcurrentConverts} converter`);
  for (let i = 1; i <= globalConfig.maxDownloadWorkers; i++)
    downloadWorker(i, globalConfig).catch(e => log.fatal(`dl-${i}`, "worker crashed", e));
  for (let i = 1; i <= globalConfig.metadataWorkers; i++)
    metadataWorker(i, globalConfig).catch(e => log.fatal(`md-${i}`, "worker crashed", e));
  for (let i = 1; i <= globalConfig.maxConcurrentConverts; i++)
    converterWorker(i, globalConfig).catch(e => log.fatal(`cv-${i}`, "worker crashed", e));

  log.ok("engine", `🚀 Engine V${ENGINE_VERSION} running — resilient, autonomous, proxy-free.`);

  // ---- drain / daemon -----------------------------------------------------
  let idleSince = 0;
  const loop = setInterval(async () => {
    if (abortSignal.aborted) return clearInterval(loop);
    const drained = await queueIsDrained().catch(() => false);
    if (drained) {
      if (idleSince === 0) idleSince = Date.now();
      const idleFor = (Date.now() - idleSince) / 1000;
      if (CLI.once) { clearInterval(loop); await gracefulShutdown("QUEUE_DRAINED"); return; }
      if (!globalConfig.daemonMode && idleFor > 30) {
        clearInterval(loop);
        await gracefulShutdown("QUEUE_DRAINED");
        return;
      }
      if (!globalConfig.daemonMode && idleFor > 10 && Math.floor(idleFor) % 10 === 0)
        log.info("engine", `Queue drained — idling ${Math.round(idleFor)}s before graceful exit (use daemonMode to stay resident).`);
    } else idleSince = 0;
  }, 5000);

  process.on("beforeExit", () => { clearInterval(dashTimer); clearInterval(tuneTimer); if (pollTimer) clearInterval(pollTimer); });
}

main().catch(async (e) => {
  log.fatal("boot", "Fatal startup error", e);
  try { writeRunHistory("BOOT_FAILURE"); } catch {}
  resetTerminal();
  process.exit(1);
});
