async function runCmd(cmd: string, args: string[], timeoutMs = 20_000) {
  try {
    const proc = Bun.spawn([cmd, ...args], { stdout: "pipe", stderr: "pipe", stdin: "ignore" });
    const timer = setTimeout(() => { try { proc.kill("SIGKILL"); } catch {} }, timeoutMs);
    const [out, err, code] = await Promise.all([
      new Response(proc.stdout).text().catch(() => ""),
      new Response(proc.stderr).text().catch(() => ""),
      proc.exited.catch(() => 1),
    ]);
    clearTimeout(timer);
    return { code, out, err };
  } catch (e) { return { code: 127, out: "", err: (e as Error).message }; }
}

async function doctor(config: Config) {
  console.clear();
  console.log("🩺 Doctor — dependency & configuration diagnostics\n");
  const rows: { name: string; ok: boolean; critical: boolean; info: string }[] = [];

  const ytdlp = await runCmd("yt-dlp", ["--version"]);
  rows.push({ name: "yt-dlp", ok: ytdlp.code === 0, critical: true, info: ytdlp.code === 0 ? ytdlp.out.trim().split("\n")[0] : (ytdlp.err || "not found").slice(0, 90) });

  const ff = await runCmd("ffmpeg", ["-version"]);
  rows.push({ name: "ffmpeg", ok: ff.code === 0, critical: true, info: ff.code === 0 ? (ff.out.split("\n")[0].match(/version (\S+)/)?.[1] ?? "present") : "not found" });

  const deno = await runCmd(existsSync(config.denoPath) ? config.denoPath : "deno", ["--version"], 12_000);
  rows.push({ name: "deno", ok: deno.code === 0, critical: false, info: deno.code === 0 ? deno.out.split("\n")[0] : `not found at "${config.denoPath}"` });

  const dbOk = (() => { try { const s = existsSync(config.dbPath) ? statSync(config.dbPath) : null; return { ok: true, info: s ? `${config.dbPath} (${(s.size / 1024 / 1024).toFixed(2)} MB)` : `${config.dbPath} (will be created)` }; } catch (e) { return { ok: false, info: (e as Error).message }; } })();
  rows.push({ name: "database", ok: dbOk.ok, critical: true, info: dbOk.info });

  const cfgOk = existsSync(CONFIG_PATH);
  const srcCount = config.playlists.length + config.channels.length + config.channelPlaylists.length;
  rows.push({ name: "config.json", ok: cfgOk && (srcCount > 0 || config.daemonMode), critical: false, info: cfgOk ? `${srcCount} source(s)` : "missing" });

  let cookieInfo = "absent (anonymous)";
  try { const s = statSync(config.cookiesFile); cookieInfo = s.size > 0 ? `${(s.size / 1024).toFixed(1)} KB` : "empty"; } catch {}
  rows.push({ name: "cookies.txt", ok: cookieInfo !== "empty", critical: false, info: cookieInfo });

  const net = await (async () => {
    try { const ac = new AbortController(); const t = setTimeout(() => ac.abort(), 6000);
      await fetch("https://www.youtube.com/favicon.ico", { signal: ac.signal, method: "HEAD" }); clearTimeout(t); return true; }
    catch { return false; }
  })();
  rows.push({ name: "youtube reachable", ok: net, critical: true, info: net ? "online" : "no connectivity" });

  const disk = await (async () => {
    try { const { statfs } = await import("node:fs/promises");
      const s = await statfs(resolve(config.outputRoot));
      const freeGB = (s.bavail * s.bsize) / 1024 ** 3, totalGB = (s.blocks * s.bsize) / 1024 ** 3;
      return { ok: freeGB > config.minFreeSpaceGB, info: `${freeGB.toFixed(1)} / ${totalGB.toFixed(1)} GB free (min ${config.minFreeSpaceGB})` };
    } catch (e) { return { ok: false, info: (e as Error).message }; }
  })();
  rows.push({ name: "output storage", ok: disk.ok, critical: true, info: disk.info });

  const w = Math.max(...rows.map(r => r.name.length));
  for (const r of rows) {
    const mark = r.ok ? "\x1b[32m✔\x1b[0m" : r.critical ? "\x1b[31m✘\x1b[0m" : "\x1b[33m!\x1b[0m";
    console.log(`   ${mark} ${r.name.padEnd(w)}  ${r.info}`);
  }
  const bad = rows.filter(r => !r.ok);
  const criticalBad = bad.filter(r => r.critical);
  console.log("");
  if (criticalBad.length) console.log(`\x1b[31m❌ ${criticalBad.length} critical problem(s) — the engine will refuse to boot.\x1b[0m`);
  else if (bad.length) console.log(`\x1b[33m⚠️  ${bad.length} non-critical warning(s).\x1b[0m`);
  else console.log("\x1b[32m✅ All checks passed — ready to run.\x1b[0m");

  const problems = crossValidate(config);
  if (problems.length) { console.log("\n\x1b[33mConfiguration notes:\x1b[0m"); problems.forEach(p => console.log(`   • ${p}`)); }
  console.log("");
  return criticalBad.length === 0;
}

/* ==========================================================================
   7. NON-INTERACTIVE FLAGS
   ========================================================================== */

function coerceValue(raw: string): unknown {
  const t = raw.trim();
  if (["true", "false"].includes(t.toLowerCase())) return t.toLowerCase() === "true";
  if (t === "null") return null;
  if (/^-?\d+$/.test(t)) return parseInt(t, 10);
  if (/^-?\d*\.\d+$/.test(t)) return parseFloat(t);
  if ((t.startsWith("[") && t.endsWith("]")) || (t.startsWith("{") && t.endsWith("}"))) {
    try { return JSON.parse(t); } catch { return raw; }
  }
  return raw;
}

async function applySetFlags(config: Config, pairs: string[]): Promise<{ config: Config; errors: string[] }> {
  const errors: string[] = [];
  const draft: Record<string, unknown> = { ...config };
  for (const pair of pairs) {
    const eq = pair.indexOf("=");
    if (eq <= 0) { errors.push(`Invalid --set "${pair}" (expected key=value)`); continue; }
    const key = pair.slice(0, eq).trim();
    const rawVal = pair.slice(eq + 1);
    if (!(key in ConfigSchema.shape)) { errors.push(`Unknown config key "${key}"`); continue; }
    draft[key] = coerceValue(rawVal);
  }
  const res = ConfigSchema.safeParse(draft);
  if (!res.success) {
    for (const i of res.error.issues) errors.push(`${i.path.join(".") || "(root)"}: ${i.message}`);
    return { config, errors };
  }
  return { config: res.data as Config, errors };
}

