  .opt:hover{border-color:#3a4f68}
  .banner{margin-top:14px;border:1px solid #6d5522;background:linear-gradient(90deg,rgba(255,176,32,.12),rgba(255,176,32,.03));
    color:#ffd07a;border-radius:12px;padding:10px 14px;font-size:12.5px;display:none;align-items:center;gap:10px}
  .banner.on{display:flex}

  /* toasts */
  .toasts{position:fixed;right:18px;bottom:18px;z-index:120;display:flex;flex-direction:column;gap:9px;max-width:360px}
  .toast{border:1px solid var(--line2);border-radius:11px;background:#111a25;padding:11px 14px;box-shadow:0 14px 40px rgba(0,0,0,.55);
    font-size:12.5px;display:flex;gap:10px;align-items:flex-start;animation:tin .26s cubic-bezier(.2,.9,.3,1.15)}
  .toast.out{animation:tout .25s forwards}
  @keyframes tin{from{opacity:0;transform:translateX(28px)}to{opacity:1;transform:none}}
  @keyframes tout{to{opacity:0;transform:translateX(28px)}}
  .toast b{display:block;font-size:12.5px;margin-bottom:2px}
  .toast span{color:var(--mut);font-size:11.5px;word-break:break-word}
  .toast .bar-l{width:3px;border-radius:3px;align-self:stretch;background:var(--cy)}
  .toast.ok .bar-l{background:var(--gr)}.toast.err .bar-l{background:var(--red)}.toast.warn .bar-l{background:var(--am)}

  .spin{animation:rot 1s linear infinite}
  @keyframes rot{to{transform:rotate(360deg)}}
  .foot{margin-top:22px;text-align:center;color:var(--dim);font-size:11.5px}
  .foot code{font-family:'JetBrains Mono',monospace;color:var(--mut)}

  @media(max-width:1180px){.g4{grid-template-columns:repeat(2,1fr)}.g3{grid-template-columns:1fr}}
  @media(max-width:760px){
    .wrap{padding:12px 12px 44px}.g4{grid-template-columns:1fr 1fr}.topbar{position:static}
    .brand p{display:none}.th-speed{font-size:26px}.card .v{font-size:22px}
  }
  @media(max-width:520px){.g4{grid-template-columns:1fr}}
</style>
</head>
<body>
<div class="wrap">

  <!-- ============ TOP BAR ============ -->
