  <div class="selbar" id="selbar" style="display:none">
    <b id="selCount">0</b><span style="color:var(--mut);font-size:12.5px">selected</span>
    <div style="flex:1"></div>
    <button class="btn sm green" id="btnSelRetry" style="border-color:#1f6b52;color:#5ff0bd;background:#0b1f18">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M21 12a9 9 0 11-3-6.7M21 4v5h-5"/></svg>Retry Selected</button>
    <button class="btn sm warn" id="btnSelPause">
      <svg viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="5" width="4" height="14" rx="1"/><rect x="14" y="5" width="4" height="14" rx="1"/></svg>Pause Selected</button>
    <button class="btn sm danger" id="btnSelDelete">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M4 7h16M9 7V5h6v2M6 7l1 13h10l1-13"/></svg>Delete Selected</button>
    <button class="btn sm ghost" id="btnSelClear">Clear</button>
