    <div class="tabs">
      <button class="tab on" data-tab="jobs">📋 Jobs <span class="cnt" id="cntJobs">0</span></button>
      <button class="tab" data-tab="failed">❌ Failed <span class="cnt" id="cntFailed">0</span></button>
