    </div>

    <!-- LOGS -->
    <div id="view-logs" style="display:none">
      <div class="logbar">
        <button class="chip on" id="logTabErr">Error Log</button>
        <button class="chip" id="logTabRep">Report Log</button>
        <div class="sep"></div>
