<div class="overlay" id="ovConfirm">
  <div class="modal" style="max-width:430px">
    <header><h2 id="cfTitle">Are you sure?</h2>
      <div style="flex:1"></div>
      <button class="iconbtn" data-close="ovConfirm"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg></button>
    </header>
    <div class="body"><p id="cfMsg" style="color:var(--mut);font-size:13px"></p></div>
    <footer>
      <button class="btn ghost" data-close="ovConfirm">Cancel</button>
      <button class="btn danger" id="cfOk">Confirm</button>
    </footer>
