/* ---------- sparkline ---------- */
const spark = $('#spark'), sctx = spark.getContext('2d');
function drawSpark() {
  const dpr = window.devicePixelRatio || 1;
  const w = spark.clientWidth, h = spark.clientHeight;
  if (!w || !h) return;
  if (spark.width !== w * dpr) { spark.width = w * dpr; spark.height = h * dpr; }
  sctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  sctx.clearRect(0, 0, w, h);
  sctx.strokeStyle = 'rgba(255,255,255,.045)'; sctx.lineWidth = 1;
  for (let i = 1; i < 4; i++) { const y = (h / 4) * i; sctx.beginPath(); sctx.moveTo(0, y); sctx.lineTo(w, y); sctx.stroke(); }
  const data = state.speedHist;
  if (data.length < 2) return;
  const max = Math.max(...data, 1);
  const pts = data.map((v, i) => [(i / (data.length - 1)) * w, h - (v / max) * (h - 10) - 5]);
  const grad = sctx.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0, 'rgba(255,59,92,.38)'); grad.addColorStop(1, 'rgba(255,59,92,0)');
  sctx.beginPath(); sctx.moveTo(0, h);
  pts.forEach(p => sctx.lineTo(p[0], p[1]));
  sctx.lineTo(w, h); sctx.closePath(); sctx.fillStyle = grad; sctx.fill();
  sctx.beginPath(); pts.forEach((p, i) => i ? sctx.lineTo(p[0], p[1]) : sctx.moveTo(p[0], p[1]));
  sctx.strokeStyle = '#ff3b5c'; sctx.lineWidth = 2; sctx.lineJoin = 'round'; sctx.stroke();
  const last = pts[pts.length - 1];
  sctx.beginPath(); sctx.arc(last[0] - 2, last[1], 3.2, 0, Math.PI * 2); sctx.fillStyle = '#fff'; sctx.fill();
  sctx.beginPath(); sctx.arc(last[0] - 2, last[1], 7, 0, Math.PI * 2); sctx.fillStyle = 'rgba(255,59,92,.22)'; sctx.fill();
}
window.addEventListener('resize', drawSpark);

/* ---------- status render ---------- */
function renderStatus(s) {
