  const id = b.dataset.id, act = b.dataset.fact;
  if (act === 'retry') { try { await api.retryOne(id); toast('Job requeued', id, 'ok'); await refresh(); renderFailed((await api.failed()).failed || []); } catch (err) { toast('Retry failed', String(err.message || err), 'err'); } }
  else if (act === 'delete') {
    const ok = await confirmDialog('Delete failed job?', `<span class="mono">${esc(id)}</span> will be removed from the database.`, 'Delete');
    if (!ok) return;
    try { await api.deleteOne(id); toast('Job deleted', id, 'ok'); renderFailed((await api.failed()).failed || []); await refresh(); } catch (err) { toast('Delete failed', String(err.message || err), 'err'); }
  } else if (act === 'copy') {
    try { await navigator.clipboard.writeText(id); toast('Copied', id, 'ok', 1600); } catch { toast('Copy blocked', 'Clipboard permission denied', 'warn'); }
  }
});

/* tabs */
$$('.tab').forEach(t => t.onclick = async () => {
  $$('.tab').forEach(x => x.classList.remove('on')); t.classList.add('on');
