<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='14' fill='%230b0f17'/%3E%3Cpath d='M22 18l24 14-24 14z' fill='%23ff3b5c'/%3E%3C/svg%3E" />
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@fontsource/inter@5.0.18/index.css" />
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@fontsource/inter@5.0.18/600.css" />
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@fontsource/inter@5.0.18/700.css" />
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@fontsource/inter@5.0.18/800.css" />
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@fontsource/jetbrains-mono@5.0.19/index.css" />
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@fontsource/jetbrains-mono@5.0.19/700.css" />
<style>
:root{
  --bg:#070a10; --bg2:#0b101a; --panel:#101725; --panel2:#141d2e; --panel3:#182236;
  --line:#1f2b40; --line2:#2a3a55;
  --txt:#e8eefc; --muted:#8ea0bf; --dim:#5f708f;
  --red:#ff3b5c; --red2:#ff6b85; --cyan:#22d3ee; --green:#3ddc97; --amber:#fbbf24;
  --violet:#a78bfa; --blue:#60a5fa; --pink:#f472b6;
  --r:14px; --rs:9px;
  --sh:0 10px 30px rgba(0,0,0,.45);
  --mono:'JetBrains Mono',ui-monospace,SFMono-Regular,Menlo,monospace;
}
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{
  background:
    radial-gradient(1200px 600px at 12% -10%, rgba(255,59,92,.13), transparent 60%),
    radial-gradient(900px 500px at 95% 0%, rgba(34,211,238,.10), transparent 55%),
    radial-gradient(800px 600px at 50% 120%, rgba(167,139,250,.09), transparent 60%),
    var(--bg);
  color:var(--txt); font-family:'Inter',system-ui,-apple-system,Segoe UI,Roboto,sans-serif;
  font-size:14px; line-height:1.5; min-height:100vh; -webkit-font-smoothing:antialiased;
}
::selection{background:rgba(255,59,92,.35)}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{background:#22304a;border-radius:8px;border:2px solid transparent;background-clip:padding-box}
::-webkit-scrollbar-thumb:hover{background:#31456a;background-clip:padding-box;border:2px solid transparent}
a{color:var(--cyan);text-decoration:none}
button{font-family:inherit}
.app{max-width:1680px;margin:0 auto;padding:18px 20px 60px}

/* ---------- Header ---------- */
.topbar{display:flex;align-items:center;gap:16px;flex-wrap:wrap;margin-bottom:16px}
.brand{display:flex;align-items:center;gap:12px;min-width:0}
.logo{width:44px;height:44px;border-radius:12px;background:linear-gradient(145deg,#1b2437,#0d1320);border:1px solid var(--line2);
  display:grid;place-items:center;box-shadow:0 0 0 1px rgba(255,59,92,.12),0 8px 24px rgba(255,59,92,.18);flex:0 0 auto}
.logo svg{width:24px;height:24px;filter:drop-shadow(0 0 6px rgba(255,59,92,.6))}
.brand h1{font-size:17px;font-weight:800;margin:0;letter-spacing:-.2px;white-space:nowrap}
.brand h1 span{background:linear-gradient(90deg,var(--red),#ff9d6b);-webkit-background-clip:text;background-clip:text;color:transparent}
.brand p{margin:1px 0 0;font-size:11.5px;color:var(--dim);font-family:var(--mono)}
.topbar-right{margin-left:auto;display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.pill{display:inline-flex;align-items:center;gap:7px;padding:6px 12px;border-radius:999px;font-size:11.5px;font-weight:700;
  border:1px solid var(--line2);background:var(--panel);color:var(--muted);letter-spacing:.3px;text-transform:uppercase;white-space:nowrap}
.dot{width:8px;height:8px;border-radius:50%;background:var(--dim);flex:0 0 auto}
.dot.ok{background:var(--green);box-shadow:0 0 0 0 rgba(61,220,151,.6);animation:pulse 2s infinite}
.dot.warn{background:var(--amber);box-shadow:0 0 8px rgba(251,191,36,.7)}
.dot.err{background:var(--red);box-shadow:0 0 8px rgba(255,59,92,.7)}
.dot.demo{background:var(--violet);box-shadow:0 0 8px rgba(167,139,250,.7)}
@keyframes pulse{0%{box-shadow:0 0 0 0 rgba(61,220,151,.55)}70%{box-shadow:0 0 0 9px rgba(61,220,151,0)}100%{box-shadow:0 0 0 0 rgba(61,220,151,0)}}
.clock{font-family:var(--mono);font-size:11.5px;color:var(--dim);padding:6px 10px;border:1px solid var(--line);border-radius:8px;background:rgba(16,23,37,.6)}
.switch{display:inline-flex;align-items:center;gap:7px;font-size:11px;color:var(--muted);cursor:pointer;user-select:none;
  padding:6px 10px;border:1px solid var(--line);border-radius:999px;background:rgba(16,23,37,.6)}
.switch input{appearance:none;width:30px;height:16px;border-radius:999px;background:#26334b;position:relative;cursor:pointer;transition:.2s;margin:0}
.switch input::after{content:'';position:absolute;top:2px;left:2px;width:12px;height:12px;border-radius:50%;background:#7c8db0;transition:.2s}
.switch input:checked{background:rgba(167,139,250,.35)}
.switch input:checked::after{left:16px;background:var(--violet)}

/* ---------- Alerts ---------- */
.alertbar{display:flex;flex-direction:column;gap:8px;margin-bottom:14px}
.alert{display:flex;align-items:flex-start;gap:10px;padding:10px 14px;border-radius:var(--rs);font-size:12.5px;
  border:1px solid;animation:slideDown .3s ease}
@keyframes slideDown{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:none}}
.alert .ic{font-size:15px;line-height:1.2}
.alert b{font-weight:700}
.alert.err{background:rgba(255,59,92,.09);border-color:rgba(255,59,92,.35);color:#ffc9d3}
.alert.warn{background:rgba(251,191,36,.09);border-color:rgba(251,191,36,.32);color:#ffe6ae}
.alert.info{background:rgba(34,211,238,.08);border-color:rgba(34,211,238,.3);color:#bff1fb}
.alert .x{margin-left:auto;background:none;border:0;color:inherit;opacity:.6;cursor:pointer;font-size:15px;padding:0 2px}
.alert .x:hover{opacity:1}

/* ---------- Cards / grid ---------- */
.grid{display:grid;gap:14px}
.g-stats{grid-template-columns:repeat(auto-fit,minmax(178px,1fr));margin-bottom:14px}
.card{background:linear-gradient(180deg,var(--panel2),var(--panel));border:1px solid var(--line);border-radius:var(--r);
  padding:14px 16px;position:relative;overflow:hidden;box-shadow:var(--sh)}
.card::before{content:'';position:absolute;inset:0 0 auto 0;height:1px;background:linear-gradient(90deg,transparent,rgba(255,255,255,.14),transparent)}
.card .k{font-size:10.5px;text-transform:uppercase;letter-spacing:.9px;color:var(--dim);font-weight:700;display:flex;align-items:center;gap:6px}
.card .v{font-size:26px;font-weight:800;letter-spacing:-1px;margin-top:6px;font-family:var(--mono);line-height:1.1}
.card .s{font-size:11.5px;color:var(--muted);margin-top:3px}
.card .v small{font-size:13px;color:var(--muted);font-weight:600}
.card.accent-red .v{color:var(--red2)} .card.accent-green .v{color:var(--green)}
.card.accent-cyan .v{color:var(--cyan)} .card.accent-amber .v{color:var(--amber)}
.card.accent-violet .v{color:var(--violet)}
.card .spark{position:absolute;right:10px;bottom:8px;opacity:.5;font-size:26px}

.panel{background:linear-gradient(180deg,rgba(20,29,46,.92),rgba(16,23,37,.92));border:1px solid var(--line);
  border-radius:var(--r);box-shadow:var(--sh);margin-bottom:14px}
.panel-h{display:flex;align-items:center;gap:12px;padding:13px 16px;border-bottom:1px solid var(--line);flex-wrap:wrap}
.panel-h h2{margin:0;font-size:13px;font-weight:800;letter-spacing:.4px;text-transform:uppercase;color:var(--muted);display:flex;align-items:center;gap:8px}
.panel-b{padding:16px}

/* ---------- Pipeline ---------- */
.pipeline{display:flex;align-items:stretch;gap:0;overflow-x:auto;padding:4px 2px 8px}
.stage{flex:1 1 0;min-width:142px;background:rgba(11,16,26,.7);border:1px solid var(--line);border-radius:12px;padding:12px 12px 11px;position:relative;transition:.25s}
.stage:hover{border-color:var(--line2);transform:translateY(-2px)}
.stage.active{border-color:rgba(34,211,238,.45);box-shadow:0 0 0 1px rgba(34,211,238,.15),0 8px 24px rgba(34,211,238,.10)}
.stage .st-top{display:flex;align-items:center;gap:7px;font-size:10px;text-transform:uppercase;letter-spacing:.8px;color:var(--dim);font-weight:700}
.stage .st-ic{font-size:14px}
.stage .st-n{font-size:24px;font-weight:800;font-family:var(--mono);margin-top:6px;letter-spacing:-1px}
.stage .st-l{font-size:10.5px;color:var(--muted);margin-top:1px}
.stage .st-bar{height:3px;border-radius:3px;background:#1b2740;margin-top:9px;overflow:hidden}
.stage .st-bar i{display:block;height:100%;border-radius:3px;transition:width .5s ease}
.connector{flex:0 0 26px;position:relative;display:grid;place-items:center;min-width:26px}
.connector::before{content:'';position:absolute;left:0;right:0;top:50%;height:2px;background:#1c2740;transform:translateY(-50%)}
.connector::after{content:'';position:absolute;left:0;top:50%;height:2px;width:34%;transform:translateY(-50%);
  background:linear-gradient(90deg,transparent,var(--cyan),transparent);opacity:0}
.connector.live::after{opacity:1;animation:flowmove 1.6s linear infinite}
@keyframes flowmove{from{left:-34%}to{left:100%}}
.stage[data-tone=red] .st-n{color:var(--red2)} .stage[data-tone=cyan] .st-n{color:var(--cyan)}
.stage[data-tone=violet] .st-n{color:var(--violet)} .stage[data-tone=amber] .st-n{color:var(--amber)}
.stage[data-tone=green] .st-n{color:var(--green)} .stage[data-tone=blue] .st-n{color:var(--blue)}
.stage[data-tone=muted] .st-n{color:var(--muted)}

/* ---------- Throughput / gauges ---------- */
.g-3{grid-template-columns:1.6fr 1fr 1.1fr;margin-bottom:14px}
@media(max-width:1100px){.g-3{grid-template-columns:1fr}}
.speed-big{font-size:34px;font-weight:800;font-family:var(--mono);letter-spacing:-1.5px;
  background:linear-gradient(90deg,#fff,var(--red2));-webkit-background-clip:text;background-clip:text;color:transparent}
#spark{width:100%;height:66px;display:block;margin-top:8px}
.gauge-wrap{display:flex;align-items:center;gap:14px}
.gauge{position:relative;width:96px;height:96px;flex:0 0 auto}
.gauge svg{transform:rotate(-90deg)}
.gauge .gv{position:absolute;inset:0;display:grid;place-items:center;font-family:var(--mono);font-weight:800;font-size:17px}
.gauge .gl{position:absolute;inset:0;display:grid;place-items:center;padding-top:34px;font-size:9.5px;color:var(--dim);text-transform:uppercase;letter-spacing:.8px}
.kv{display:flex;flex-direction:column;gap:8px;min-width:0;flex:1}
.kv-row{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:12px}
.kv-row span:first-child{color:var(--muted)}
.kv-row span:last-child{font-family:var(--mono);font-weight:700;text-align:right;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.meter{height:5px;border-radius:4px;background:#1b2740;overflow:hidden;margin-top:4px}
.meter i{display:block;height:100%;border-radius:4px;transition:width .6s ease}
.meter.green i{background:linear-gradient(90deg,#1f9d6b,var(--green))}
.meter.amber i{background:linear-gradient(90deg,#b7860f,var(--amber))}
.meter.red i{background:linear-gradient(90deg,#b8243d,var(--red))}
.meter.cyan i{background:linear-gradient(90deg,#0e7f96,var(--cyan))}

/* ---------- Workers ---------- */
.workers{display:flex;flex-wrap:wrap;gap:7px}
.wchip{display:flex;align-items:center;gap:6px;padding:5px 9px;border-radius:8px;border:1px solid var(--line);
  background:rgba(11,16,26,.7);font-family:var(--mono);font-size:10.5px;color:var(--dim);max-width:100%}
.wchip b{font-weight:700;color:var(--muted)}
.wchip.busy{border-color:rgba(34,211,238,.4);background:rgba(34,211,238,.08);color:#bff1fb}
.wchip.busy b{color:var(--cyan)}
.wchip.conv{border-color:rgba(251,191,36,.32);background:rgba(251,191,36,.07);color:#ffe6ae}
.wchip.conv b{color:var(--amber)}
.wchip .t{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:190px}

/* ---------- Buttons ---------- */
.btn{display:inline-flex;align-items:center;gap:7px;padding:8px 13px;border-radius:9px;border:1px solid var(--line2);
  background:linear-gradient(180deg,var(--panel3),var(--panel2));color:var(--txt);font-size:12.5px;font-weight:600;
  cursor:pointer;transition:.16s;white-space:nowrap}
.btn:hover:not(:disabled){border-color:#3b5278;transform:translateY(-1px);box-shadow:0 6px 16px rgba(0,0,0,.35)}
.btn:active:not(:disabled){transform:translateY(0)}
.btn:disabled{opacity:.4;cursor:not-allowed}
.btn:focus-visible{outline:2px solid var(--cyan);outline-offset:2px}
.btn.primary{background:linear-gradient(180deg,#ff4a68,#d92246);border-color:#ff6b85;color:#fff;box-shadow:0 6px 18px rgba(255,59,92,.28)}
.btn.primary:hover:not(:disabled){box-shadow:0 8px 24px rgba(255,59,92,.4)}
.btn.ghost{background:transparent}
.btn.danger{background:linear-gradient(180deg,rgba(255,59,92,.2),rgba(255,59,92,.1));border-color:rgba(255,59,92,.45);color:#ffc9d3}
.btn.warn{background:linear-gradient(180deg,rgba(251,191,36,.18),rgba(251,191,36,.08));border-color:rgba(251,191,36,.4);color:#ffe6ae}
.btn.ok{background:linear-gradient(180deg,rgba(61,220,151,.18),rgba(61,220,151,.08));border-color:rgba(61,220,151,.4);color:#b6f5da}
.btn.sm{padding:5px 9px;font-size:11.5px;border-radius:7px}
.btn .sp{width:13px;height:13px;border:2px solid rgba(255,255,255,.25);border-top-color:#fff;border-radius:50%;animation:spin .7s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.iconbtn{display:inline-grid;place-items:center;width:28px;height:28px;border-radius:7px;border:1px solid var(--line);
  background:rgba(11,16,26,.6);color:var(--muted);cursor:pointer;transition:.15s;padding:0}
.iconbtn:hover{color:#fff;border-color:var(--line2);background:var(--panel3)}
.iconbtn.danger:hover{color:#fff;background:rgba(255,59,92,.25);border-color:rgba(255,59,92,.5)}
.iconbtn.ok:hover{color:#fff;background:rgba(61,220,151,.22);border-color:rgba(61,220,151,.5)}
.iconbtn svg{width:14px;height:14px}

/* ---------- Toolbar ---------- */
.toolbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:12px 16px;border-bottom:1px solid var(--line);background:rgba(11,16,26,.35)}
.toolbar .sep{width:1px;height:24px;background:var(--line);margin:0 3px}
.selbar{margin-left:auto;display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.selcount{font-family:var(--mono);font-size:11.5px;color:var(--cyan);background:rgba(34,211,238,.1);border:1px solid rgba(34,211,238,.3);
  padding:5px 10px;border-radius:999px;font-weight:700}

/* ---------- Tabs ---------- */
.tabs{display:flex;gap:4px;padding:10px 14px 0;border-bottom:1px solid var(--line);overflow-x:auto;background:rgba(11,16,26,.35)}
.tab{padding:9px 15px;border-radius:9px 9px 0 0;border:1px solid transparent;border-bottom:0;background:transparent;
  color:var(--muted);font-size:12.5px;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:7px;white-space:nowrap;transition:.15s}
.tab:hover{color:var(--txt);background:rgba(255,255,255,.03)}
.tab.on{color:#fff;background:var(--panel3);border-color:var(--line);box-shadow:inset 0 2px 0 var(--red)}
.tab .badge{font-family:var(--mono);font-size:10px;padding:1px 6px;border-radius:999px;background:#22304a;color:var(--muted);font-weight:700}
.tab.on .badge{background:rgba(255,59,92,.22);color:var(--red2)}
.tab.on .badge.warnb{background:rgba(251,191,36,.2);color:var(--amber)}
.tabpane{display:none;padding:0}
.tabpane.on{display:block;animation:fade .25s ease}
@keyframes fade{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}

/* ---------- Filters ---------- */
.filters{display:flex;align-items:center;gap:8px;padding:11px 14px;border-bottom:1px solid var(--line);flex-wrap:wrap}
.search{position:relative;flex:1 1 240px;min-width:180px}
.search input{width:100%;padding:8px 12px 8px 33px;border-radius:9px;border:1px solid var(--line2);background:rgba(7,10,16,.7);
  color:var(--txt);font-size:12.5px;font-family:inherit;transition:.15s}
.search input:focus{outline:none;border-color:var(--cyan);box-shadow:0 0 0 3px rgba(34,211,238,.13)}
.search svg{position:absolute;left:10px;top:50%;transform:translateY(-50%);width:15px;height:15px;color:var(--dim)}
.search kbd{position:absolute;right:8px;top:50%;transform:translateY(-50%);font-family:var(--mono);font-size:10px;color:var(--dim);
  border:1px solid var(--line);border-radius:4px;padding:1px 5px;background:rgba(0,0,0,.3)}
select.mini,input.mini{padding:8px 10px;border-radius:9px;border:1px solid var(--line2);background:rgba(7,10,16,.7);color:var(--txt);
  font-size:12px;font-family:inherit;cursor:pointer}
select.mini:focus,input.mini:focus{outline:none;border-color:var(--cyan)}
.chips{display:flex;gap:5px;flex-wrap:wrap}
.chip{padding:6px 11px;border-radius:999px;border:1px solid var(--line);background:transparent;color:var(--muted);
  font-size:11.5px;font-weight:700;cursor:pointer;transition:.15s;display:inline-flex;align-items:center;gap:6px}
.chip:hover{border-color:var(--line2);color:var(--txt)}
.chip.on{background:rgba(255,59,92,.14);border-color:rgba(255,59,92,.45);color:#ffc0cb}
.chip .n{font-family:var(--mono);font-size:10px;opacity:.75}

/* ---------- Table ---------- */
.tbl-wrap{overflow:auto;max-height:min(64vh,760px)}
table{width:100%;border-collapse:separate;border-spacing:0;font-size:12.5px}
thead th{position:sticky;top:0;z-index:3;background:#111a2b;border-bottom:1px solid var(--line2);padding:9px 12px;
  text-align:left;font-size:10.5px;text-transform:uppercase;letter-spacing:.8px;color:var(--dim);font-weight:800;white-space:nowrap}
thead th.sortable{cursor:pointer;user-select:none}
thead th.sortable:hover{color:var(--txt)}
thead th .arw{opacity:.35;font-size:9px;margin-left:3px}
thead th.sorted .arw{opacity:1;color:var(--cyan)}
tbody td{padding:9px 12px;border-bottom:1px solid rgba(31,43,64,.55);vertical-align:middle}
tbody tr{transition:background .12s}
tbody tr:hover{background:rgba(255,255,255,.028)}
tbody tr.sel{background:rgba(34,211,238,.06)}
tbody tr.sel:hover{background:rgba(34,211,238,.09)}
tbody tr.exp{background:rgba(255,255,255,.02)}
.cbx{appearance:none;width:15px;height:15px;border-radius:4px;border:1.5px solid var(--line2);background:rgba(7,10,16,.6);cursor:pointer;
  position:relative;transition:.15s;flex:0 0 auto}
.cbx:hover{border-color:var(--cyan)}
.cbx:checked{background:var(--red);border-color:var(--red)}
.cbx:checked::after{content:'';position:absolute;left:4px;top:1px;width:4px;height:8px;border:solid #fff;border-width:0 2px 2px 0;transform:rotate(42deg)}
.title-cell{display:flex;align-items:flex-start;gap:9px;min-width:240px;max-width:520px}
.tw{cursor:pointer;background:none;border:0;color:var(--dim);padding:2px;border-radius:5px;transition:.15s;flex:0 0 auto;margin-top:1px}
.tw:hover{color:var(--cyan);background:rgba(34,211,238,.1)}
.tw svg{width:12px;height:12px;transition:transform .2s;display:block}
tr.expanded .tw svg{transform:rotate(90deg)}
.tname{font-weight:600;color:var(--txt);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:430px;cursor:pointer}
.tname:hover{color:var(--cyan)}
.tmeta{font-family:var(--mono);font-size:10px;color:var(--dim);margin-top:2px;display:flex;gap:7px;flex-wrap:wrap;align-items:center}
.tmeta .tag{padding:0 5px;border-radius:4px;border:1px solid var(--line);background:rgba(0,0,0,.25)}
.prog{min-width:130px}
.prog-top{display:flex;justify-content:space-between;font-family:var(--mono);font-size:10.5px;color:var(--muted);margin-bottom:4px}
.pbar{height:6px;border-radius:5px;background:#1a2437;overflow:hidden;position:relative}
.pbar i{display:block;height:100%;border-radius:5px;background:linear-gradient(90deg,#d92246,var(--red2));transition:width .5s ease;position:relative}
.pbar i::after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent,rgba(255,255,255,.4),transparent);
  animation:shimmer 1.4s linear infinite}
@keyframes shimmer{from{transform:translateX(-100%)}to{transform:translateX(100%)}}
.pbar.done i{background:linear-gradient(90deg,#1f9d6b,var(--green))} .pbar.done i::after{display:none}
.pbar.conv i{background:linear-gradient(90deg,#b7860f,var(--amber))}
.pbar.meta i{background:linear-gradient(90deg,#7c5ce0,var(--violet))}
.pbar.fail i{background:#7a2334} .pbar.fail i::after{display:none}
.pbar.idle i{background:#2c3a55} .pbar.idle i::after{display:none}
.mono{font-family:var(--mono);font-size:11.5px;white-space:nowrap}
.badge{display:inline-flex;align-items:center;gap:5px;padding:3px 9px;border-radius:999px;font-size:10.5px;font-weight:800;
  letter-spacing:.4px;text-transform:uppercase;border:1px solid;white-space:nowrap}
.badge .bd{width:6px;height:6px;border-radius:50%;background:currentColor}
.b-queued{color:#9fb3d4;border-color:#2c3d5c;background:rgba(96,165,250,.08)}
.b-downloading{color:#7dd8f5;border-color:rgba(34,211,238,.45);background:rgba(34,211,238,.12)}
.b-downloading .bd{animation:pulse2 1.1s infinite}
@keyframes pulse2{0%,100%{opacity:1}50%{opacity:.25}}
.b-downloaded{color:#7fe3c0;border-color:rgba(61,220,151,.4);background:rgba(61,220,151,.1)}
.b-metadata{color:#c4b0ff;border-color:rgba(167,139,250,.42);background:rgba(167,139,250,.12)}
.b-converting{color:#ffd98a;border-color:rgba(251,191,36,.42);background:rgba(251,191,36,.11)}
.b-archived{color:#8ee6bd;border-color:rgba(61,220,151,.5);background:rgba(61,220,151,.16)}
.b-paused{color:#f0c987;border-color:rgba(251,191,36,.3);background:rgba(120,90,20,.18)}
.b-failed{color:#ff9db0;border-color:rgba(255,59,92,.5);background:rgba(255,59,92,.14)}
.rowacts{display:flex;gap:5px;justify-content:flex-end}
.detail{background:rgba(7,10,16,.5)}
.detail-in{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px;padding:4px 2px}
.dbox{background:rgba(16,23,37,.7);border:1px solid var(--line);border-radius:10px;padding:11px 12px}
.dbox h4{margin:0 0 7px;font-size:10px;text-transform:uppercase;letter-spacing:.8px;color:var(--dim);font-weight:800}
.dl{display:flex;justify-content:space-between;gap:10px;font-size:11.5px;padding:2.5px 0}
.dl span:first-child{color:var(--muted)}
.dl span:last-child{font-family:var(--mono);color:var(--txt);text-align:right;word-break:break-all;max-width:60%}
.errbox{font-family:var(--mono);font-size:11px;color:#ffb3c1;background:rgba(255,59,92,.09);border:1px solid rgba(255,59,92,.3);
  border-radius:8px;padding:9px 11px;margin-top:8px;white-space:pre-wrap;word-break:break-word;max-height:110px;overflow:auto}
.empty{padding:56px 20px;text-align:center;color:var(--dim)}
.empty .ei{font-size:38px;opacity:.5;margin-bottom:10px}
.empty h3{margin:0 0 6px;font-size:15px;color:var(--muted);font-weight:700}
.empty p{margin:0 0 14px;font-size:12.5px}
.foot-note{padding:9px 14px;border-top:1px solid var(--line);font-size:11px;color:var(--dim);display:flex;gap:14px;flex-wrap:wrap;
  align-items:center;font-family:var(--mono)}

/* ---------- Failed / error center ---------- */
.errgroup{border:1px solid rgba(255,59,92,.28);border-radius:12px;background:rgba(255,59,92,.05);margin-bottom:12px;overflow:hidden}
.errgroup-h{display:flex;align-items:center;gap:11px;padding:11px 14px;flex-wrap:wrap;background:rgba(255,59,92,.07)}
.errgroup-h .sig{font-family:var(--mono);font-size:12px;font-weight:700;color:#ffc0cb;flex:1 1 240px;min-width:0;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.errgroup-h .cnt{font-family:var(--mono);font-size:11px;padding:2px 8px;border-radius:999px;background:rgba(255,59,92,.2);color:#ff9db0;font-weight:800}
.errgroup-b{padding:12px 14px}
.fix{display:flex;gap:9px;align-items:flex-start;padding:9px 11px;border-radius:9px;background:rgba(34,211,238,.07);
  border:1px solid rgba(34,211,238,.25);font-size:12px;color:#c8f2fb;margin-bottom:10px}
.fix .fi{font-size:14px;line-height:1.3}
.joblist{display:flex;flex-direction:column;gap:5px}
.jmini{display:flex;align-items:center;gap:9px;padding:7px 10px;border-radius:8px;background:rgba(7,10,16,.5);border:1px solid var(--line);font-size:12px}
.jmini .nm{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.jmini .fd{font-family:var(--mono);font-size:10px;color:var(--dim)}

/* ---------- Logs ---------- */
.logbar{display:flex;align-items:center;gap:8px;padding:11px 14px;border-bottom:1px solid var(--line);flex-wrap:wrap}
.seg{display:inline-flex;border:1px solid var(--line2);border-radius:9px;overflow:hidden;background:rgba(7,10,16,.6)}
.seg button{padding:7px 13px;background:transparent;border:0;color:var(--muted);font-size:11.5px;font-weight:700;cursor:pointer;transition:.15s}
.seg button+button{border-left:1px solid var(--line2)}
.seg button:hover{color:var(--txt);background:rgba(255,255,255,.04)}
.seg button.on{background:rgba(255,59,92,.16);color:#ffc0cb}
.terminal{background:#05080e;border-top:1px solid var(--line);padding:12px 14px;height:min(58vh,620px);overflow:auto;
  font-family:var(--mono);font-size:11.5px;line-height:1.75}
.ln{display:flex;gap:9px;padding:1px 0;border-radius:3px;white-space:pre-wrap;word-break:break-word}
.ln:hover{background:rgba(255,255,255,.03)}
.ln .ts{color:#3f5474;flex:0 0 auto}
.ln .msg{color:#a9bcda;flex:1;min-width:0}
.ln.err .msg{color:#ff9db0} .ln.warn .msg{color:#ffd98a} .ln.ok .msg{color:#8ee6bd} .ln.info .msg{color:#7dd8f5}
.ln.fatal{background:rgba(255,59,92,.1)}

/* ---------- Health ---------- */
.depgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(268px,1fr));gap:11px}
.dep{display:flex;gap:11px;padding:12px;border-radius:11px;border:1px solid var(--line);background:rgba(11,16,26,.6);transition:.2s}
.dep:hover{border-color:var(--line2)}
.dep .di{width:34px;height:34px;border-radius:9px;display:grid;place-items:center;font-size:16px;flex:0 0 auto;border:1px solid var(--line2)}
.dep.ok .di{background:rgba(61,220,151,.13);border-color:rgba(61,220,151,.35)}
.dep.bad .di{background:rgba(255,59,92,.13);border-color:rgba(255,59,92,.4)}
.dep.warn .di{background:rgba(251,191,36,.13);border-color:rgba(251,191,36,.4)}
.dep .dn{font-weight:700;font-size:12.5px}
.dep .dv{font-family:var(--mono);font-size:10.5px;color:var(--dim);margin-top:2px;word-break:break-all}
.dep .ds{margin-left:auto;font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.6px;align-self:flex-start}
.dep.ok .ds{color:var(--green)} .dep.bad .ds{color:var(--red2)} .dep.warn .ds{color:var(--amber)}
.cfggrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(215px,1fr));gap:9px}
.cfgitem{padding:9px 11px;border-radius:9px;border:1px solid var(--line);background:rgba(11,16,26,.55)}
.cfgitem .ck{font-size:10px;text-transform:uppercase;letter-spacing:.7px;color:var(--dim);font-weight:700}
.cfgitem .cv{font-family:var(--mono);font-size:12.5px;margin-top:3px;color:var(--txt);word-break:break-all}
.subhead{font-size:11px;text-transform:uppercase;letter-spacing:.9px;color:var(--dim);font-weight:800;margin:18px 0 10px;display:flex;align-items:center;gap:8px}
.subhead:first-child{margin-top:0}
.subhead::after{content:'';flex:1;height:1px;background:var(--line)}

/* ---------- Modal ---------- */
.overlay{position:fixed;inset:0;background:rgba(3,6,11,.78);backdrop-filter:blur(6px);z-index:100;display:none;
  align-items:flex-start;justify-content:center;padding:5vh 16px;overflow:auto}
.overlay.on{display:flex;animation:fade .2s ease}
.modal{width:100%;max-width:660px;background:linear-gradient(180deg,#151f31,#101725);border:1px solid var(--line2);
  border-radius:16px;box-shadow:0 30px 80px rgba(0,0,0,.6);animation:pop .24s cubic-bezier(.2,.9,.3,1.2)}
.modal.narrow{max-width:430px}
@keyframes pop{from{opacity:0;transform:translateY(14px) scale(.97)}to{opacity:1;transform:none}}
.modal-h{display:flex;align-items:center;gap:11px;padding:15px 18px;border-bottom:1px solid var(--line)}
.modal-h h3{margin:0;font-size:15px;font-weight:800}
.modal-h .x{margin-left:auto;background:none;border:0;color:var(--dim);cursor:pointer;font-size:20px;line-height:1;padding:2px 6px;border-radius:6px}
.modal-h .x:hover{color:#fff;background:rgba(255,255,255,.06)}
.modal-b{padding:18px}
.modal-f{padding:13px 18px;border-top:1px solid var(--line);display:flex;gap:9px;justify-content:flex-end;flex-wrap:wrap}
.field{margin-bottom:14px}
.field label{display:block;font-size:11px;text-transform:uppercase;letter-spacing:.7px;color:var(--muted);font-weight:800;margin-bottom:6px}
.field .hint{font-size:11px;color:var(--dim);margin-top:5px}
.field input[type=text],.field textarea,.field select{width:100%;padding:10px 12px;border-radius:9px;border:1px solid var(--line2);
  background:rgba(7,10,16,.75);color:var(--txt);font-size:13px;font-family:inherit;transition:.15s}
.field textarea{font-family:var(--mono);font-size:12px;min-height:96px;resize:vertical;line-height:1.7}
.field input:focus,.field textarea:focus,.field select:focus{outline:none;border-color:var(--cyan);box-shadow:0 0 0 3px rgba(34,211,238,.13)}
.field.bad input,.field.bad textarea{border-color:var(--red)}
.field .err-t{color:var(--red2);font-size:11.5px;margin-top:5px;display:none}
.field.bad .err-t{display:block}
.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}
@media(max-width:560px){.two{grid-template-columns:1fr}}
.toggles{display:grid;grid-template-columns:repeat(auto-fit,minmax(168px,1fr));gap:8px}
.tg{display:flex;align-items:center;gap:9px;padding:9px 11px;border-radius:9px;border:1px solid var(--line);background:rgba(11,16,26,.5);
  cursor:pointer;font-size:12px;transition:.15s;user-select:none}
.tg:hover{border-color:var(--line2)}
.tg input{appearance:none;width:16px;height:16px;border-radius:5px;border:1.5px solid var(--line2);position:relative;cursor:pointer;transition:.15s;margin:0;flex:0 0 auto}
.tg input:checked{background:var(--green);border-color:var(--green)}
.tg input:checked::after{content:'';position:absolute;left:4.5px;top:1.5px;width:4px;height:8px;border:solid #06120c;border-width:0 2px 2px 0;transform:rotate(42deg)}
.scanres{margin-top:12px;display:none}
.scanres.on{display:block}
.scanrow{display:flex;align-items:center;gap:9px;padding:7px 10px;border-radius:8px;background:rgba(7,10,16,.5);border:1px solid var(--line);
  font-family:var(--mono);font-size:11px;margin-bottom:5px}
.scanrow .u{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

/* ---------- Toasts ---------- */
.toasts{position:fixed;right:16px;bottom:16px;z-index:200;display:flex;flex-direction:column;gap:9px;max-width:min(400px,calc(100vw - 32px))}
.toast{display:flex;gap:10px;align-items:flex-start;padding:11px 13px;border-radius:11px;border:1px solid;background:rgba(16,23,37,.97);
  box-shadow:0 14px 40px rgba(0,0,0,.5);animation:slideIn .26s cubic-bezier(.2,.9,.3,1.1);font-size:12.5px;backdrop-filter:blur(8px)}
@keyframes slideIn{from{opacity:0;transform:translateX(24px)}to{opacity:1;transform:none}}
.toast.out{animation:slideOut .25s ease forwards}
@keyframes slideOut{to{opacity:0;transform:translateX(24px)}}
.toast .ti{font-size:15px;line-height:1.2}
.toast .tb{flex:1;min-width:0}
.toast .tt{font-weight:800;margin-bottom:1px}
.toast .tm{color:var(--muted);word-break:break-word}
.toast.ok{border-color:rgba(61,220,151,.4)} .toast.ok .tt{color:var(--green)}
.toast.err{border-color:rgba(255,59,92,.45)} .toast.err .tt{color:var(--red2)}
.toast.warn{border-color:rgba(251,191,36,.42)} .toast.warn .tt{color:var(--amber)}
.toast.info{border-color:rgba(34,211,238,.4)} .toast.info .tt{color:var(--cyan)}
.toast .tx{background:none;border:0;color:var(--dim);cursor:pointer;font-size:15px;padding:0;line-height:1}
.toast .tx:hover{color:#fff}

.foot{margin-top:18px;text-align:center;font-size:11px;color:var(--dim);font-family:var(--mono)}
.foot b{color:var(--muted)}
.hidden{display:none !important}
@media(max-width:760px){
  .app{padding:12px 12px 40px}
  .brand h1{font-size:15px} .clock{display:none}
  .card .v{font-size:22px}
  .selbar{margin-left:0;width:100%}
  .tname{max-width:180px}
}
</style>
</head>
<body>
<div class="app">

  <!-- ===== HEADER ===== -->
  <div class="topbar">
    <div class="brand">
      <div class="logo">
        <svg viewBox="0 0 24 24" fill="none"><path d="M4 5.5A2.5 2.5 0 0 1 6.5 3h11A2.5 2.5 0 0 1 20 5.5v8a2.5 2.5 0 0 1-2.5 2.5h-3.2l-2.6 3.2a1 1 0 0 1-1.56 0L7.5 16H6.5A2.5 2.5 0 0 1 4 13.5v-8Z" stroke="#ff3b5c" stroke-width="1.6"/><path d="M10 7.4 15 10l-5 2.6V7.4Z" fill="#ff3b5c"/></svg>
      </div>
      <div>
        <h1>🎬 YouTube Archive Engine <span>V5</span></h1>
        <p id="engineSub">central-sqlite · resilient · autonomous · proxy-free</p>
      </div>
    </div>
    <div class="topbar-right">
      <div class="clock" id="clock">--:--:--</div>
      <div class="pill" id="connPill" title="Engine connection"><span class="dot" id="connDot"></span><span id="connTxt">Connecting…</span></div>
      <label class="switch" title="Force the offline simulation sandbox"><input type="checkbox" id="demoToggle"><span>Demo mode</span></label>
      <button class="btn primary" id="btnAdd">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg>
        Add Playlist / Channel
      </button>
    </div>
  </div>

  <!-- ===== ALERTS ===== -->
  <div class="alertbar" id="alertBar"></div>

  <!-- ===== STAT CARDS ===== -->
  <div class="grid g-stats">
    <div class="card"><div class="k">📦 Total Jobs</div><div class="v" id="sTotal">0</div><div class="s" id="sTotalSub">across 0 folders</div><span class="spark">🗄️</span></div>
    <div class="card accent-cyan"><div class="k">⏳ Not Started</div><div class="v" id="sQueued">0</div><div class="s" id="sQueuedSub">waiting for a worker</div><span class="spark">📥</span></div>
    <div class="card accent-red"><div class="k">⬇️ Downloading</div><div class="v" id="sSpeed">0 B/s</div><div class="s" id="sSpeedSub">0 active workers</div><span class="spark">🚀</span></div>
    <div class="card accent-green"><div class="k">✅ Completed</div><div class="v" id="sDone">0</div><div class="s" id="sDoneSub">archived &amp; verified</div><span class="spark">🏁</span></div>
    <div class="card accent-amber"><div class="k">❌ Failed</div><div class="v" id="sFailed">0</div><div class="s" id="sFailedSub">requires attention</div><span class="spark">⚠️</span></div>
    <div class="card accent-violet"><div class="k">💾 Free Disk</div><div class="v" id="sDisk">--</div><div class="s" id="sDiskSub">of -- total</div><span class="spark">🗃️</span></div>
  </div>

  <!-- ===== PIPELINE ===== -->
  <div class="panel">
    <div class="panel-h">
      <h2>🔀 Processing Pipeline</h2>
      <span class="pill" id="pipeState"><span class="dot" id="pipeDot"></span><span id="pipeTxt">Idle</span></span>
      <div style="margin-left:auto;display:flex;gap:8px;flex-wrap:wrap">
        <button class="btn sm" id="btnScan" title="Re-scan all configured playlists/channels">📡 Scan &amp; Add to Queue</button>
        <button class="btn sm warn" id="btnPause">⏸️ Pause All</button>
        <button class="btn sm" id="btnRefresh">🔄 Refresh</button>
      </div>
    </div>
    <div class="panel-b">
      <div class="pipeline" id="pipeline"></div>
      <div style="height:14px"></div>
      <div class="grid g-3">
        <div class="card">
          <div class="k">📈 Aggregate Throughput</div>
          <div style="display:flex;align-items:flex-end;gap:12px;flex-wrap:wrap;margin-top:4px">
            <div class="speed-big" id="bigSpeed">0 B/s</div>
            <div style="font-size:11.5px;color:var(--muted);padding-bottom:6px" id="bigSpeedSub">peak — · cap unlimited</div>
          </div>
          <canvas id="spark"></canvas>
        </div>
        <div class="card">
          <div class="k">🗄️ Storage</div>
          <div class="gauge-wrap" style="margin-top:8px">
            <div class="gauge">
              <svg width="96" height="96" viewBox="0 0 96 96">
                <circle cx="48" cy="48" r="40" fill="none" stroke="#1b2740" stroke-width="9"/>
                <circle id="gaugeArc" cx="48" cy="48" r="40" fill="none" stroke="url(#gg)" stroke-width="9" stroke-linecap="round"
                        stroke-dasharray="251.3" stroke-dashoffset="251.3" style="transition:stroke-dashoffset .7s ease"/>
                <defs><linearGradient id="gg" x1="0" y1="0" x2="1" y2="1">
                  <stop offset="0%" stop-color="#3ddc97"/><stop offset="100%" stop-color="#22d3ee"/></linearGradient></defs>
              </svg>
              <div class="gv" id="gaugeVal">--</div>
              <div class="gl">free</div>
            </div>
            <div class="kv">
              <div class="kv-row"><span>Free</span><span id="diskFree">--</span></div>
              <div class="kv-row"><span>Total</span><span id="diskTotal">--</span></div>
              <div class="kv-row"><span>Output root</span><span id="diskRoot" title="">--</span></div>
              <div>
                <div class="kv-row"><span>Min free guard</span><span id="diskGuard">--</span></div>
                <div class="meter green"><i id="diskGuardBar" style="width:0%"></i></div>
              </div>
            </div>
          </div>
        </div>
        <div class="card">
          <div class="k">🖥️ System &amp; Queue</div>
          <div class="kv" style="margin-top:10px">
            <div class="kv-row"><span>Queue position</span><span id="qPos">--</span></div>
            <div class="kv-row"><span>Global ETA</span><span id="qEta">--</span></div>
            <div class="kv-row"><span>Uptime</span><span id="qUptime">--</span></div>
            <div>
              <div class="kv-row"><span>Workers (active/target)</span><span id="qWorkers">0 / 0</span></div>
              <div class="meter cyan"><i id="qWorkersBar" style="width:0%"></i></div>
            </div>
            <div>
              <div class="kv-row"><span>RAM</span><span id="qRam">--</span></div>
              <div class="meter amber"><i id="qRamBar" style="width:0%"></i></div>
            </div>
          </div>
        </div>
      </div>
      <div class="subhead" style="margin-bottom:9px">Worker Pool</div>
      <div class="workers" id="workers"></div>
    </div>
  </div>

  <!-- ===== MAIN PANEL ===== -->
  <div class="panel">
    <div class="toolbar">
      <button class="btn sm" id="btnPurge">🗑️ Purge Queue</button>
      <button class="btn sm ok" id="btnResumePaused">▶️ Resume Paused</button>
      <button class="btn sm warn" id="btnRetryFailed">🔄 Retry All Failed</button>
      <button class="btn sm" id="btnMetaRun" title="Force the metadata worker to sweep downloaded jobs">🏷️ Run Metadata Pass</button>
      <button class="btn sm" id="btnConvRun" title="Force the converter worker to sweep downloaded jobs">🎞️ Run Convert Pass</button>
      <span class="sep"></span>
      <button class="btn sm" id="btnExport" title="Export current job table as CSV">⬇️ Export CSV</button>
      <div class="selbar">
        <span class="selcount" id="selCount">0 selected</span>
        <button class="btn sm" id="btnSelRetry" disabled>🔄 Retry Selected</button>
        <button class="btn sm" id="btnSelPause" disabled>⏸️ Pause Selected</button>
        <button class="btn sm danger" id="btnSelDel" disabled>🗑️ Delete Selected</button>
      </div>
    </div>

    <div class="tabs" id="tabs">
      <button class="tab on" data-tab="jobs">📋 Jobs <span class="badge" id="bJobs">0</span></button>
      <button class="tab" data-tab="failed">❌ Failed <span class="badge warnb" id="bFailed">0</span></button>
      <button class="tab" data-tab="history">📜 History <span class="badge" id="bHist">0</span></button>
      <button class="tab" data-tab="logs">📝 Logs</button>
      <button class="tab" data-tab="health">🩺 Health <span class="badge" id="bHealth">–</span></button>
      <button class="tab" data-tab="db">🗄️ Database</button>
    </div>

    <!-- JOBS -->
    <div class="tabpane on" id="pane-jobs">
      <div class="filters">
        <div class="search">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg>
          <input type="text" id="q" placeholder="Search title, folder, video id…" autocomplete="off"><kbd>/</kbd>
        </div>
        <div class="chips" id="statusChips"></div>
        <select class="mini" id="folderSel" title="Filter by destination folder"></select>
        <select class="mini" id="pageSize">
          <option value="50">50 rows</option><option value="100" selected>100 rows</option>
          <option value="250">250 rows</option><option value="9999">All rows</option>
        </select>
      </div>
      <div class="tbl-wrap" id="tblWrap">
        <table>
