    await writeFile(backup, rawText, "utf-8").catch(() => {});
    throw new Error(`config.json is not valid JSON (${(e as Error).message}). A copy was saved to ${backup}.`);
  }
  const merged = { ...DEFAULT_CONFIG, ...(parsedJson as object) };
  const result = ConfigSchema.safeParse(merged);
  if (!result.success) {
    const issues = result.error.issues.map(i => `  • ${i.path.join(".") || "(root)"}: ${i.message}`).join("\n");
    throw new Error(`config.json failed validation:\n${issues}`);
  }
  return result.data as Config;
}

