```typescript
// update_config.ts — V6 "Central Database Edition"
// Interactive + non-interactive configuration manager for the YouTube Archive Engine.
//
//   bun run update_config.ts                 # interactive menu
//   bun run update_config.ts --print         # dump the effective config
//   bun run update_config.ts --validate      # validate only (exit 1 on failure)
//   bun run update_config.ts --reset         # restore defaults (backs up the old file)
//   bun run update_config.ts --set videoQuality=720p --set daemonMode=true
//   bun run update_config.ts --add-playlist "https://youtube.com/playlist?list=..."
//   bun run update_config.ts --add-channel "https://youtube.com/@handle"
//   bun run update_config.ts --doctor        # dependency + config diagnostics

import { readFile, writeFile, copyFile } from "node:fs/promises";
import { existsSync, statSync } from "node:fs";
import { createInterface } from "node:readline/promises";
import { resolve } from "node:path";
import { z } from "zod";

const CONFIG_PATH = "./config.json";
const SCHEMA_NAME = "Archive Engine V6";
const rl = createInterface({ input: process.stdin, output: process.stdout });

/* ==========================================================================
   1. ZOD SCHEMA  (single source of truth — keep in sync with the downloader)
   ========================================================================== */

const ConfigSchema = z.object({
  // ---- sources -------------------------------------------------------------
  playlists:        z.array(z.string()).default([]),
  channels:         z.array(z.string()).default([]),
  channelPlaylists: z.array(z.string()).default([]),
  folderOverrides:  z.record(z.string(), z.string()).default({}),

  // ---- workers / autoscale -------------------------------------------------
  maxConcurrentDownloads: z.number().int().min(1).max(20).default(3),
  maxConcurrentConverts:  z.number().int().min(1).max(10).default(2),
  metadataWorkers:        z.number().int().min(1).max(8).default(1),
  maxDownloadWorkers:     z.number().int().min(1).max(20).default(5),
  minDownloadWorkers:     z.number().int().min(1).max(20).default(1),
  autoscaleEnabled:       z.boolean().default(true),
  maxBandwidthKBps:       z.number().min(0).default(0),
  scanConcurrency:        z.number().int().min(1).max(8).default(2),

  // ---- resilience ----------------------------------------------------------
  maxRetryAttempts:     z.number().int().min(1).max(20).default(3),
  maxFailures:          z.number().int().min(1).default(10),
  maxFailuresPerVideo:  z.number().int().min(1).default(4),
  claimTimeoutSeconds:  z.number().int().min(15).max(3600).default(180),
  heartbeatSeconds:     z.number().int().min(1).max(60).default(3),
  downloadTimeoutMinutes: z.number().int().min(1).max(600).default(90),
  socketTimeout:        z.number().int().min(5).max(300).default(15),
  fragmentRetries:      z.number().int().min(0).max(50).default(10),
  concurrentFragments:  z.number().int().min(1).max(64).default(16),
  transientBackoffSeconds: z.number().int().min(1).max(600).default(30),
  minFreeSpaceGB:       z.number().min(0).default(10),

  // ---- paths ---------------------------------------------------------------
  denoPath:      z.string().default("deno"),
  outputRoot:    z.string().default("./downloads"),
  secondaryStoragePath: z.string().default(""),
  archiveFile:   z.string().default("downloaded_videos.txt"),
  cookiesFile:   z.string().default("cookies.txt"),
  dbPath:        z.string().default("./archive.db"),
  errorLog:      z.string().default("error.log"),
  reportLog:     z.string().default("report.log"),

  // ---- media policy --------------------------------------------------------
  videoQuality: z.enum(["highest", "1080p", "720p", "480p", "audio"]).default("1080p"),
  targetFormat: z.enum(["mp4", "mkv", "mp3", "m4a", "webm"]).default("mp4"),
  deleteSourceAfterConvert: z.boolean().default(true),
  downloadSubtitles: z.boolean().default(true),
  subtitleLangs:     z.string().default("en.*,en"),
  embedMetadata:     z.boolean().default(true),
  writeInfoJson:     z.boolean().default(true),
  writeDescription:  z.boolean().default(true),
  writeThumbnail:    z.boolean().default(true),
  verifyIntegrity:   z.boolean().default(true),
  archiveLiveStreams: z.boolean().default(false),
  skipShorts:        z.boolean().default(true),
  downloadShorts:    z.boolean().default(false),
  cleanOrphanedDays: z.number().int().min(0).max(365).default(7),

  // ---- service -------------------------------------------------------------
  validateCookiesOnStart: z.boolean().default(true),
  daemonMode:       z.boolean().default(false),
  enableWebUi:      z.boolean().default(true),
  enableTui:        z.boolean().default(true),
  webHost:          z.string().default("0.0.0.0"),
  webPort:          z.number().int().min(1).max(65535).default(3000),
  rssEnabled:       z.boolean().default(true),
  rssPollIntervalMinutes: z.number().int().min(1).max(1440).default(15),
  rescanIntervalHours:    z.number().min(0).max(720).default(24),
  logLevel:         z.enum(["debug", "info", "warn", "error"]).default("info"),
}).strict().catchall(z.unknown());

type Config = z.infer<typeof ConfigSchema>;
const DEFAULT_CONFIG: Config = ConfigSchema.parse({});

/* ==========================================================================
   2. LOAD / SAVE  (atomic write + timestamped backup + validation)
   ========================================================================== */

async function backupConfig(): Promise<string | null> {
  if (!existsSync(CONFIG_PATH)) return null;
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  const dest = `${CONFIG_PATH}.bak.${stamp}`;
  await copyFile(CONFIG_PATH, dest).catch(() => {});
  return existsSync(dest) ? dest : null;
}

async function loadConfig(): Promise<{ config: Config; created: boolean; repaired: boolean; warnings: string[] }> {
  const warnings: string[] = [];
  if (!existsSync(CONFIG_PATH)) {
    await writeFile(CONFIG_PATH, JSON.stringify(DEFAULT_CONFIG, null, 2), "utf-8");
    return { config: { ...DEFAULT_CONFIG }, created: true, repaired: false, warnings };
  }
  const rawText = await readFile(CONFIG_PATH, "utf-8");
  let parsed: unknown;
  try {
    parsed = JSON.parse(rawText);
  } catch (e) {
    const bak = await backupConfig();
    warnings.push(`config.json is not valid JSON (${(e as Error).message}). Backup: ${bak ?? "failed"}. Falling back to defaults.`);
    return { config: { ...DEFAULT_CONFIG }, created: false, repaired: true, warnings };
  }
  const merged = { ...DEFAULT_CONFIG, ...(parsed as object) };
  const result = ConfigSchema.safeParse(merged);
  if (!result.success) {
    const bak = await backupConfig();
    const lines = result.error.issues.map(i => `   • ${i.path.join(".") || "(root)"}: ${i.message}`);
    warnings.push(`config.json failed validation (backup: ${bak ?? "failed"}):\n${lines.join("\n")}`);
    // salvage: strip unknown/invalid keys and keep whatever validates
    const loose: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(merged)) {
      const one = ConfigSchema.shape[k as keyof typeof ConfigSchema.shape];
      if (!one) continue;
      const r = (one as z.ZodTypeAny).safeParse(v);
      if (r.success) loose[k] = r.data;
    }
    const salvaged = ConfigSchema.parse({ ...DEFAULT_CONFIG, ...loose }) as Config;
    return { config: salvaged, created: false, repaired: true, warnings };
  }
  return { config: result.data as Config, created: false, repaired: false, warnings };
}

async function saveConfig(config: Config): Promise<void> {
  const validated = ConfigSchema.parse(config);          // hard gate before touching disk
  const crossProblems = crossValidate(validated);
  if (crossProblems.length) {
    console.log(`\n\x1b[33m⚠️  Cross-field warnings (saved anyway):\x1b[0m`);
    crossProblems.forEach(p => console.log(`   • ${p}`));
  }
  await backupConfig();
  const tmp = `${CONFIG_PATH}.tmp`;
  await writeFile(tmp, JSON.stringify(validated, null, 2), "utf-8");
  const { rename } = await import("node:fs/promises");
  await rename(tmp, CONFIG_PATH);                          // atomic replace
  console.log(`\n\x1b[32m✅ Saved → ${resolve(CONFIG_PATH)}\x1b[0m`);
}

function crossValidate(c: Config): string[] {
  const out: string[] = [];
  if (c.minDownloadWorkers > c.maxDownloadWorkers) out.push("minDownloadWorkers > maxDownloadWorkers — the autoscaler will clamp it.");
  if (c.maxConcurrentDownloads > c.maxDownloadWorkers) out.push("maxConcurrentDownloads exceeds maxDownloadWorkers ceiling.");
  if (c.videoQuality === "audio" && ["mp4", "mkv", "webm"].includes(c.targetFormat))
    out.push(`videoQuality=audio with targetFormat=${c.targetFormat}; the engine will transcode to mp3 instead.`);
  if (!c.daemonMode && c.rescanIntervalHours > 0) out.push("rescanIntervalHours is ignored unless daemonMode=true.");
  if (c.rssEnabled && !c.daemonMode) out.push("rssEnabled has no effect unless daemonMode=true.");
  if (c.skipShorts && c.downloadShorts) out.push("skipShorts and downloadShorts are both true — skipShorts wins.");
  if (c.playlists.length + c.channels.length + c.channelPlaylists.length === 0 && !c.daemonMode)
    out.push("No sources configured: the engine will start idle. Add playlists/channels or enable daemonMode.");
  if (c.minFreeSpaceGB < 1) out.push("minFreeSpaceGB below 1 GB risks ENOSPC mid-download.");
  if (c.webPort < 1024) out.push(`webPort ${c.webPort} is privileged — the process may need elevated rights.`);
  return out;
}

/* ==========================================================================
   3. PROMPT HELPERS  (validated, non-crashing)
   ========================================================================== */

const ask = (q: string) => rl.question(q);

async function askYesNo(q: string, def: boolean): Promise<boolean> {
  for (let i = 0; i < 5; i++) {
    const ans = (await ask(`${q} ${def ? "[Y/n]" : "[y/N]"}: `)).trim().toLowerCase();
    if (ans === "") return def;
    if (["y", "yes", "true", "1", "on"].includes(ans)) return true;
    if (["n", "no", "false", "0", "off"].includes(ans)) return false;
    console.log("   ⚠️  Please answer y or n.");
  }
  console.log("   ⚠️  Too many invalid answers — keeping the current value.");
  return def;
}

async function askNumber(q: string, current: number, min?: number, max?: number, allowFloat = false): Promise<number> {
  for (let i = 0; i < 6; i++) {
    const ans = (await ask(`${q} [current: ${current}]: `)).trim();
    if (ans === "") return current;
    const n = allowFloat ? parseFloat(ans) : parseInt(ans, 10);
    if (Number.isNaN(n)) { console.log("   ⚠️  Please enter a valid number."); continue; }
    if (min !== undefined && n < min) { console.log(`   ⚠️  Must be >= ${min}.`); continue; }
    if (max !== undefined && n > max) { console.log(`   ⚠️  Must be <= ${max}.`); continue; }
    if (!allowFloat && !Number.isInteger(n)) { console.log("   ⚠️  Must be a whole number."); continue; }
    return n;
  }
  console.log("   ⚠️  Keeping the current value.");
  return current;
}

async function askString(q: string, current: string, opts: { required?: boolean; validate?: (v: string) => string | null } = {}): Promise<string> {
  for (let i = 0; i < 5; i++) {
    const ans = (await ask(`${q} [current: ${current || "(empty)"}]: `)).trim();
    if (ans === "") {
      if (opts.required && !current) { console.log("   ⚠️  A value is required."); continue; }
      return current;
    }
    if (opts.validate) {
      const err = opts.validate(ans);
      if (err) { console.log(`   ⚠️  ${err}`); continue; }
    }
    return ans;
  }
  return current;
}

async function askChoice<T extends string>(q: string, options: readonly T[], current: string): Promise<T> {
  for (let i = 0; i < 5; i++) {
    console.log(`\n${q} [current: ${current}]`);
    options.forEach((o, idx) => console.log(`   ${idx + 1}. ${o}${o === current ? "  ←" : ""}`));
    const ans = (await ask("Select number (or Enter to keep): ")).trim();
    if (ans === "") return current as T;
    const idx = parseInt(ans, 10) - 1;
    if (idx >= 0 && idx < options.length) return options[idx];
    console.log("   ⚠️  Invalid selection.");
  }
  return current as T;
}

async function askMultiLine(prompt: string): Promise<string[]> {
  console.log(`\n${prompt}`);
  console.log("(paste one or more lines; empty line to finish)\n");
  const links: string[] = [];
  for (let i = 0; i < 500; i++) {
    const line = await ask(" > ");
    if (line.trim() === "") break;
    links.push(...line.split(/[,\n]+/).map(s => s.trim()).filter(Boolean));
  }
  return links;
}

function isValidPlaylistUrl(url: string): string | null {
  try {
    const u = new URL(url);
    if (!/youtube\.com|youtu\.be/.test(u.hostname)) return "Not a YouTube URL.";
    if (!u.searchParams.has("list")) return "Missing ?list= parameter (not a playlist URL).";
    return null;
  } catch { return "Not a valid absolute URL."; }
}
function isValidChannelUrl(url: string): string | null {
  try {
    const u = new URL(url);
    if (!/youtube\.com|youtu\.be/.test(u.hostname)) return "Not a YouTube URL.";
    if (!/(@|\/channel\/|\/c\/|\/user\/|\/videos)/.test(u.pathname + u.search)) return "Expected @handle, /channel/UC…, or /videos.";
    return null;
  } catch { return "Not a valid absolute URL."; }
}
function isValidPath(v: string): string | null {
  if (v.includes("\0")) return "Path contains a null byte.";
  if (v.length > 4000) return "Path too long.";
  return null;
}

/* ==========================================================================
   4. URL LIST MANAGER
   ========================================================================== */

async function manageUrlList(config: Config, key: "playlists" | "channels" | "channelPlaylists", title: string): Promise<Config> {
  const validator = key === "playlists" ? isValidPlaylistUrl : isValidChannelUrl;
  while (true) {
    console.clear();
    console.log(`📂 Manage ${title}\n`);
    const list = (config[key] || []) as string[];
    if (list.length === 0) console.log("   (none configured)\n");
    else list.forEach((url, i) => {
      const folder = (config.folderOverrides?.[url]) || "";
      console.log(`   ${String(i + 1).padStart(3)}. ${url}${folder ? `   \x1b[90m→ folder: ${folder}\x1b[0m` : ""}`);
    });
    console.log("\n   A. Add new");
    console.log("   R. Remove one");
    console.log("   F. Set destination folder override");
    console.log("   C. Clear all");
    console.log("   B. Back\n");
    const choice = (await ask("Select: ")).trim().toLowerCase();

    if (choice === "a") {
      const newLinks = await askMultiLine(`Enter ${title} URLs / handles:`);
      let added = 0, skipped = 0;
      for (const link of newLinks) {
        const err = validator(link);
        if (err) { console.log(`   ⚠️  Skipping "${link}" — ${err}`); skipped++; continue; }
        if (list.includes(link)) { console.log(`   • Already present: ${link}`); skipped++; continue; }
        list.push(link); added++;
      }
      config[key] = list as never;
      console.log(`\n   ✅ Added ${added} item(s)${skipped ? `, skipped ${skipped}` : ""}.`);
      await ask("Press Enter to continue…");
    } else if (choice === "r") {
      if (list.length === 0) { await ask("Nothing to remove. Press Enter…"); continue; }
      const ans = (await ask("Enter number to remove (or 'all'): ")).trim().toLowerCase();
      if (ans === "all") {
        if (await askYesNo("Remove ALL entries?", false)) { config[key] = [] as never; }
      } else {
        const i = parseInt(ans, 10) - 1;
        if (i >= 0 && i < list.length) {
          const removed = list.splice(i, 1)[0];
          if (config.folderOverrides?.[removed]) delete config.folderOverrides[removed];
          console.log(`   ✅ Removed ${removed}`);
        } else console.log("   ⚠️  Invalid number.");
      }
      await ask("Press Enter to continue…");
    } else if (choice === "f") {
      if (list.length === 0) { await ask("Nothing to map. Press Enter…"); continue; }
      const i = parseInt((await ask("Entry number: ")).trim(), 10) - 1;
      if (i < 0 || i >= list.length) { console.log("   ⚠️  Invalid number."); await ask("Press Enter…"); continue; }
      const url = list[i];
      config.folderOverrides = config.folderOverrides || {};
      const cur = config.folderOverrides[url] || "";
      const folder = await askString(`Destination folder name for ${url}`, cur, {
        validate: v => (/[/:*?"<>|]/.test(v) ? "Folder names cannot contain / \\ : * ? \" < > |" : null),
      });
      if (folder) config.folderOverrides[url] = folder;
      else delete config.folderOverrides[url];
      console.log(folder ? `   ✅ Will download into <outputRoot>/${folder}` : "   ✅ Override cleared (auto-detect from playlist title).");
      await ask("Press Enter to continue…");
    } else if (choice === "c") {
      if (await askYesNo(`Clear ALL ${title}?`, false)) config[key] = [] as never;
      await ask("Press Enter to continue…");
    } else if (choice === "b") return config;
  }
}

