    if (flag("--reset")) {
      const bak = await backupConfig();
      config = { ...DEFAULT_CONFIG };
      await saveConfig(config);
      console.log(`\x1b[33m♻️  Defaults restored${bak ? ` (previous file: ${bak})` : ""}.\x1b[0m`);
      rl.close(); return;
    }

    const sets = allValues("--set");
    const addPlaylists = allValues("--add-playlist");
    const addChannels = allValues("--add-channel");
    const addChannelPlaylists = allValues("--add-channel-playlist");
    const mutated = sets.length > 0 || addPlaylists.length > 0 || addChannels.length > 0 || addChannelPlaylists.length > 0;

    if (sets.length) {
      const r = await applySetFlags(config, sets);
      if (r.errors.length) {
        console.error(`\x1b[31m❌ --set rejected:\x1b[0m\n${r.errors.map(e => `   • ${e}`).join("\n")}`);
        rl.close(); process.exit(1);
      }
      config = r.config;
    }
    const push = (key: "playlists" | "channels" | "channelPlaylists", urls: string[], validate: (u: string) => string | null) => {
      for (const u of urls) {
        const err = validate(u);
        if (err) { console.log(`\x1b[33m⚠️  Skipped "${u}" — ${err}\x1b[0m`); continue; }
        if (!config[key].includes(u)) { (config[key] as string[]).push(u); console.log(`\x1b[32m+ ${key}: ${u}\x1b[0m`); }
        else console.log(`• already present: ${u}`);
      }
    };
    if (addPlaylists.length) push("playlists", addPlaylists, isValidPlaylistUrl);
    if (addChannels.length) push("channels", addChannels, isValidChannelUrl);
    if (addChannelPlaylists.length) push("channelPlaylists", addChannelPlaylists, isValidChannelUrl);

    if (flag("--validate")) {
      const res = ConfigSchema.safeParse(config);
      const problems = crossValidate(config);
      if (!res.success) {
        console.error(`\x1b[31m❌ Invalid configuration:\x1b[0m\n${res.error.issues.map(i => `   • ${i.path.join(".") || "(root)"}: ${i.message}`).join("\n")}`);
        rl.close(); process.exit(1);
      }
      console.log(`\x1b[32m✅ ${CONFIG_PATH} is valid against ${SCHEMA_NAME}.\x1b[0m`);
      if (problems.length) { console.log(`\x1b[33m⚠️  Notes:\x1b[0m`); problems.forEach(p => console.log(`   • ${p}`)); }
      rl.close(); return;
    }

    if (flag("--doctor")) { const ok = await doctor(config); rl.close(); process.exit(ok ? 0 : 1); }

    if (flag("--print")) { console.log(JSON.stringify(config, null, 2)); rl.close(); return; }

    if (mutated) {
      if (flag("--save")) { await saveConfig(config); rl.close(); return; }
      await saveConfig(config);
      rl.close(); return;
    }

    await mainMenu(config);
  } catch (e) {
    console.error(`\n\x1b[31m❌ Unexpected error: ${(e as Error).message}\x1b[0m`);
    if (process.env.DEBUG) console.error(e);
    rl.close();
    process.exit(1);
  }
}

main();
